def validate_params(words, param):
    if not isinstance(words, list):
        raise TypeError("words must be a list of strings")
    if isinstance(param, bool) or not isinstance(param, int):
        raise TypeError("capacity must be an integer")
    if param < 1:
        err = "capacity must be at least 1, got {}".format(param)
        raise ValueError(err)
    for idx, elem in enumerate(words):
        if not isinstance(elem, str):
            raise TypeError("words[{}] is not a string".format(idx))
        val = len(elem)
        if val > param:
            err = "words[{}] of length {} exceeds capacity {}".format(idx, val, param)
            raise ValueError(err)


def normalize_words(raw):
    res = []
    for elem in raw:
        tmp = elem.strip()
        if tmp:
            res.append(tmp)
    return res


def paginate_text(words, capacity):
    res = []
    buf = []
    cnt = 0
    pos = 0
    for idx in range(len(words)):
        curr = words[idx]
        num = len(curr)
        if buf:
            tmp = pos + 1 + num
        else:
            tmp = num
        if buf and tmp > capacity:
            msg = " ".join(buf)
            res.append(msg)
            cnt += len(msg)
            buf = []
            tmp = num
        buf.append(curr)
        pos = tmp
    if buf:
        msg = " ".join(buf)
        res.append(msg)
        cnt += len(msg)
    return res, cnt


def run_pagination(cfg):
    words = normalize_words(cfg["words"])
    param = cfg["capacity"]
    validate_params(words, param)
    return paginate_text(words, param)


def main():
    cfg = {"words": ["The", "quick", "brown", "fox", "jumps"], "capacity": 10}
    print(run_pagination(cfg))


if __name__ == "__main__":
    main()

