def _validate(readings, param):
    if not isinstance(readings, (list, tuple)):
        raise TypeError("readings must be a list or tuple")
    for idx in range(len(readings)):
        elem = readings[idx]
        if isinstance(elem, bool) or not isinstance(elem, (int, float)):
            msg = "reading at index {} is not numeric".format(idx)
            raise TypeError(msg)
    if isinstance(param, bool) or not isinstance(param, (int, float)):
        raise TypeError("threshold must be numeric")
    if param < 0:
        raise ValueError("threshold must be non-negative")


def aggregate_readings(readings, threshold):
    _validate(readings, threshold)
    buf = []
    cnt = 0
    pos = []
    prev = None
    for idx in range(len(readings)):
        curr = readings[idx]
        if prev is None:
            prev = curr
            buf.append(curr)
            continue
        tmp = abs(curr - prev)
        if tmp > threshold:
            cnt += 1
            pos.append(idx)
        else:
            prev = curr
            buf.append(curr)
    return buf, cnt, pos


def parse_readings(text):
    res = []
    for pos, chunk in enumerate(text.split(",")):
        stripped = chunk.strip()
        if not stripped:
            raise ValueError("empty field at position {}".format(pos))
        try:
            num = float(stripped)
        except ValueError as err:
            raise ValueError("bad field at position {}".format(pos)) from err
        if num.is_integer():
            val = int(num)
        else:
            val = num
        res.append(val)
    return res


def main():
    cfg = {"source": "10, 15, 50, 18, 20", "threshold": 20}
    samples = parse_readings(cfg["source"])
    ctx = aggregate_readings(samples, cfg["threshold"])
    print(ctx)


if __name__ == "__main__":
    main()

