def join_continuations(lines):
    """Merge lines ending in a backslash with the line that follows them."""
    res = []
    buf = ''
    for elem in lines:
        curr = elem.rstrip()
        if curr.endswith('\\'):
            buf += curr[:-1]
            continue
        res.append(buf + curr)
        buf = ''
    if buf:
        res.append(buf)
    return res


def unquote(val):
    """Strip a matching pair of double quotes; report unbalanced ones."""
    cnt = val.count('"')
    if cnt == 2 and val.startswith('"') and val.endswith('"'):
        return val[1:-1], None
    if cnt % 2:
        return val, 'UNTERMINATED_QUOTE'
    return val, None


def format_error(code, num):
    """Build the failure text for a rejected line."""
    return '%s (line %d)' % (code, num)


def parse_settings(lines):
    cfg = {}
    err = []
    for idx, elem in enumerate(join_continuations(lines)):
        num = idx + 1
        tmp = elem.strip()
        if not tmp or tmp.startswith('#') or tmp.startswith(';'):
            continue
        pos = tmp.find('=')
        if pos < 0:
            err.append(format_error('MISSING_EQUALS', num))
            continue
        param = tmp[:pos].strip()
        if not param:
            err.append(format_error('MISSING_NAME', num))
            continue
        val, msg = unquote(tmp[pos + 1:].strip())
        if msg is not None:
            err.append(format_error(msg, num))
            continue
        prev = cfg.get(param)
        if prev is not None and prev != val:
            err.append(format_error('DUPLICATE_NAME', num))
        cfg[param] = val
    return cfg, err


def main():
    res = parse_settings(['host=localhost', 'port=80', 'badline'])
    print(res)


if __name__ == '__main__':
    main()

