def make_cfg(grid_width, grid_height):
    cfg = {"width": grid_width, "height": grid_height}
    for param in ("width", "height"):
        val = cfg[param]
        if not isinstance(val, int) or isinstance(val, bool) or val <= 0:
            raise ValueError("grid %s must be a positive integer, got %r" % (param, val))
    return cfg


def coerce_pair(elem, ctx):
    try:
        num = len(elem)
    except TypeError:
        raise ValueError("%s is not a coordinate pair: %r" % (ctx, elem))
    if num != 2:
        msg = "%s must have exactly 2 components, got %d" % (ctx, num)
        raise ValueError(msg)
    res = []
    for val in elem:
        if not isinstance(val, int) or isinstance(val, bool):
            raise ValueError("%s has a non-integer component: %r" % (ctx, val))
        res.append(val)
    return (res[0], res[1])


def normalize_obstacles(obstacles):
    buf = set()
    for idx, elem in enumerate(obstacles):
        buf.add(coerce_pair(elem, "obstacle #%d" % idx))
    return buf


def in_bounds(cfg, pos):
    x, y = pos
    return 0 <= x < cfg["width"] and 0 <= y < cfg["height"]


def validate_path(grid_width, grid_height, obstacles, moves):
    cfg = make_cfg(grid_width, grid_height)
    blocked = normalize_obstacles(obstacles)
    curr = (0, 0)
    if curr in blocked:
        return (False, curr, 0)
    cnt = 0
    for idx, param in enumerate(moves):
        elem = coerce_pair(param, "move #%d" % idx)
        prev = curr
        curr = (prev[0] + elem[0], prev[1] + elem[1])
        if curr in blocked or not in_bounds(cfg, curr):
            return (False, prev, cnt)
        cnt += 1
    return (True, curr, cnt)


def main():
    obstacles = {(2, 1), (0, 3), (4, 4)}
    safe_moves = [(1, 0), (1, 0), (1, 0), (0, 1)]
    res = validate_path(5, 5, obstacles, safe_moves)
    print(res)
    hazard_moves = [(0, 1), (1, 0), (1, 0), (1, 0), (0, 1)]
    tmp = validate_path(5, 5, obstacles, hazard_moves)
    print(tmp)


if __name__ == "__main__":
    main()

