DEFAULT_CFG = {"min_severity": 1, "keyword": "", "name": "unnamed"}


def check_entry(elem, idx):
    """Validate one raw log record and return a clean copy of it."""
    if not isinstance(elem, dict):
        raise TypeError("log #" + str(idx) + " is not a dictionary")
    for param in ("severity", "text"):
        if param not in elem:
            raise KeyError("log #" + str(idx) + " is missing '" + param + "'")
    val = elem["severity"]
    if isinstance(val, bool) or not isinstance(val, int):
        raise TypeError("log #" + str(idx) + " has a non-integer severity")
    msg = elem["text"]
    if not isinstance(msg, str):
        raise TypeError("log #" + str(idx) + " has a non-string text")
    return {"severity": val, "text": msg}


def sanitize(logs):
    res = []
    for idx, elem in enumerate(logs):
        res.append(check_entry(elem, idx))
    return res


def filter_logs(logs, min_severity, keyword):
    kept = []
    cnt = 0
    for elem in sanitize(logs):
        val = elem["severity"]
        msg = elem["text"]
        if val < min_severity or keyword not in msg:
            cnt += 1
            continue
        kept.append(msg)
    return kept, cnt


def build_report(kept, cnt, ctx):
    buf = ["source: " + ctx["name"]]
    num = len(kept) + cnt
    for idx, msg in enumerate(kept, start=1):
        pos = msg.find(ctx["keyword"])
        tmp = str(idx) + ". " + msg + " [hit@" + str(pos) + "]"
        buf.append(tmp)
    buf.append("kept " + str(len(kept)) + " of " + str(num) +
               ", dropped " + str(cnt))
    return "\n".join(buf)


def main():
    cfg = dict(DEFAULT_CFG)
    cfg.update({"min_severity": 2, "keyword": "disk", "name": "node-07"})
    logs = [
        {"severity": 3, "text": "disk usage at 91 percent"},
        {"severity": 1, "text": "disk scrub finished"},
        {"severity": 4, "text": "cpu temperature high"},
    ]
    try:
        res = filter_logs(logs, cfg["min_severity"], cfg["keyword"])
    except (TypeError, KeyError) as err:
        print("input rejected:", err)
        return
    print(res)
    ctx = {"name": cfg["name"], "keyword": cfg["keyword"]}
    print(build_report(res[0], res[1], ctx))


if __name__ == "__main__":
    main()

