def _type_msg(param, val):
    """Message describing a value that should have been an int."""
    return "{} must be an int, got {}".format(param, type(val).__name__)


def validate(sequence, window):
    """Return a message describing bad input, or None when the input is sane."""
    if isinstance(window, bool) or not isinstance(window, int):
        return _type_msg("window", window)
    if window < 1:
        return "window must be at least 1, got {}".format(window)
    for idx, elem in enumerate(sequence):
        if isinstance(elem, bool) or not isinstance(elem, int):
            return "sequence[{}]: {}".format(idx, _type_msg("element", elem))
    if window > len(sequence):
        return "window {} exceeds sequence length {}".format(window, len(sequence))
    return None


def maximum(buf):
    """Maximum of a non-empty slice, scanned element by element."""
    curr = buf[0]
    for elem in buf[1:]:
        if elem > curr:
            curr = elem
    return curr


def sliding_maximum(sequence, window):
    """Maximums of every window-long slice, plus the offset of each slice."""
    err = validate(sequence, window)
    if err is not None:
        raise ValueError(err)

    buf = list(sequence)
    cnt = len(buf) - window + 1
    res = []
    offsets = []
    for pos in range(cnt):
        tmp = buf[pos:pos + window]
        res.append(maximum(tmp))
        offsets.append(pos)
    return res, offsets


def main():
    res = sliding_maximum([1, 3, -1, -3, 5, 3, 6, 7], 3)
    print(res)


if __name__ == "__main__":
    main()

