STATE_CFG = {
    'IDLE': {'START': 'RUNNING'},
    'RUNNING': {'STOP': 'IDLE'},
}

KNOWN_COMMANDS = ('START', 'STOP')


def normalize_commands(commands):
    """Validate and canonicalise the raw command sequence."""
    res = []
    for idx, elem in enumerate(commands):
        if not isinstance(elem, str):
            msg = 'command at index {} is not a string: {!r}'.format(idx, elem)
            raise TypeError(msg)
        tmp = elem.strip().upper()
        if tmp not in KNOWN_COMMANDS:
            msg = 'unknown command at index {}: {!r}'.format(idx, elem)
            raise ValueError(msg)
        res.append(tmp)
    return res


def process_commands(commands):
    """Run the state machine and report (state, transitions, faults)."""
    curr = 'IDLE'
    cnt = 0
    faults = []
    for param in normalize_commands(commands):
        ctx = STATE_CFG[curr]
        if param in ctx:
            curr = ctx[param]
            cnt += 1
        else:
            faults.append('INVALID_' + param)
    return curr, cnt, faults


def fault_summary(faults):
    """Collapse the faults list into a compact 'NAME xN' description."""
    num = {}
    for err in faults:
        num[err] = num.get(err, 0) + 1
    buf = []
    for err, val in sorted(num.items()):
        buf.append('{} x{}'.format(err, val))
    if not buf:
        return 'none'
    return ', '.join(buf)


def format_report(state, cnt, faults):
    """Render a human readable summary of one machine run."""
    buf = [
        'final state: ' + state,
        'transitions: {}'.format(cnt),
    ]
    msg = fault_summary(faults)
    buf.append('faults: ' + msg)
    return '\n'.join(buf)


def main():
    cmds = ['START', 'START', 'STOP']
    res = process_commands(cmds)
    print(res)
    print(format_report(*res))


