STATE_CONFIGURATION = {
    'IDLE': {'START': 'RUNNING'},
    'RUNNING': {'STOP': 'IDLE'},
}

KNOWN_COMMANDS = ('START', 'STOP')


def normalize_commands(commands):
    """Validate and canonicalise the raw command sequence."""
    result = []
    for index, element in enumerate(commands):
        if not isinstance(element, str):
            message = 'command at index {} is not a string: {!r}'.format(index, element)
            raise TypeError(message)
        temporary = element.strip().upper()
        if temporary not in KNOWN_COMMANDS:
            message = 'unknown command at index {}: {!r}'.format(index, element)
            raise ValueError(message)
        result.append(temporary)
    return result


def process_commands(commands):
    """Run the state machine and report (state, transitions, faults)."""
    current = 'IDLE'
    count = 0
    faults = []
    for parameter in normalize_commands(commands):
        context = STATE_CONFIGURATION[current]
        if parameter in context:
            current = context[parameter]
            count += 1
        else:
            faults.append('INVALID_' + parameter)
    return current, count, faults


def fault_summary(faults):
    """Collapse the faults list into a compact 'NAME xN' description."""
    number = {}
    for error in faults:
        number[error] = number.get(error, 0) + 1
    buffer = []
    for error, value in sorted(number.items()):
        buffer.append('{} x{}'.format(error, value))
    if not buffer:
        return 'none'
    return ', '.join(buffer)


def format_report(state, count, faults):
    """Render a human readable summary of one machine run."""
    buffer = [
        'final state: ' + state,
        'transitions: {}'.format(count),
    ]
    message = fault_summary(faults)
    buffer.append('faults: ' + message)
    return '\n'.join(buffer)


def main():
    cmds = ['START', 'START', 'STOP']
    result = process_commands(cmds)
    print(result)
    print(format_report(*result))


if __name__ == '__main__':
    main()

