    if num == 0:
        raise ValueError("matrix rows must not be empty")
    for idx, row in enumerate(matrix):
        if len(row) != num:
            msg = "row {} has length {}, expected {}".format(idx, len(row), num)
            raise ValueError(msg)
    return len(matrix), num


def parse_params(cfg):
    res = []
    for param in ("start_r", "start_c", "size"):
        val = cfg[param]
        if not isinstance(val, int):
            raise TypeError(param + " must be an integer")
        res.append(val)
    if res[-1] <= 0:
        raise ValueError("size must be positive")
    return tuple(res)


def extract_subgrid(matrix, start_r, start_c, size):
    rows, cols = matrix_dims(matrix)
    buf = []
    cnt = 0
    for idx in range(size):
        curr = matrix[(start_r + idx) % rows]
        for pos in range(size):
            buf.append(curr[(start_c + pos) % cols])
            cnt += 1
    return buf, cnt


def count_wraps(start, size, limit):
    cnt = 0
    prev = start % limit
    for idx in range(1, size):
        curr = (start + idx) % limit
        if curr < prev:
            cnt += 1
        prev = curr
    return cnt


def render_grid(buf, size):
    lines = []
    for pos in range(0, len(buf), size):
        tmp = [str(elem) for elem in buf[pos:pos + size]]
        lines.append(" ".join(tmp))
    return "\n".join(lines)


