FRAME_START = 255


def option(cfg, param, default):
    """Fetch a formatting option, falling back to a default."""
    if param in cfg:
        return cfg[param]
    return default


def normalize(stream):
    """Turn an arbitrary sequence of readings into a list of plain ints."""
    out = []
    for idx, elem in enumerate(stream):
        if isinstance(elem, bool) or not isinstance(elem, int):
            raise TypeError("reading at index %d is not an integer: %r" % (idx, elem))
        out.append(elem)
    return out


def parse(stream):
    """Extract 255-framed payloads; return (payloads, errors)."""
    data = normalize(stream)
    num = len(data)
    res = []
    ctx = []
    pos = 0
    while pos < num:
        curr = data[pos]
        if curr != FRAME_START:
            pos += 1
            continue
        if pos + 1 >= num:
            ctx.append("frame at position %d has no length byte" % pos)
            break
        cnt = data[pos + 1]
        if cnt < 0:
            ctx.append("frame at position %d declares negative length %d" % (pos, cnt))
            break
        buf = data[pos + 2:pos + 2 + cnt]
        if len(buf) < cnt:
            ctx.append("frame at position %d wants %d bytes, only %d available"
                       % (pos, cnt, len(buf)))
            break
        res.append(buf)
        pos += 2 + cnt
    return res, ctx


def checksum(buf):
    """Low byte of the payload sum, as carried by this sensor protocol."""
    total = 0
    for val in buf:
        total = (total + val) & 0xFF
    return total


def summarize(payloads, errors, cfg):
    """Render a human readable report of a parse() result."""
    sep = option(cfg, "sep", " ")
    fmt = option(cfg, "fmt", "d")
    lines = []
    prev = None
    for idx, buf in enumerate(payloads):
        tmp = []
        for val in buf:
            tmp.append(format(val, fmt))
        msg = "frame %d: %d bytes [%s] sum=%d" % (idx, len(buf), sep.join(tmp), checksum(buf))
        if prev is not None:
            msg += " (delta %+d)" % (len(buf) - prev)
        lines.append(msg)
        prev = len(buf)
    for err in errors:
        lines.append("error: " + err)
    if not lines:
        lines.append("no frames found")
    return "\n".join(lines)


def main():
    stream = [0, 255, 3, 10, 20, 30, 7, 255, 2, 40, 50, 255, 4, 60, 70]
    cfg = {"sep": ", ", "fmt": "02X"}
    res, ctx = parse(stream)
    print(summarize(res, ctx, cfg))


if __name__ == "__main__":
    main()

