def decode(text):
    res = []
    pos = 0
    while pos < len(text):
        curr = text[pos]
        if curr == '%':
            tmp = text[pos + 1:pos + 3]
            if len(tmp) < 2:
                raise ValueError("truncated escape at position %d" % pos)
            try:
                num = int(tmp, 16)
            except ValueError as err:
                raise ValueError("bad escape '%%%s': %s" % (tmp, err))
            res.append(chr(num))
            pos += 3
        elif curr == '+':
            res.append(' ')
            pos += 1
        else:
            res.append(curr)
            pos += 1
    return ''.join(res)


def parse(query):
    if not isinstance(query, str):
        raise TypeError("query must be a string")
    if query.startswith('?'):
        query = query[1:]
    if query:
        query += '&'
    res = []
    buf = ''
    prev = ''
    ctx = 'key'
    pos = 0
    while pos < len(query):
        curr = query[pos]
        if curr == '=' and ctx == 'key':
            prev = buf
            buf = ''
            ctx = 'value'
        elif curr == '&':
            if ctx == 'key':
                prev = buf
                buf = ''
            key = decode(prev)
            val = decode(buf)
            res.append((key, val))
            buf = ''
            prev = ''
            ctx = 'key'
        else:
            buf += curr
        pos += 1
    cnt = len(res)
    return (res, cnt)


