    width = max([len(p[0]) for p in pairs] or [0])
    lines = ["%d pair(s) parsed" % cnt]
    for idx in range(len(pairs)):
        elem = pairs[idx]
        lines.append("  %s -> %r" % (elem[0].ljust(width), elem[1]))
    return "\n".join(lines)


