OPS_CFG = {
    "digits": "0123456789",
    "decimal": ".",
    "operators": "+-*/%^",
    "parens": "()",
    "skip": " \t\n",
}


def tokenize(source):
    cfg = OPS_CFG
    res = []
    idx = 0
    cnt = 0
    ctx = {"previous_number": False}
    while idx < len(source):
        curr = source[idx]
        if curr in cfg["skip"]:
            idx += 1
            continue
        if curr in cfg["digits"] or curr == cfg["decimal"]:
            buf = ""
            while idx < len(source):
                elem = source[idx]
                if elem not in cfg["digits"] and elem != cfg["decimal"]:
                    break
                buf += elem
                idx += 1
            tmp = buf.count(cfg["decimal"])
            if tmp > 1:
                pos = idx - len(buf)
                msg = "malformed number %r starting at position %d" % (buf, pos)
                raise ValueError(msg)
            num = float(buf) if tmp else int(buf)
            res.append(("number", num))
            ctx["previous_number"] = True
        elif curr in cfg["operators"] or curr in cfg["parens"]:
            if curr == "(" and ctx["previous_number"]:
                res.append(("op", "*"))
                cnt += 1
            res.append(("op", curr))
            ctx["previous_number"] = curr == ")"
            idx += 1
        else:
            msg = "unexpected character %r at position %d" % (curr, idx)
            raise ValueError(msg)
        cnt += 1
    return res, cnt


def validate(tokens):
    prev = "start"
    for pos in range(len(tokens)):
        curr = tokens[pos][0]
        if curr == "number" and prev == "number":
            msg = "two numbers in a row at unit %d" % pos
            raise ValueError(msg)
        prev = curr


def summarize(tokens):
    res = {"numbers": 0, "operators": 0, "largest": None}
    for elem in tokens:
        if elem[0] == "number":
            val = elem[1]
            res["numbers"] += 1
            if res["largest"] is None or val > res["largest"]:
                res["largest"] = val
        else:
            res["operators"] += 1
    return res


def render(tokens, param=" "):
    buf = []
    prev = None
    for elem in tokens:
        text = str(elem[1])
        if prev is not None and prev != "(" and text != ")":
            buf.append(param)
        buf.append(text)
        prev = text
    return "".join(buf)


def main():
    samples = ["12+3*4", "7.5 - (2 * 8)", "3(4+1)", "3 4 + 1", "5 $ 2", "1.2.3+4"]
    for src in samples:
        try:
            tmp = tokenize(src)
            res = tmp[0]
            cnt = tmp[1]
            validate(res)
        except ValueError as err:
            print("%-16r rejected: %s" % (src, err))
            continue
        info = summarize(res)
        print("%-16r %s | units=%d numbers=%d ops=%d largest=%s"
              % (src, render(res), cnt, info["numbers"], info["operators"], info["largest"]))


if __name__ == "__main__":
