def split(line):
    res = []
    buf = []
    ctx = False
    cnt = 0
    idx = 0
    size = len(line)
    while idx < size:
        elem = line[idx]
        if elem == '"':
            if ctx and idx + 1 < size and line[idx + 1] == '"':
                buf.append('"')
                idx += 2
                continue
            ctx = not ctx
        elif elem == ',' and not ctx:
            val = "".join(buf)
            res.append(val)
            buf.clear()
            cnt += 1
        else:
            buf.append(elem)
        idx += 1
    if ctx:
        raise ValueError("unterminated quote in field %d" % (cnt + 1))
    res.append("".join(buf))
    cnt += 1
    return res


def parse_rows(lines, cfg):
    rows = []
    errs = []
    for num, raw in enumerate(lines, 1):
        tmp = raw.rstrip("\r\n")
        if not tmp.strip():
            continue
        try:
            fields = split(tmp)
        except ValueError as err:
            errs.append("line %d: %s" % (num, err))
            continue
        if cfg["strip"]:
            fields = [val.strip() for val in fields]
        if len(fields) != cfg["columns"]:
            msg = "line %d: expected %d fields, got %d" % (num, cfg["columns"], len(fields))
            errs.append(msg)
            continue
        missing = [pos for pos in cfg["required"] if not fields[pos]]
        if missing:
            errs.append("line %d: empty required column(s) %s" % (num, missing))
            continue
        rows.append(fields)
    return rows, errs


def pad(param, width):
    return param + " " * (width - len(param))


def render(rows, cfg):
    widths = [0] * cfg["columns"]
    for row in rows:
        for idx, field in enumerate(row):
            widths[idx] = max(widths[idx], len(field))
    out = []
    prev = None
    for row in sorted(rows):
        curr = row[0]
        if curr != prev:
            out.append(curr + ":")
            prev = curr
        cells = [pad(row[pos], widths[pos]) for pos in range(1, cfg["columns"])]
        out.append("  " + " | ".join(cells).rstrip())
    return "\n".join(out)


def main():
    cfg = {"columns": 3, "strip": True, "required": [0, 1]}
    data = [
        'fruit,apple,"sweet, crisp"',
