def validate_node(param):
    """Check that a node is a sorted list of integers big enough to divide."""
    if not isinstance(param, list):
        raise TypeError("a node must be a list")
    if len(param) < 3:
        raise ValueError("a node needs at least three elements to divide")
    prev = None
    for curr in param:
        if not isinstance(curr, int) or isinstance(curr, bool):
            raise TypeError("node elements must be integers")
        if prev is not None and curr < prev:
            raise ValueError("node elements must be sorted")
        prev = curr


def divide(elements):
    """Split an overfull node into (left half, promoted parent, right half)."""
    validate_node(elements)
    num = len(elements)
    idx = num // 2
    val = elements[idx]
    buf = []
    tmp = []
    for pos in range(num):
        elem = elements[pos]
        if pos < idx:
            buf.append(elem)
        elif pos > idx:
            tmp.append(elem)
    res = []
    res.append(buf)
    res.append(tmp)
    return (res[0], val, res[1])


def describe(split):
    """Render one split as a readable line."""
    left, mid, right = split
    msg = "left=%s -> parent=%d <- right=%s" % (left, mid, right)
    return msg


def split_overfull(nodes, cfg):
    """Divide every node exceeding the configured capacity."""
    capacity = cfg["capacity"]
    ctx = {"parents": [], "leaves": [], "errors": [], "log": []}
    cnt = 0
    for node in nodes:
        if len(node) <= capacity:
            ctx["leaves"].append(node)
            continue
        try:
            res = divide(node)
        except (TypeError, ValueError) as err:
            ctx["errors"].append(str(err))
            continue
        ctx["parents"].append(res[1])
        ctx["leaves"].append(res[0])
        ctx["leaves"].append(res[2])
        ctx["log"].append(describe(res))
        cnt += 1
    ctx["splits"] = cnt
    return ctx


def main():
    cfg = {"capacity": 3}
    nodes = [[1, 2, 3, 4, 5], [7, 8], [10, 20, 30, 40, 50, 60], [9, 4, 1]]
    ctx = split_overfull(nodes, cfg)
    for msg in ctx["log"]:
        print(msg)
    print("splits performed: %d" % ctx["splits"])
    print("promoted parents: %s" % ctx["parents"])
    print("resulting leaves: %s" % ctx["leaves"])
    for err in ctx["errors"]:
        print("skipped node: %s" % err)


if __name__ == "__main__":
    main()

