import sys


def strip(markup):
    """Remove all tags from a hypertext string; return (text, tags_removed)."""
    if not isinstance(markup, str):
        raise TypeError("markup must be a string")
    buf = []
    ctx = False
    cnt = 0
    pos = 0
    num = len(markup)
    while pos < num:
        elem = markup[pos]
        if elem == '<':
            ctx = True
        elif elem == '>':
            if ctx:
                cnt += 1
                ctx = False
            else:
                buf.append(elem)
        elif not ctx:
            buf.append(elem)
        pos += 1
    res = ''.join(buf)
    return res, cnt


def normalize(text):
    """Collapse runs of whitespace into single spaces and trim the edges."""
    tmp = []
    prev = ' '
    for curr in text:
        if curr.isspace():
            if not prev.isspace():
                tmp.append(' ')
        else:
            tmp.append(curr)
        prev = curr
    return ''.join(tmp).strip()


def truncate(val, param):
    if len(val) <= param:
        return val
    return val[:param - 3] + '...'


def load_sources(paths):
    docs = []
    for param in paths:
        try:
            with open(param, encoding='utf-8') as handle:
                docs.append((param, handle.read()))
        except OSError as err:
            msg = "cannot read {}: {}".format(param, err)
            print(msg, file=sys.stderr)
    return docs


def main(argv):
    cfg = {'collapse': True, 'width': 60}
