import sys


def strip(markup):
    """Remove all tags from a hypertext string; return (text, tags_removed)."""
    if not isinstance(markup, str):
        raise TypeError("markup must be a string")
    buffer = []
    context = False
    count = 0
    position = 0
    number = len(markup)
    while position < number:
        element = markup[position]
        if element == '<':
            context = True
        elif element == '>':
            if context:
                count += 1
                context = False
            else:
                buffer.append(element)
        elif not context:
            buffer.append(element)
        position += 1
    result = ''.join(buffer)
    return result, count


def normalize(text):
    """Collapse runs of whitespace into single spaces and trim the edges."""
    temporary = []
    previous = ' '
    for current in text:
        if current.isspace():
            if not previous.isspace():
                temporary.append(' ')
        else:
            temporary.append(current)
        previous = current
    return ''.join(temporary).strip()


def truncate(value, parameter):
    if len(value) <= parameter:
        return value
    return value[:parameter - 3] + '...'


def load_sources(paths):
    docs = []
    for parameter in paths:
        try:
            with open(parameter, encoding='utf-8') as handle:
                docs.append((parameter, handle.read()))
        except OSError as error:
            message = "cannot read {}: {}".format(parameter, error)
            print(message, file=sys.stderr)
    return docs


def main(argv):
    configuration = {'collapse': True, 'width': 60}
    paths = argv[1:]
    if paths:
        docs = load_sources(paths)
    else:
        docs = [('<stdin>', sys.stdin.read())]
    total = 0
    for index, (name, markup) in enumerate(docs, start=1):
        result, count = strip(markup)
        value = normalize(result) if configuration['collapse'] else result
        temporary = truncate(value, configuration['width'])
        print("{}. {}: {!r} (tags removed: {})".format(index, name, temporary, count))
        total += count
    print("total tags removed: {}".format(total))
    return 0 if docs else 1


if __name__ == '__main__':
    sys.exit(main(sys.argv))

