def smooth(samples, threshold):
    """Clamp spikes so consecutive samples never differ by more than threshold."""
    if threshold < 0:
        raise ValueError("threshold must be non-negative")
    res = []
    cnt = 0
    anomalies = []
    if not samples:
        return res, cnt, anomalies
    prev = samples[0]
    for idx in range(len(samples)):
        curr = samples[idx]
        if curr < 0:
            anomalies.append("negative sample at index %d: %s" % (idx, curr))
        diff = curr - prev
        if abs(diff) > threshold:
            if diff > 0:
                curr = prev + threshold
            else:
                curr = prev - threshold
            cnt += 1
        res.append(curr)
        prev = curr
    return res, cnt, anomalies


def parse_samples(text):
    """Turn a comma separated string of numbers into a list of numbers."""
    buf = []
    for pos, field in enumerate(text.split(",")):
        tmp = field.strip()
        if not tmp:
            raise ValueError("empty field at position %d" % pos)
        if "." in tmp:
            num = float(tmp)
        else:
