import random

DEFAULT_SETTINGS = {"max": 3, "backoff": 2, "seed": None}


def parse_settings(settings):
    """Merge user settings over the defaults and reject unusable values."""
    cfg = dict(DEFAULT_SETTINGS)
    for param in settings:
        if param not in cfg:
            msg = f"unknown setting: {param!r}"
            raise ValueError(msg)
        cfg[param] = settings[param]
    if cfg["max"] < 1:
        raise ValueError("max attempts must be at least 1")
    if cfg["backoff"] < 1:
        raise ValueError("backoff multiplier must be at least 1")
    return cfg


def validate_task(elem):
    """Check a single (name, failure rate) pair and return its two fields."""
    if not isinstance(elem, tuple) or len(elem) != 2:
        raise ValueError(f"each task must be a (name, rate) pair: {elem!r}")
    name, rate = elem
    if not isinstance(name, str) or not name:
        raise ValueError(f"task name must be a non-empty string: {name!r}")
    if not isinstance(rate, int) or not 0 <= rate <= 100:
        raise ValueError(f"failure rate must be 0..100: {rate!r}")
    return name, rate


def execute(tasks, settings):
    cfg = parse_settings(settings)
    rng = random.Random(cfg["seed"])
    mult = cfg["backoff"]
    ctx = {"wait": 1}
    log = []
    cnt = 0
    for elem in tasks:
        name, rate = validate_task(elem)
        for idx in range(cfg["max"]):
            val = rng.randrange(100)
            if val >= rate:
                log.append(f"{name} success")
                cnt += 1
                break
            tmp = ctx["wait"]
            log.append(f"{name} attempt {idx + 1} failed, waiting {tmp}s")
            ctx["wait"] = tmp * mult
    res = (log, cnt, ctx)
    return res


def format_report(entries, finished, ctx):
    """Render a run as numbered log lines plus a two line summary."""
    buf = []
    for pos, text in enumerate(entries, 1):
        buf.append(f"{pos:>2}. {text}")
    num = len(entries)
    buf.append(f"{finished} operations finished, {num} log lines")
    buf.append(f"final wait: {ctx['wait']}s")
    return "\n".join(buf)


def main():
    tasks = [("upload", 0), ("index", 70), ("notify", 40)]
    scenarios = [
        {"max": 3, "backoff": 2, "seed": 7},
        {"max": 5, "backoff": 3, "seed": 11},
    ]
    prev = None
    for settings in scenarios:
        print(f"--- settings: {settings}")
        try:
            res = execute(tasks, settings)
        except ValueError as err:
            print(f"cannot run scenario: {err}")
            continue
        print(format_report(*res))
        curr = res[2]["wait"]
        if prev is not None:
            print(f"wait time changed from {prev}s to {curr}s")
        prev = curr


if __name__ == "__main__":
    main()

