        raise ValueError(f"failure rate must be 0..100: {rate!r}")
    return name, rate


def execute(tasks, settings):
    configuration = parse_settings(settings)
    rng = random.Random(configuration["seed"])
    mult = configuration["backoff"]
    context = {"wait": 1}
    log = []
    count = 0
    for element in tasks:
        name, rate = validate_task(element)
        for index in range(configuration["max"]):
            value = rng.randrange(100)
            if value >= rate:
                log.append(f"{name} success")
                count += 1
                break
            temporary = context["wait"]
            log.append(f"{name} attempt {index + 1} failed, waiting {temporary}s")
            context["wait"] = temporary * mult
    result = (log, count, context)
    return result


def format_report(entries, finished, context):
    """Render a run as numbered log lines plus a two line summary."""
    buffer = []
    for position, text in enumerate(entries, 1):
        buffer.append(f"{position:>2}. {text}")
    number = len(entries)
    buffer.append(f"{finished} operations finished, {number} log lines")
    buffer.append(f"final wait: {context['wait']}s")
    return "\n".join(buffer)


def main():
    tasks = [("upload", 0), ("index", 70), ("notify", 40)]
    scenarios = [
        {"max": 3, "backoff": 2, "seed": 7},
        {"max": 5, "backoff": 3, "seed": 11},
    ]
    previous = None
    for settings in scenarios:
        print(f"--- settings: {settings}")
        try:
            result = execute(tasks, settings)
        except ValueError as error:
            print(f"cannot run scenario: {error}")
            continue
        print(format_report(*result))
        current = result[2]["wait"]
        if previous is not None:
            print(f"wait time changed from {previous}s to {current}s")
        previous = current


if __name__ == "__main__":
    main()

