def validate(elem, idx):
    if not isinstance(elem, dict):
        raise TypeError("object %d is not a dictionary" % idx)
    for param in REQUIRED_KEYS:
        if param not in elem:
            raise KeyError("object %d is missing key '%s'" % (idx, param))
        val = elem[param]
        if not isinstance(val, (int, float)) or isinstance(val, bool):
            raise TypeError("object %d has non-numeric '%s'" % (idx, param))


def update(objects, delta):
    res = []
    buf = []
    cnt = 0
    for idx, elem in enumerate(objects):
        validate(elem, idx)
        vx = float(elem["vx"])
        vy = float(elem["vy"])
        curr = float(elem["x"]) + vx * delta
        if curr < MIN_POS or curr > MAX_POS:
            vx = -vx * abs(float(elem["bounce"]))
            curr = MIN_POS if curr < MIN_POS else MAX_POS
            cnt += 1
        tmp = {"x": curr, "y": float(elem["y"]) + vy * delta,
               "vx": vx, "vy": vy, "bounce": elem["bounce"]}
        res.append(tmp)
        for param in ("vx", "vy"):
            num = tmp[param]
            if abs(num) > SPEED_LIMIT:
                buf.append("object %d: %s of %.1f exceeds speed limit" % (idx, param, num))
    return res, cnt, buf


def simulate(objects, cfg):
    ctx = [dict(elem) for elem in objects]
    total = 0
    notes = []
    for _ in range(cfg["steps"]):
        ctx, cnt, extra = update(ctx, cfg["delta"])
        total += cnt
        notes.extend(extra)
