DEFAULT_CFG = {"list": "ul", "item": "li", "para": "p"}

ESCAPES = {"&": "&amp;", "<": "&lt;", ">": "&gt;"}

DOCS = [
    ("simple", ["* item", "text"]),
    ("mixed", ["intro", "* first", "* second & more", "", "outro <b>"]),
    ("list only", ["* alpha", "* beta"]),
]


def escape(text):
    tmp = text
    for elem, val in ESCAPES.items():
        tmp = tmp.replace(elem, val)
    return tmp


def item_text(line):
    pos = line.index("*")
    return line[pos + 1:].strip()


def wrap(tag, param):
    return "<{0}>{1}</{0}>".format(tag, param)


def close_tag(tag):
    return "</{0}>".format(tag)


def render(lines, cfg=None):
    if cfg is None:
        cfg = DEFAULT_CFG
    for idx, elem in enumerate(lines):
        if not isinstance(elem, str):
            err = "line {0} is not a string: {1!r}".format(idx, elem)
            raise TypeError(err)
    buf = []
    cnt = 0
    curr = "none"
    for line in lines:
        tmp = line.strip()
        if tmp.startswith("*"):
            if curr != cfg["list"]:
                buf.append("<{0}>".format(cfg["list"]))
                cnt += 1
                curr = cfg["list"]
            buf.append(wrap(cfg["item"], escape(item_text(tmp))))
            cnt += 1
        elif tmp:
            if curr == cfg["list"]:
                buf.append(close_tag(cfg["list"]))
                cnt += 1
            buf.append(wrap(cfg["para"], escape(tmp)))
            cnt += 1
            curr = cfg["para"]
        else:
            if curr == cfg["list"]:
                buf.append(close_tag(cfg["list"]))
                cnt += 1
            curr = "none"
    if curr == cfg["list"]:
        buf.append(close_tag(cfg["list"]))
        cnt += 1
