def _validated_limits(limits):
    """Return a copy of the limits mapping with both entries checked."""
    cfg = {}
    for param in ("lines", "chars"):
        if param not in limits:
            msg = "missing limit: %s" % param
            raise KeyError(msg)
        val = limits[param]
        if not isinstance(val, int) or val < 1:
            raise ValueError("limit %r must be a positive int, got %r" % (param, val))
        cfg[param] = val
    return cfg


def paginate(words, limits):
    """Split words into pages of wrapped lines; return (pages, page_count)."""
    cfg = _validated_limits(limits)
    max_lines = cfg["lines"]
    max_chars = cfg["chars"]
    res = []
    buf = []
    tmp = []
    curr = 0
    cnt = 0
    for elem in words:
        param = str(elem)
        num = len(param)
        if tmp and curr + num > max_chars:
            buf.append(" ".join(tmp))
            tmp = []
            curr = 0
            if len(buf) == max_lines:
                res.append(buf)
                cnt += 1
                buf = []
        tmp.append(param)
        curr += num
    if tmp:
        buf.append(" ".join(tmp))
    if buf:
        res.append(buf)
        cnt += 1
    return res, cnt


