def _load_cfg(settings):
    cfg = {}
    for param in ("sync", "escape"):
        if param not in settings:
            raise KeyError(f"missing setting '{param}'")
        val = settings[param]
        if not isinstance(val, int) or not 0 <= val <= 255:
            err = f"setting '{param}' must be a byte value in 0..255"
            raise ValueError(err)
        cfg[param] = val
    if cfg["sync"] == cfg["escape"]:
        raise ValueError("sync and escape bytes must differ")
    return cfg


def frame(payloads, settings):
    cfg = _load_cfg(settings)
    res = []
    cnt = 0
    diagnostics = []
    for idx, payload in enumerate(payloads):
        if not payload:
            diagnostics.append(f"payload {idx} is empty; no sequence emitted")
            continue
        buf = [cfg["sync"]]
        checksum = 0
        for pos, val in enumerate(payload):
            if not isinstance(val, int) or not 0 <= val <= 255:
                raise ValueError(f"payload {idx} offset {pos} is not a byte")
            if val == cfg["sync"] or val == cfg["escape"]:
                buf.append(cfg["escape"])
                cnt += 1
            buf.append(val)
            checksum ^= val
        buf.append(checksum)
        res.append(buf)
    return res, cnt, diagnostics


def unframe(sequence, settings):
    cfg = _load_cfg(settings)
    if not sequence or sequence[0] != cfg["sync"]:
        raise ValueError("sequence does not start with the sync byte")
    out = []
    prev = None
    for curr in sequence[1:]:
        if prev == cfg["escape"]:
            out.append(curr)
            prev = None
            continue
        if curr == cfg["escape"]:
            prev = curr
            continue
        out.append(curr)
        prev = curr
    checksum = out.pop()
    tmp = 0
    for elem in out:
        tmp ^= elem
    if tmp != checksum:
        raise ValueError(f"checksum mismatch: expected {checksum}, computed {tmp}")
    return out


def render(sequences):
    res = []
    for idx, buf in enumerate(sequences):
        body = " ".join(f"{elem:02X}" for elem in buf)
        res.append(f"frame {idx}: {body} ({len(buf)} bytes)")
    return res


def main():
    ctx = {"sync": 0x7E, "escape": 0x7D}
    payloads = [[10, 20], [0x7E, 1, 0x7D], [], [255, 0, 0x7D]]
    sequences, cnt, diagnostics = frame(payloads, ctx)
    for line in render(sequences):
        print(line)
    print(f"escape operations: {cnt}")
    for msg in diagnostics:
        print(f"diagnostic: {msg}")
    for num, sequence in enumerate(sequences):
        recovered = unframe(sequence, ctx)
        print(f"frame {num} decodes to {recovered}")


if __name__ == "__main__":
    main()

