def merge(base, overrides):
    res = {}
    cnt = 0
    warns = []
    for key, val in base.items():
        if key not in overrides:
            res[key] = val
            continue
        new_value = overrides[key]
        if isinstance(val, dict) and isinstance(new_value, dict):
            merged, hits, notes = merge(val, new_value)
            res[key] = merged
            cnt += hits
            warns.extend(notes)
        elif isinstance(val, dict) or isinstance(new_value, dict):
            msg = "type mismatch for %r: %s vs %s" % (
                key, type(val).__name__, type(new_value).__name__)
            warns.append(msg)
            res[key] = val
        elif isinstance(new_value, (str, int)):
            res[key] = new_value
            cnt += 1
        else:
            res[key] = val
    return res, cnt, warns


def parse_assignment(text):
    pos = text.find("=")
    if pos < 0:
        return None, "missing '=' in %r" % text
    path = text[:pos].strip()
    raw = text[pos + 1:].strip()
    if not path:
        return None, "empty setting name in %r" % text
    if raw.lstrip("-").isdigit():
        tmp = {path.split(".")[-1]: int(raw)}
    else:
        tmp = {path.split(".")[-1]: raw}
    for elem in reversed(path.split(".")[:-1]):
        tmp = {elem: tmp}
    return tmp, None


def build_layers(args):
    layers = []
    errs = []
    for text in args:
        layer, err = parse_assignment(text)
        if err:
            errs.append(err)
        else:
            layers.append(layer)
    return layers, errs


def apply_layers(base, layers):
    cfg = base
    num = 0
    notes = []
    for layer in layers:
        cfg, hits, msgs = merge(cfg, layer)
        num += hits
        notes.extend(msgs)
    return cfg, num, notes


def flatten(settings, prefix=""):
    buf = []
    for key in sorted(settings):
        param = prefix + key
        val = settings[key]
        if isinstance(val, dict):
            buf.extend(flatten(val, param + "."))
        else:
            buf.append((param, val))
    return buf


def changes(base, merged):
