def merge(base, overrides):
    result = {}
    count = 0
    warns = []
    for key, value in base.items():
        if key not in overrides:
            result[key] = value
            continue
        new_value = overrides[key]
        if isinstance(value, dict) and isinstance(new_value, dict):
            merged, hits, notes = merge(value, new_value)
            result[key] = merged
            count += hits
            warns.extend(notes)
        elif isinstance(value, dict) or isinstance(new_value, dict):
            message = "type mismatch for %r: %s vs %s" % (
                key, type(value).__name__, type(new_value).__name__)
            warns.append(message)
            result[key] = value
        elif isinstance(new_value, (str, int)):
            result[key] = new_value
            count += 1
        else:
            result[key] = value
    return result, count, warns


def parse_assignment(text):
    position = text.find("=")
    if position < 0:
        return None, "missing '=' in %r" % text
    path = text[:position].strip()
    raw = text[position + 1:].strip()
    if not path:
        return None, "empty setting name in %r" % text
    if raw.lstrip("-").isdigit():
        temporary = {path.split(".")[-1]: int(raw)}
    else:
        temporary = {path.split(".")[-1]: raw}
    for element in reversed(path.split(".")[:-1]):
        temporary = {element: temporary}
    return temporary, None


def build_layers(args):
    layers = []
    errs = []
    for text in args:
        layer, error = parse_assignment(text)
        if error:
            errs.append(error)
        else:
            layers.append(layer)
    return layers, errs


def apply_layers(base, layers):
    configuration = base
    number = 0
    notes = []
    for layer in layers:
        configuration, hits, msgs = merge(configuration, layer)
        number += hits
        notes.extend(msgs)
    return configuration, number, notes


def flatten(settings, prefix=""):
    buffer = []
    for key in sorted(settings):
        parameter = prefix + key
        value = settings[key]
        if isinstance(value, dict):
            buffer.extend(flatten(value, parameter + "."))
        else:
            buffer.append((parameter, value))
    return buffer


def changes(base, merged):
    after = dict(flatten(merged))
    out = []
    for parameter, previous in flatten(base):
        current = after[parameter]
        if previous != current:
            out.append("%s: %r -> %r" % (parameter, previous, current))
    return out


def format_report(settings, number, warns):
    lines = ["settings:"]
    for index, pair in enumerate(flatten(settings), 1):
        lines.append("  %2d. %s = %s" % (index, pair[0], pair[1]))
    lines.append("overridden keys: %d" % number)
    for message in warns:
        lines.append("warning: " + message)
    return lines


def main():
    base = {
        "service": {"host": "localhost", "port": 8080, "tls": {"enabled": 0}},
        "limits": {"cpu": 2, "mem": 512},
        "debug": 0,
    }
    args = ["service.port=9090", "service.tls.enabled=1", "limits=fast", "debug"]
    layers, errs = build_layers(args)
    for error in errs:
        print("input error: " + error)
    context, total, warns = apply_layers(base, layers)
    for line in format_report(context, total, warns):
        print(line)
    print("changes:")
    for line in changes(base, context):
