def validate_readings(readings, window):
    """Reject inputs that the spike scan cannot handle."""
    if isinstance(window, bool) or not isinstance(window, int):
        raise ValueError("window must be an integer")
    if window < 1:
        raise ValueError("window must be at least 1")
    for idx in range(len(readings)):
        val = readings[idx]
        if isinstance(val, bool) or not isinstance(val, (int, float)):
            raise ValueError(f"reading {idx} is not numeric")


def analyze(readings, window):
    """Replace spikes by the last normal value and report their size."""
    validate_readings(readings, window)
    cleaned = []
    warnings = []
    cnt = 0
    prev = None
    pos = 0
    while pos < len(readings):
        curr = readings[pos]
        buf = readings[max(pos - window, 0):pos]
        if len(buf) < window:
            cleaned.append(curr)
            prev = curr
            pos += 1
            continue
        avg = sum(buf) / len(buf)
        if curr > 2 * avg:
            msg = f"spike difference {curr - avg}"
            warnings.append(msg)
            cleaned.append(prev)
            cnt += 1
        else:
            cleaned.append(curr)
            prev = curr
        pos += 1
    return cleaned, warnings, cnt


def format_report(param, res):
    """Turn one analyze() result into a printable block of text."""
    cleaned, msgs, num = res
    lines = [f"{param}: {num} anomaly(ies) over {len(cleaned)} readings"]
    parts = []
    for elem in cleaned:
        parts.append(f"{elem:g}")
    tmp = ", ".join(parts)
    lines.append(f"  cleaned: [{tmp}]")
    for idx in range(len(msgs)):
        lines.append(f"  #{idx + 1} {msgs[idx]}")
    return "\n".join(lines)


