def describe_op(idx, elem):
    cmd, lhs, rhs = elem
    return f"#{idx} {cmd} {lhs} {rhs}"


def validate_program(instructions):
    for idx, elem in enumerate(instructions):
        if len(elem) != 3:
            return f"malformed instruction #{idx}"
        if elem[0] not in ("add", "jump"):
            return f"unknown command in {describe_op(idx, elem)}"
    return ""


def validate_inputs(inputs):
    for key in sorted(inputs):
        val = inputs[key]
        if not isinstance(val, int) or isinstance(val, bool):
            return f"non-integer value for slot {key!r}"
    return ""


def read_slot(ctx, param):
    if param not in ctx:
        raise KeyError(param)
    return ctx[param]


def simulate(instructions, inputs):
    mem = dict(inputs)
    cnt = 0
    err = validate_program(instructions) or validate_inputs(inputs)
    if err:
        return mem, cnt, err
    pos = 0
    while 0 <= pos < len(instructions):
        cmd, lhs, rhs = instructions[pos]
        try:
            if cmd == "add":
                tmp = read_slot(mem, lhs) + read_slot(mem, rhs)
                mem[lhs] = tmp
                pos += 1
            else:
                pos = read_slot(mem, lhs)
        except KeyError as exc:
            err = f"missing target {exc.args[0]!r} at operation {pos}"
            break
        cnt += 1
    return mem, cnt, err


def format_report(name, inputs, res, cfg):
    mem, cnt, err = res
    num = len(mem)
    buf = [f"{cfg['title']} {name}", cfg["rule"] * 28, f"  slots: {num}"]
    for key in sorted(mem):
        curr = mem[key]
        prev = inputs.get(key)
        if curr == prev:
            buf.append(f"  {key} = {curr}")
        else:
            buf.append(f"  {key} = {curr} (was {prev})")
    buf.append(f"  executed: {cnt}")
    msg = err if err else "ok"
    buf.append(f"  status: {msg}")
    return "\n".join(buf)


def main():
    cfg = {"title": "program", "rule": "-"}
    programs = {
        "sum": ([("add", "a", "b")], {"a": 1, "b": 2}),
