                 {"a": 0, "b": 5, "j": 3}),
        "broken": ([("add", "a", "z")], {"a": 1}),
    }
    for name in sorted(programs):
        instructions, inputs = programs[name]
        res = simulate(instructions, inputs)
        print(format_report(name, inputs, res, cfg))
        print()


