DEFAULT_CFG = {"alphabet_size": 256, "codes_per_line": 8}


def build_table(cfg):
    """Map every single character of the configured alphabet to its code."""
    table = {}
    for idx in range(cfg["alphabet_size"]):
        table[chr(idx)] = idx
    return table


def check_symbols(symbols, cfg):
    """Reject characters that have no single-character code in the table."""
    if not isinstance(symbols, str):
        raise TypeError("symbols must be a string")
    for pos, character in enumerate(symbols):
        if ord(character) >= cfg["alphabet_size"]:
            err = "symbol %r at position %d is outside the alphabet" % (character, pos)
            raise ValueError(err)


def encode(symbols):
    """Compress a string, returning (list of codes, number of dictionary additions)."""
    cfg = DEFAULT_CFG
    check_symbols(symbols, cfg)
    if not symbols:
        return ([], 0)
    table = build_table(cfg)
    num = cfg["alphabet_size"]
    cnt = 0
    curr = symbols[0]
    res = []
    for pos in range(1, len(symbols)):
        elem = symbols[pos]
        sequence = curr + elem
        if sequence in table:
            curr = sequence
        else:
            res.append(table[curr])
            table[sequence] = num
            num += 1
            cnt += 1
            curr = elem
    res.append(table[curr])
    return (res, cnt)


def format_codes(codes, param):
    """Lay the codes out in rows of `parameter` entries."""
    buf = []
    for idx in range(0, len(codes), param):
        tmp = codes[idx:idx + param]
        buf.append(" ".join(str(val) for val in tmp))
    return "\n".join(buf)


def format_report(ctx):
    msg = "input=%d chars, codes=%d, additions=%d, ratio=%.3f" % (
        len(ctx["source"]), len(ctx["codes"]), ctx["adds"], ctx["ratio"])
    return msg


def main():
    samples = ["AB", "TOBEORNOTTOBEORTOBEORNOT", "aaaaaaaaaaaa"]
    prev = None
    for elem in samples:
        codes, additions = encode(elem)
        ctx = {"source": elem, "codes": codes, "adds": additions,
               "ratio": len(codes) / len(elem)}
        print("source: %r" % elem)
        print(format_report(ctx))
        print(format_codes(codes, DEFAULT_CFG["codes_per_line"]))
        if prev is not None:
            print("change in ratio vs previous sample: %+.3f" % (ctx["ratio"] - prev))
        prev = ctx["ratio"]
        print()


