def parse_intervals(raw):
    """Validate a sequence of (start, end) pairs and return them as tuples."""
    buf = []
    for idx in range(len(raw)):
        elem = raw[idx]
        if len(elem) != 2:
            msg = "entry %d does not have exactly two values" % idx
            raise ValueError(msg)
        start, end = elem
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("entry %d has non-integer bounds" % idx)
        if end < start:
            raise ValueError("entry %d ends before it starts" % idx)
        buf.append((start, end))
    return buf


def resolve(intervals):
    """Merge overlapping periods; return the merged list and the merge tally."""
    if not intervals:
        return [], 0
    ordered = sorted(intervals, key=lambda param: param[0])
    res = [tuple(ordered[0])]
    cnt = 0
    for curr in ordered[1:]:
        prev = res[-1]
        if curr[0] <= prev[1]:
            val = max(prev[1], curr[1])
            res[-1] = (prev[0], val)
            cnt += 1
        else:
            res.append(tuple(curr))
    return res, cnt


def format_report(merged, cnt):
    """Build a human readable summary of one merge run."""
    lines = []
    num = 0
    for pos in range(len(merged)):
        start, end = merged[pos]
        tmp = end - start
        num += tmp
        lines.append("  #%d: [%d, %d] span=%d" % (pos + 1, start, end, tmp))
    msg = "  %d merge(s) -> %d block(s), covering %d unit(s)" % (cnt, len(merged), num)
    lines.append(msg)
    return "\n".join(lines)


def main():
    cfg = {
        "simple": [(1, 3), (2, 4)],
        "chained": [(5, 6), (1, 3), (2, 5), (9, 12), (11, 15)],
        "disjoint": [(4, 5), (1, 2)],
        "touching": [(1, 2), (2, 3), (3, 4)],
        "broken": [(1, "x")],
    }
    ctx = {"blocks": 0, "merges": 0}
    for name in sorted(cfg):
        try:
            periods = parse_intervals(cfg[name])
        except ValueError as err:
            print("%s: skipped (%s)" % (name, err))
            continue
        out, cnt = resolve(periods)
        ctx["blocks"] += len(out)
        ctx["merges"] += cnt
        print("%s: %r" % (name, out))
        print(format_report(out, cnt))
    print("totals: %d block(s), %d merge(s)" % (ctx["blocks"], ctx["merges"]))


if __name__ == "__main__":
    main()

