def match(text, pattern):
    """Locate every occurrence of pattern inside text, with diagnostics."""
    if not pattern:
        raise ValueError("pattern must not be empty")
    res = {}
    cnt = 0
    errors = []
    num = len(pattern)
    for pos in range(len(text) - num + 1):
        tmp = text[pos:pos + num]
        matched = True
        for idx, elem in enumerate(pattern):
            curr = tmp[idx]
            if curr != elem:
                msg = "expected {} found {}".format(curr, elem)
                errors.append(msg)
                matched = False
                break
        if matched:
            res[pos] = tmp
            cnt += 1
    return res, cnt, errors


def spacing(res):
    """Distances between consecutive match start pointers."""
    gaps = []
    prev = None
    for pos in sorted(res):
        if prev is not None:
            gaps.append(pos - prev)
        prev = pos
    return gaps


def tally(errors):
    """Group identical diagnostic strings and count them."""
    res = {}
    for msg in errors:
        res[msg] = res.get(msg, 0) + 1
    return res


def format_report(text, pattern):
    """Human readable summary of a single search."""
    res, cnt, errors = match(text, pattern)
    buf = ["text={!r} pattern={!r}".format(text, pattern)]
    buf.append("matches={} at {}".format(cnt, sorted(res)))
    gaps = spacing(res)
    if gaps:
        buf.append("gaps=" + ",".join(str(val) for val in gaps))
    for msg, num in sorted(tally(errors).items()):
        buf.append("  {}x {}".format(num, msg))
    return "\n".join(buf)


