def parse_transitions(cfg):
    """Turn a text block of 'state: next, next' lines into a transition table."""
    table = {}
    for idx, line in enumerate(cfg.splitlines(), start=1):
        tmp = line.strip()
        if not tmp or tmp.startswith("#"):
            continue
        pos = tmp.find(":")
        if pos < 0:
            raise ValueError("line %d: missing ':' separator" % idx)
        param = tmp[:pos].strip()
        if not param:
            raise ValueError("line %d: empty state name" % idx)
        table[param] = [elem.strip() for elem in tmp[pos + 1:].split(",") if elem.strip()]
    return table


def validate(transitions, sequence):
    """Walk the sequence, counting valid steps and reporting the first bad one."""
    if not sequence:
        raise ValueError("sequence must contain at least one state")
    curr = sequence[0]
    cnt = 0
    res = []
    for idx in range(1, len(sequence)):
        elem = sequence[idx]
        if elem not in transitions.get(curr, []):
            msg = "invalid transition from '%s' to '%s'" % (curr, elem)
            res.append(msg)
            break
        curr = elem
        cnt += 1
    return cnt, res, curr


def trace(sequence, cnt):
    """Render the steps that were actually accepted as an arrow chain."""
    parts = []
    for idx in range(cnt):
        prev = sequence[idx]
        curr = sequence[idx + 1]
        parts.append("%s -> %s" % (prev, curr))
    return " | ".join(parts) if parts else "(no accepted steps)"


def format_report(sequence, cnt, issues, last):
    num = len(sequence) - 1
    buf = ["accepted steps: %d of %d" % (cnt, num)]
    buf.append("path: " + trace(sequence, cnt))
    buf.append("last visited state: " + last)
    for msg in issues:
        buf.append("issue: " + msg)
    return buf


def main():
    cfg = """
    # state machine of a simple job runner
    start: run
    run: pause, stop
    pause: run
    stop:
    """
    try:
        table = parse_transitions(cfg)
    except ValueError as err:
        print("config error:", err)
        return
    ctx = {
        "clean run": ["start", "run", "pause", "run", "stop"],
        "restart attempt": ["start", "run", "start", "stop"],
        "unknown state": ["start", "halt"],
    }
    for name, val in ctx.items():
        cnt, issues, last = validate(table, val)
        print(name + ":")
        for line in format_report(val, cnt, issues, last):
            print("   " + line)


if __name__ == "__main__":
    main()

