def tokenize(text):
    """Split a text block into lowercase word tokens, dropping punctuation."""
    buf = []
    curr = []
    for elem in text:
        if elem.isalnum() or elem == "'":
            curr.append(elem.lower())
        elif curr:
            buf.append("".join(curr))
            curr = []
    if curr:
        buf.append("".join(curr))
    return buf


def normalize_keywords(keywords):
    """Return the keywords lowercased, trimmed, de-duplicated and order-preserved."""
    res = []
    for param in keywords:
        if not isinstance(param, str):
            err = "keywords must contain strings, got {!r}".format(param)
            raise TypeError(err)
        tmp = param.strip().lower()
        if tmp and tmp not in res:
            res.append(tmp)
    return res


def calculate(documents, keywords):
    """Count keyword hits per text block; return (per-block dicts, overall peak)."""
    keys = normalize_keywords(keywords)
    master = []
    num = 0
    for ctx in documents:
        tallies = {key: 0 for key in keys}
        words = tokenize(ctx)
        top = 0
        for word in words:
            if word in tallies:
                cnt = tallies[word] + 1
                tallies[word] = cnt
                if cnt > top:
                    top = cnt
        master.append(tallies)
        if top > num:
            num = top
    return master, num


def aggregate(master):
    """Sum each keyword's tallies over all text blocks."""
    totals = {}
    for tallies in master:
        for key in tallies:
            prev = totals.get(key, 0)
            totals[key] = prev + tallies[key]
    return totals


def format_report(master, peak):
    """Render one line per text block plus the overall peak tally."""
    lines = []
    for idx, tallies in enumerate(master, start=1):
        parts = []
        for key in sorted(tallies):
            val = tallies[key]
            parts.append("{}={}".format(key, val))
        msg = "block {}: {}".format(idx, ", ".join(parts) or "no keywords")
        lines.append(msg)
    lines.append("peak tally in a single block: {}".format(peak))
    return "\n".join(lines)


def main():
    cfg = {
        "documents": [
            "apple banana apple",
            "Cherry, apple; cherry -- cherry!",
            "banana bread and banana jam",
        ],
        "keywords": ["Apple", "banana", "cherry", "apple"],
    }
    master, peak = calculate(cfg["documents"], cfg["keywords"])
    print(format_report(master, peak))
    totals = aggregate(master)
    for key in sorted(totals, key=lambda k: (-totals[k], k)):
        print("total {}: {}".format(key, totals[key]))


if __name__ == "__main__":
    main()

