OPS = {"+", "-", "*", "/"}


def parse(expression):
    out = []
    issues = []
    pos = 0
    num = len(expression)
    while pos < num:
        curr = expression[pos]
        if curr.isdigit():
            tmp = [curr]
            pos += 1
            while pos < num and expression[pos].isdigit():
                tmp.append(expression[pos])
                pos += 1
            buf = "".join(tmp)
            out.append(float(buf))
        elif curr in OPS:
            out.append(str(curr))
            pos += 1
        else:
            msg = "unknown character %r at position %d" % (curr, pos)
            issues.append(msg)
            pos += 1
    cnt = len(out)
    return out, cnt, issues


def evaluate(components):
    ctx = {
        "+": lambda a, b: a + b,
        "-": lambda a, b: a - b,
        "*": lambda a, b: a * b,
        "/": lambda a, b: a / b,
    }
    val = None
    prev = None
    for elem in components:
        if isinstance(elem, str):
            prev = elem
        elif val is None:
            val = elem
        else:
            if prev is None:
                raise ValueError("missing operator before %s" % elem)
            param = ctx[prev]
            val = param(val, elem)
            prev = None
    if val is None:
        raise ValueError("no numbers in expression")
    return val


def format_report(expression, cfg):
    components, cnt, issues = parse(expression)
    lines = ["input: %s" % expression, "components: %d" % cnt]
    for idx, elem in enumerate(components):
        lines.append("  [%d] %r" % (idx, elem))
    if cfg.get("show_value") and not issues:
        try:
            val = evaluate(components)
        except (ValueError, ZeroDivisionError) as exc:
            lines.append("value: unavailable (%s)" % exc)
        else:
            lines.append("value: %s" % val)
    for msg in issues:
        lines.append("issue: %s" % msg)
    return "\n".join(lines)


def main():
    cfg = {"show_value": True}
    samples = ["12+3", "100*25-7", "4/0", "8 + x", "+5"]
    for elem in samples:
        print(format_report(elem, cfg))
        print("-" * 32)
    print(parse("12+3"))


if __name__ == "__main__":
    main()

