def validate(text, minimum):
    """Reject inputs that the palindrome scan cannot work with."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got %s" % type(text).__name__)
    if isinstance(minimum, bool) or not isinstance(minimum, int):
        raise TypeError("minimum must be an integer")
    if minimum < 1:
        raise ValueError("minimum must be at least 1, got %d" % minimum)


def extract(text, minimum):
    """Return (palindromes, longest palindrome, diagnostics) for text."""
    validate(text, minimum)
    res = []
    diags = []
    curr = ""
    num = len(text)
    if num == 0:
        diags.append("empty text: nothing to scan")
        return (res, curr, diags)
    for pos in range(num):
        for idx in range(pos + 1, num + 1):
            tmp = text[pos:idx]
            if tmp != tmp[::-1]:
                continue
            if len(tmp) >= minimum:
                res.append(tmp)
                if len(tmp) > len(curr):
                    curr = tmp
    return (res, curr, diags)


def tally(res):
    """Count how often each palindrome was produced by the scan."""
    cnt = {}
    for elem in res:
