import sys


def strip_comment(raw):
    pos = raw.find("#")
    if pos >= 0:
        raw = raw[:pos]
    return raw.strip()


def parse_section(text):
    if not text.startswith("["):
        return None
    name = text[1:]
    if name.endswith("]"):
        name = name[:-1]
    return name.strip()


def split_param(text):
    idx = text.find("=")
    if idx < 0:
        return None
    return text[:idx].strip(), text[idx + 1:].strip()


def describe(num, ctx, problem):
    return "line %d, section [%s]: %s" % (num, ctx, problem)


def lint(lines):
    res = []
    cfg = {}
    ctx = "(no section)"
    cfg[ctx] = {}
    for num, raw in enumerate(lines, 1):
        text = strip_comment(raw)
        if not text:
            continue
        curr = parse_section(text)
        if curr is not None:
            if curr:
                ctx = curr
                cfg.setdefault(ctx, {})
            else:
                res.append(describe(num, ctx, "section header is missing a name"))
            continue
        param = split_param(text)
        if param is None:
            res.append(describe(num, ctx, "line is neither a section header nor an assignment"))
            continue
        key, val = param
        if not key:
            res.append(describe(num, ctx, "assignment is missing a parameter name"))
            continue
        if not val:
            res.append(describe(num, ctx, "parameter %r has an empty value" % key))
        prev = cfg[ctx].get(key)
        if prev is None:
            cfg[ctx][key] = num
        else:
            err = describe(num, ctx, "parameter %r was already assigned on line %d" % (key, prev))
            res.append(err)
    return res


