def paginate(items):
    """Split items into pages of three without slicing."""
    res = []
    buf = []
    cnt = 0
    idx = 0
    while idx < len(items):
        elem = items[idx]
        buf.append(elem)
        if len(buf) == 3:
            tmp = list(buf)
            res.append(tmp)
            buf.clear()
            cnt += 1
        idx += 1
    if buf:
