def parse_tag(param):
    """Split a tag like 'open-a' into its kind ('open'/'close') and its suffix."""
    pos = param.find("-")
    if pos < 0:
        raise ValueError("malformed tag %r" % param)
    kind = param[:pos]
    if kind not in ("open", "close"):
        raise ValueError("unknown tag kind %r" % kind)
    suffix = param[pos + 1:]
    if not suffix:
        raise ValueError("missing tag name in %r" % param)
