            if val < 0:
                msg = "negative value %d at row %d, column %d" % (val, idx, pos)
                errors.append(msg)
                continue
            if val == 0:
                continue
            if idx > 0 and pos < len(grid[idx - 1]):
                prev = grid[idx - 1][pos]
                if prev == val:
                    cnt += 1
            if pos > 0:
                elem = curr[pos - 1]
                if elem == val:
