        if curr.startswith(">"):
            tmp = curr.lstrip(">").strip()
            if tmp:
                buf = (buf + " " + tmp).strip()
        elif buf:
            res.append(buf)
            cnt += 1
            buf = ""
    if buf:
        res.append(buf)
        cnt += 1
    return cnt, res


def normalize_cfg(param):
    cfg = dict(DEFAULT_CFG)
    for key, val in (param or {}).items():
        if key not in cfg:
            raise KeyError("unknown option %r" % key)
        cfg[key] = val
    if int(cfg["width"]) < 20:
        raise ValueError("width must be at least 20")
    cfg["width"] = int(cfg["width"])
    return cfg


def wrap_text(text, width):
    out = []
    buf = ""
    for elem in text.split():
        if buf and len(buf) + 1 + len(elem) > width:
            out.append(buf)
            buf = elem
        else:
            buf = (buf + " " + elem) if buf else elem
    if buf:
        out.append(buf)
    return out


def report(cnt, res, param=None):
