    res = []
    err = []
    for idx, word in enumerate(words):
        num = WIDTH - len(word)
        if num < 0:
            msg = "word %d (%r) exceeds %d characters" % (idx, word, WIDTH)
            err.append(msg)
            res.append(word)
        else:
            left = num // 2
            right = num - left
            tmp = " " * left + word + " " * right
            res.append(tmp)
    return res, err


def normalize(raw):
