SEPARATOR = "/"
INVALID_CHARS = "*?<>|"
HEADER = "{input}  ->  {output}  (depth {depth})"
MESSAGE = "segment {0} ({1!r}): forbidden character {2!r} at offset {3}"
SAMPLES = [
    "/usr/local//bin/../lib/./headers",
    "docs/./drafts/../../notes/chapter*1/appendix",
    "a/b/c/../../../../d",
]


def find_invalid(param):
    """Return (offset, character) of the first forbidden character, or None."""
    for offset, character in enumerate(param):
        if character in INVALID_CHARS:
            return offset, character
    return None


def normalize(path):
    """Resolve '.' and '..' segments; return (normalized path, list of errors)."""
    buf = []
    errors = []
    for position, part in enumerate(path.split(SEPARATOR)):
        if part in ("", "."):
            continue
        bad = find_invalid(part)
        if bad is not None:
            offset, character = bad
            err = MESSAGE.format(position, part, character, offset)
            errors.append(err)
            continue
        if part == "..":
            if buf:
                buf.pop()
            else:
                buf.append(part)
            continue
        buf.append(part)
    text = SEPARATOR.join(buf)
    if path.startswith(SEPARATOR):
        text = SEPARATOR + text
    return text, errors


def depth(path):
    return len([segment for segment in path.split(SEPARATOR) if segment])


def build_ctx(path):
    res, errors = normalize(path)
    ctx = {
        "input": path,
        "output": res or SEPARATOR,
        "errors": errors,
        "depth": depth(res),
    }
    return ctx


def format_report(ctx):
    lines = [HEADER.format(**ctx)]
    reported = ctx["errors"]
    for number, msg in enumerate(reported, start=1):
        lines.append("    error {0}: {1}".format(number, msg))
    return "\n".join(lines)


def main():
    contexts = [build_ctx(path) for path in SAMPLES]
    for ctx in contexts:
        print(format_report(ctx))
    cnt = sum(len(item["errors"]) for item in contexts)
    print("paths processed: {0}".format(len(contexts)))
    print("errors recorded: {0}".format(cnt))


if __name__ == "__main__":
    main()

