    return text, errors


def depth(path):
    return len([segment for segment in path.split(SEPARATOR) if segment])


def build_context(path):
    result, errors = normalize(path)
    context = {
        "input": path,
        "output": result or SEPARATOR,
        "errors": errors,
        "depth": depth(result),
    }
    return context


def format_report(context):
    lines = [HEADER.format(**context)]
    reported = context["errors"]
    for number, message in enumerate(reported, start=1):
        lines.append("    error {0}: {1}".format(number, message))
    return "\n".join(lines)


def main():
    contexts = [build_context(path) for path in SAMPLES]
    for context in contexts:
        print(format_report(context))
    count = sum(len(item["errors"]) for item in contexts)
    print("paths processed: {0}".format(len(contexts)))
    print("errors recorded: {0}".format(count))


if __name__ == "__main__":
    main()

