def parse_digits(text):
    """Convert a whitespace/comma separated string into a list of integers."""
    res = []
    err = []
    for tmp in text.replace(",", " ").split():
        try:
            res.append(int(tmp))
        except ValueError:
            err.append("not an integer: %r" % tmp)
    return res, err


def checksum(digits):
    """Return (check digit, error strings) for a list of integers 0..9."""
    total = 0
    errors = []
    for idx, val in enumerate(digits):
        if val < 0 or val > 9:
            errors.append("digit at index %d out of range: %d" % (idx, val))
            continue
        if idx % 2 == 0:
            total += val * 3
        else:
            total += val
    num = total % 10
    if num == 0:
        return 0, errors
    return 10 - num, errors


def verify(digits):
    """Treat the last element as a check digit and verify the leading body."""
    if not digits:
        return False, ["empty code"]
    body = digits[:-1]
    curr = digits[-1]
    expected, errors = checksum(body)
    if curr < 0 or curr > 9:
        errors.append("check digit out of range: %d" % curr)
        return False, errors
    return (not errors) and expected == curr, errors


def format_report(param, digits):
    """Build a one-line report about a labelled code."""
    ok, errors = verify(digits)
    buf = ["%-10s %s" % (param, "".join(str(d) for d in digits if 0 <= d <= 9))]
    buf.append("valid" if ok else "INVALID")
    for msg in errors:
        buf.append("(%s)" % msg)
    return " ".join(buf)


