import sys


def validate_params(data, width):
    """Raise if the byte list or the row width cannot be dumped."""
    if not isinstance(width, int) or width <= 0:
        raise ValueError("width must be a positive integer")
    for idx, elem in enumerate(data):
        if not isinstance(elem, int):
            msg = f"byte at index {idx} is not an integer"
            raise TypeError(msg)
        if not 0 <= elem <= 255:
            raise ValueError(f"byte at index {idx} out of range: {elem}")


def format_row(offset, chunk, width):
    """Build one dump row: hex offset, then hex bytes padded with dashes."""
    cells = [f"{val:02X}" for val in chunk]
    cnt = width - len(chunk)
    cells.extend(["--"] * cnt)
    return f"{offset:04X} " + " ".join(cells)


def dump(data, width):
    """Format a list of byte values into offset-prefixed hex rows."""
    validate_params(data, width)
    res = []
    for pos in range(0, len(data), width):
        chunk = data[pos:pos + width]
        res.append(format_row(pos, chunk, width))
    return res


def parse_tokens(tokens):
    """Convert command line tokens into byte values (decimal or 0x hex)."""
    buf = []
    for tmp in tokens:
        curr = tmp.strip().rstrip(",")
        if not curr:
            continue
        base = 16 if curr.lower().startswith("0x") else 10
        buf.append(int(curr, base))
    return buf


def summarize(data, rows):
    """Describe how much data was dumped and in how many rows."""
    num = len(data)
    cnt = len(rows)
    return f"{num} byte(s) in {cnt} row(s)"


