def validate_orders(orders):
    """Check the raw order tuples and return them as a plain list."""
    for idx, elem in enumerate(orders):
        if len(elem) != 3:
            msg = f"order {idx} must be a (timestamp, type, price) triple"
            raise ValueError(msg)
        stamp, kind, price = elem
        if not isinstance(stamp, int):
            raise ValueError(f"order {idx} has a non-integer timestamp")
        if kind not in ("buy", "sell"):
            err = f"order {idx} has unknown type {kind!r}"
            raise ValueError(err)
        if not isinstance(price, int) or price < 0:
            raise ValueError(f"order {idx} has an invalid price {price!r}")
    return list(orders)


def find_match(book, price, kind):
    """Index of the earliest order in book that can trade against price."""
    for pos, elem in enumerate(book):
        val = elem[1]
        if kind == "buy" and val <= price:
            return pos
        if kind == "sell" and val >= price:
            return pos
    return -1


def match(orders):
    buf = validate_orders(orders)
    buf.sort(key=lambda param: param[0])
    ctx = {"buy": [], "sell": []}
    res = []
    for curr in buf:
        stamp, kind, price = curr
        book = ctx["sell"] if kind == "buy" else ctx["buy"]
        pos = find_match(book, price, kind)
        if pos < 0:
            ctx[kind].append((stamp, price))
            continue
        tmp = book.pop(pos)
        if kind == "buy":
            res.append((stamp, tmp[0]))
        else:
            res.append((tmp[0], stamp))
    return res


def format_report(matches):
    lines = [f"matched pairs: {len(matches)}"]
    prev = None
    for num, pair in enumerate(matches, start=1):
        buy_ts, sell_ts = pair
        if prev is None:
            gap = ""
        else:
            gap = f" (+{buy_ts - prev} since previous buy)"
        lines.append(f"{num}. buy@{buy_ts} <-> sell@{sell_ts}{gap}")
        prev = buy_ts
    cnt = sum(1 for pair in matches if pair[0] > pair[1])
    lines.append(f"pairs where the buy arrived after the sell: {cnt}")
    return "\n".join(lines)


def main():
    cfg = {
        "orders": [
            (1, "buy", 10),
            (2, "sell", 9),
            (3, "sell", 12),
            (4, "buy", 15),
            (5, "buy", 8),
            (6, "sell", 20),
        ]
    }
    try:
        res = match(cfg["orders"])
    except ValueError as err:
        print(f"invalid input: {err}")
        return 1
    print(res)
    print(format_report(res))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

