_KINDS = ("note_on", "note_off")


def validate_events(events):
    if not isinstance(events, list):
        raise TypeError("events must be a list of tuples")
    for idx in range(len(events)):
        elem = events[idx]
        if not isinstance(elem, tuple) or len(elem) != 3:
            msg = "event %d must be a 3-tuple (offset, type, pitch)" % idx
            raise ValueError(msg)
        offset, kind, pitch = elem
        if not isinstance(offset, int) or offset < 0:
            raise ValueError("event %d has a bad time offset: %r" % (idx, offset))
        if kind not in _KINDS:
            raise ValueError("event %d has unknown type: %r" % (idx, kind))
        if not isinstance(pitch, int) or not 0 <= pitch <= 127:
            raise ValueError("event %d has a bad pitch: %r" % (idx, pitch))


def _apply_event(ctx, elem):
    offset, kind, pitch = elem
    curr = ctx["time"] + offset
    ctx["time"] = curr
    if kind == "note_on":
        if pitch not in ctx["active"]:
            ctx["active"][pitch] = curr
        return
    prev = ctx["active"].pop(pitch, None)
    if prev is None:
        return
    val = curr - prev
    if pitch not in ctx["totals"]:
        ctx["totals"][pitch] = 0
        ctx["order"].append(pitch)
    ctx["totals"][pitch] += val


def synthesize(events):
    validate_events(events)
    ctx = {"time": 0, "active": {}, "totals": {}, "order": []}
    for elem in events:
        _apply_event(ctx, elem)
    return [(pitch, ctx["totals"][pitch]) for pitch in ctx["order"]]


