    events = []
    for pos in range(len(lines)):
        tmp = lines[pos].strip()
        if not tmp or tmp.startswith("#"):
            continue
        parts = tmp.split()
        if len(parts) != 3:
            raise ValueError("line %d: expected 3 fields, got %d" % (pos + 1, len(parts)))
        events.append((int(parts[0]), parts[1], int(parts[2])))
    return events


