    cfg = dict(cfg or {})
    defaults = {"width": 4, "unit": "ticks"}
    for param in defaults:
        cfg.setdefault(param, defaults[param])
    buf = []
    for pos in range(len(pairs)):
        pitch, duration = pairs[pos]
        num = pos + 1
        buf.append("%2d. pitch %3d held %*d %s" % (num, pitch, cfg["width"], duration, cfg["unit"]))
    cnt = len(pairs)
    buf.append("-- %d note(s) sounded --" % cnt)
    return "\n".join(buf)


