PIECE_NAMES = {
    "K": "King",
    "Q": "Queen",
    "R": "Rook",
    "B": "Bishop",
    "N": "Knight",
    "P": "Pawn",
}
FILES = "abcdefgh"
RANKS = "12345678"


def normalize(param):
    """Strip whitespace and trailing annotation marks such as +, #, ! or ?."""
    buf = param.strip()
    while buf and buf[-1] in "+#!?":
        buf = buf[:-1]
    return buf


def parse_move(move):
    """Return (piece, captured, destination) for one algebraic move."""
    curr = normalize(move)
    if len(curr) < 2:
        raise ValueError("too short to contain a destination square")
    pos = len(curr) - 2
    val = curr[pos:]
    if val[0] not in FILES or val[1] not in RANKS:
        raise ValueError("%r is not a square" % val)
    prev = curr[:pos]
    captured = "x" in prev
    prev = prev.replace("x", "")
    elem = prev[0] if prev else "P"
    if elem not in PIECE_NAMES:
        msg = "unknown piece letter %r" % elem
        raise ValueError(msg)
    return (PIECE_NAMES[elem], captured, val)


def read(moves):
    """Parse a list of algebraic moves into (piece, capture, destination) tuples."""
    res = []
    for idx, param in enumerate(moves):
        try:
            res.append(parse_move(param))
        except ValueError as err:
            msg = "move %d (%r): %s" % (idx + 1, param, err)
            raise ValueError(msg)
    return res


def format_row(elem):
    piece, captured, dest = elem
    tmp = "capture" if captured else "quiet"
    return "%-7s %-8s -> %s" % (piece, tmp, dest)


def report(parsed):
    buf = ["Parsed %d move(s)" % len(parsed)]
    ctx = {}
    cnt = 0
    for elem in parsed:
        buf.append(format_row(elem))
        ctx[elem[0]] = ctx.get(elem[0], 0) + 1
        if elem[1]:
            cnt += 1
    buf.append("Captures: %d" % cnt)
    for piece, num in sorted(ctx.items()):
        buf.append("  %s x%d" % (piece, num))
    return "\n".join(buf)


def main():
    game = ["e4", "e5", "Nf3", "Nc6", "Bb5", "a6", "Bxc6", "dxc6", "Nxe5", "Qd4+"]
    print(report(read(game)))


if __name__ == "__main__":
    main()

