def column_widths(rows):
    """Maximum character width of every column across all rows."""
    widths = []
    for row in rows:
        for idx, cell in enumerate(row):
            num = len(cell)
            if idx == len(widths):
                widths.append(num)
            elif num > widths[idx]:
                widths[idx] = num
    return widths


def pad_row(cells, widths):
    """Render one row, padding each cell to its column width."""
    buf = []
    for idx, width in enumerate(widths):
        val = cells[idx] if idx < len(cells) else ""
        buf.append(val.ljust(width))
    return "|".join(buf)


def dash_row(widths):
    """Render the dashed separator line."""
    tmp = ["-" * width for width in widths]
    return "|".join(tmp)


def validate(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list of lists of strings")
    for pos, row in enumerate(rows):
        ctx = "row %d" % pos
        if not isinstance(row, list):
            raise TypeError(ctx + " is not a list")
        for elem in row:
            if not isinstance(elem, str):
                err = "%s contains a non-string cell: %r" % (ctx, elem)
                raise TypeError(err)


def tabularize(rows):
    validate(rows)
    if not rows:
        return []
    cfg = column_widths(rows)
    res = [pad_row(rows[0], cfg), dash_row(cfg)]
    for row in rows[1:]:
