UNIT_CFG = {
    "oz": "ounces", "ounce": "ounces", "ounces": "ounces",
    "lb": "pounds", "lbs": "pounds", "pound": "pounds", "pounds": "pounds",
    "c": "cups", "cup": "cups", "cups": "cups",
    "tbsp": "tablespoons", "tablespoon": "tablespoons", "tablespoons": "tablespoons",
}


def normalize_unit(param):
    tmp = param.strip().lower()
    return UNIT_CFG.get(tmp, tmp)


def validate(recipe):
    err = []
    for idx, elem in enumerate(recipe):
        if len(elem) != 3:
            err.append("entry %d: expected 3 fields, got %d" % (idx, len(elem)))
            continue
        name, num, unit = elem
        if not isinstance(name, str) or not name.strip():
            err.append("entry %d: ingredient name must be a non-empty string" % idx)
        if isinstance(num, bool) or not isinstance(num, (int, float)) or num < 0:
            err.append("entry %d: quantity must be a non-negative number" % idx)
        if not isinstance(unit, str):
            err.append("entry %d: unit must be a string" % idx)
    return err


def scale(recipe, multiplier):
    ctx = validate(recipe)
    if ctx:
        raise ValueError("; ".join(ctx))
    if isinstance(multiplier, bool) or not isinstance(multiplier, (int, float)):
        raise TypeError("multiplier must be a number")
    if multiplier < 0:
        raise ValueError("multiplier must be non-negative")
    res = []
    for name, qty, unit in recipe:
        val = qty * multiplier
        curr = normalize_unit(unit)
        if curr == "ounces" and val > 16:
            val = val / 16.0
            curr = "pounds"
        elif curr == "cups" and val < 0.25:
            val = val * 16.0
            curr = "tablespoons"
        res.append((name, val, curr))
    return res


def fmt_qty(num):
    val = round(float(num), 3)
    if abs(val - round(val)) < 1e-9:
        return str(int(round(val)))
    return ("%.3f" % val).rstrip("0")


def report(recipe, multiplier):
    buf = ["Scaled by %s:" % fmt_qty(multiplier)]
    cnt = 0
    for pos, elem in enumerate(scale(recipe, multiplier)):
        prev = normalize_unit(recipe[pos][2])
        ingredient, amount, curr = elem
        msg = "  %-10s %8s %s" % (ingredient, fmt_qty(amount), curr)
        if curr != prev:
            cnt += 1
            msg += "  (converted from %s)" % prev
        buf.append(msg)
    buf.append("  -> %d unit conversion(s) applied" % cnt)
    return "\n".join(buf)


def main():
    recipe = [
        ("flour", 8.0, "ounces"),
        ("sugar", 0.2, "cups"),
        ("butter", 4.0, "oz"),
        ("milk", 1.5, "cups"),
    ]
    for idx, param in enumerate((3.0, 0.5, 1.0), start=1):
        print("Batch %d" % idx)
        print(report(recipe, param))


