def validate(rolls):
    if not isinstance(rolls, list):
        raise TypeError("rolls must be a list of integers")
    for idx in range(len(rolls)):
        val = rolls[idx]
        if not isinstance(val, int):
            raise TypeError("roll %d is not an integer" % (idx + 1))
        if val < 0 or val > 10:
            raise ValueError("roll %d is out of range: %d" % (idx + 1, val))


def frame_breakdown(rolls):
    validate(rolls)
    res = []
    pos = 0
    for idx in range(10):
        if pos >= len(rolls):
            raise ValueError("game ends before frame %d" % (idx + 1))
        curr = rolls[pos]
        if curr == 10:
            bonus = rolls[pos + 1:pos + 3]
            if len(bonus) < 2:
                raise ValueError("missing bonus rolls after strike in frame %d" % (idx + 1))
            tmp = 10 + sum(bonus)
            res.append({"rolls": [curr], "score": tmp})
            pos += 1
            continue
        if pos + 1 >= len(rolls):
            raise ValueError("frame %d has only one roll" % (idx + 1))
        second = rolls[pos + 1]
        if curr + second > 10:
            raise ValueError("frame %d knocks down more than ten pins" % (idx + 1))
        tmp = curr + second
        if tmp == 10:
            if pos + 2 >= len(rolls):
                raise ValueError("missing bonus roll after spare in frame %d" % (idx + 1))
            tmp += rolls[pos + 2]
        res.append({"rolls": [curr, second], "score": tmp})
        pos += 2
    return res


def score(rolls):
    res = 0
    for elem in frame_breakdown(rolls):
        res += elem["score"]
    return res


def notation(frame_rolls):
    buf = []
    prev = None
    for idx in range(len(frame_rolls)):
        val = frame_rolls[idx]
        if val == 10:
            buf.append("X")
        elif prev is not None and prev + val == 10:
            buf.append("/")
        elif val == 0:
            buf.append("-")
        else:
            buf.append(str(val))
        prev = val
    return "".join(buf)


def format_report(rolls):
    frames = frame_breakdown(rolls)
    buf = []
    prev = 0
    cnt = 0
    for idx in range(len(frames)):
        elem = frames[idx]
        curr = prev + elem["score"]
        if elem["rolls"][0] == 10:
            cnt += 1
        buf.append("  frame %2d  %-4s %3d  running %3d"
                   % (idx + 1, notation(elem["rolls"]), elem["score"], curr))
        prev = curr
    buf.append("  strikes: %d   total: %d" % (cnt, prev))
    return "\n".join(buf)


def main():
    cfg = [("perfect game", [10] * 12),
           ("all spares", [5] * 21),
           ("open frames", [3, 4] * 10),
           ("gutter game", [0] * 20),
           ("mixed game", [10, 7, 3, 9, 0, 10, 0, 8, 8, 2, 0, 6, 10, 10, 10, 8, 1]),
           ("truncated game", [10, 10])]
    for param in cfg:
        name, rolls = param
        print("%s:" % name)
        try:
            msg = format_report(rolls)
        except (TypeError, ValueError) as err:
            print("  invalid game: %s" % err)
            continue
        print(msg)
        num = score(rolls)
        print("  score() -> %d" % num)


if __name__ == "__main__":
