from typing import Dict, List, Sequence

CFG_DEFAULT: Dict[str, object] = {"sep": ", ", "label_width": 10}


def effective_steps(steps: int, length: int) -> int:
    if length == 0:
        return 0
    return steps % length


def rotate(items: Sequence[int], steps: int) -> List[int]:
    num = len(items)
    pos = effective_steps(steps, num)
    return list(items[num - pos:]) + list(items[:num - pos])


def parse_items(text: str) -> List[int]:
    res: List[int] = []
    for idx, tmp in enumerate(text.split(",")):
        elem = tmp.strip()
        if not elem:
            raise ValueError(f"empty number field at position {idx}")
        try:
            val = int(elem)
        except ValueError as err:
            raise ValueError(f"field {idx} is not an integer: {err}") from None
        res.append(val)
    return res


def parse_steps(text: str) -> int:
    tmp = text.strip()
    try:
        return int(tmp)
    except ValueError as err:
        raise ValueError(f"step count is not an integer: {err}") from None


def format_report(items: Sequence[int], steps: int, cfg: Dict[str, object]) -> str:
    sep = str(cfg["sep"])
    width = int(cfg["label_width"])
    pos = effective_steps(steps, len(items))
    buf = [
        f"{'input':<{width}}" + sep.join(str(elem) for elem in items),
        f"{'steps':<{width}}{steps} (effective {pos})",
        f"{'output':<{width}}" + sep.join(str(elem) for elem in rotate(items, steps)),
    ]
    return "\n".join(buf)


