def build_alias_map(aliases):
    """Turn a list of (folder, label) tuples into a lookup dictionary."""
    res = {}
    for param in aliases:
        if len(param) != 2:
            raise ValueError("alias entries must be (folder, label) pairs")
        folder, label = param
        res[folder] = label
    return res


def split_path(path):
    """Split a slash separated path into clean components."""
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    buf = path.strip()
    tmp = []
    for elem in buf.split("/"):
        curr = elem.strip()
        if not curr or curr == ".":
            continue
        if curr == "..":
            if tmp:
                tmp.pop()
            continue
        tmp.append(curr)
    return tmp


def breadcrumb(path, aliases):
    """Return (cumulative path, display name) pairs for each path component."""
    amap = build_alias_map(aliases)
    parts = split_path(path)
    rooted = path.strip().startswith("/")
    res = []
    for idx in range(len(parts)):
        name = parts[idx]
        if idx:
            prev = res[-1][0]
        else:
            prev = "/" if rooted else ""
        pos = prev if (not prev or prev.endswith("/")) else prev + "/"
        curr = pos + name
        res.append((curr, amap.get(name, name)))
    return res


def format_trail(crumbs, sep):
    """Join the display names of a breadcrumb list into one line."""
    val = []
    for elem in crumbs:
        val.append(elem[1])
    return sep.join(val)


def render_report(crumbs):
    """Produce a numbered listing of display names and their target paths."""
    lines = []
    cnt = len(crumbs)
    for num in range(cnt):
        target, name = crumbs[num]
        msg = "{}. {} -> {}".format(num + 1, name, target)
        lines.append(msg)
    lines.append("{} level(s)".format(cnt))
    return "\n".join(lines)


def main():
    cfg = {
        "separator": " > ",
        "aliases": [("root", "Home"), ("usr", "User Files"), ("docs", "Documents")],
    }
    tasks = [
        ("/root/usr/docs/report.txt", cfg["aliases"]),
        ("root/usr/./cache/../docs", cfg["aliases"]),
        ("/root/usr", [("root", "Home", "extra")]),
    ]
    for ctx in tasks:
        target, alias_list = ctx
        try:
            crumbs = breadcrumb(target, alias_list)
        except ValueError as err:
            print("skipping {!r}: {}".format(target, err))
            continue
        print(format_trail(crumbs, cfg["separator"]))
        print(render_report(crumbs))
        print("-" * 32)


if __name__ == "__main__":
    main()

