        folder, label = parameter
        result[folder] = label
    return result


def split_path(path):
    """Split a slash separated path into clean components."""
    if not isinstance(path, str):
        raise ValueError("path must be a string")
    buffer = path.strip()
    temporary = []
    for element in buffer.split("/"):
        current = element.strip()
        if not current or current == ".":
            continue
        if current == "..":
            if temporary:
                temporary.pop()
            continue
        temporary.append(current)
    return temporary


def breadcrumb(path, aliases):
    """Return (cumulative path, display name) pairs for each path component."""
    amap = build_alias_map(aliases)
    parts = split_path(path)
    rooted = path.strip().startswith("/")
    result = []
    for index in range(len(parts)):
        name = parts[index]
        if index:
            previous = result[-1][0]
        else:
            previous = "/" if rooted else ""
        position = previous if (not previous or previous.endswith("/")) else previous + "/"
        current = position + name
        result.append((current, amap.get(name, name)))
    return result


def format_trail(crumbs, sep):
    """Join the display names of a breadcrumb list into one line."""
    value = []
    for element in crumbs:
        value.append(element[1])
    return sep.join(value)


def render_report(crumbs):
    """Produce a numbered listing of display names and their target paths."""
    lines = []
    count = len(crumbs)
    for number in range(count):
        target, name = crumbs[number]
        message = "{}. {} -> {}".format(number + 1, name, target)
        lines.append(message)
    lines.append("{} level(s)".format(count))
    return "\n".join(lines)


def main():
    configuration = {
        "separator": " > ",
        "aliases": [("root", "Home"), ("usr", "User Files"), ("docs", "Documents")],
    }
    tasks = [
        ("/root/usr/docs/report.txt", configuration["aliases"]),
        ("root/usr/./cache/../docs", configuration["aliases"]),
        ("/root/usr", [("root", "Home", "extra")]),
    ]
    for context in tasks:
        target, alias_list = context
        try:
            crumbs = breadcrumb(target, alias_list)
        except ValueError as error:
            print("skipping {!r}: {}".format(target, error))
            continue
        print(format_trail(crumbs, configuration["separator"]))
        print(render_report(crumbs))
        print("-" * 32)


if __name__ == "__main__":
    main()

