    "east": (1, 0),
    "south": (0, -1),
    "west": (-1, 0),
}
TURNS = {"left": -1, "right": 1}


def parse_command(param):
    """Normalise a raw command string, rejecting anything unknown."""
    if not isinstance(param, str):
        raise ValueError("command must be a string, got %r" % (param,))
    tmp = param.strip().lower()
    if tmp != "forward" and tmp not in TURNS:
        raise ValueError("unknown command %r" % (param,))
    return tmp


def turn(idx, curr):
    """Rotate the heading index by ninety degrees in the requested sense."""
    return (idx + TURNS[curr]) % len(HEADINGS)


def navigate(commands):
    idx = 0
    pos = (0, 0)
    res = []
    seen = set()
    for elem in commands:
        curr = parse_command(elem)
        if curr == "forward":
            cfg = STEP_CFG[HEADINGS[idx]]
            prev = pos
            pos = (prev[0] + cfg[0], prev[1] + cfg[1])
            if pos in seen:
                return [pos]
            seen.add(pos)
            res.append(pos)
        else:
            idx = turn(idx, curr)
    return res


