import math


def parse_particle(param):
    """Validate one (x, y, radius) triple and return it as a normalized tuple."""
    if len(param) != 3:
        raise ValueError("a particle needs exactly three values")
    x, y, radius = param
    for val in (x, y, radius):
        if not isinstance(val, int) or isinstance(val, bool):
            raise TypeError("particle values must be integers")
    if radius < 0:
        raise ValueError("radius must not be negative")
    return (x, y, radius)


def normalize(particles):
    """Turn the raw input into a list of checked particle tuples."""
    buf = []
    for idx, elem in enumerate(particles):
        try:
            buf.append(parse_particle(elem))
        except (TypeError, ValueError) as err:
            raise ValueError("particle %d is invalid: %s" % (idx, err))
    return buf


def distance(a, b):
    """Euclidean distance between the centers of two particles."""
    return math.hypot(a[0] - b[0], a[1] - b[1])


def collide(particles):
    ctx = normalize(particles)
    res = []
    cnt = len(ctx)
    for i in range(cnt):
        for j in range(i + 1, cnt):
            if distance(ctx[i], ctx[j]) < ctx[i][2] + ctx[j][2]:
                res.append((i, j))
    return res


def group_chains(pairs, num):
    """Merge colliding pairs into connected groups of particle indices."""
    parent = list(range(num))

    def find(pos):
        curr = pos
        while parent[curr] != curr:
            prev = curr
            curr = parent[curr]
            parent[prev] = curr
        return curr

    for left, right in pairs:
        parent[find(left)] = find(right)
    groups = {}
    for idx in range(num):
        groups.setdefault(find(idx), []).append(idx)
    return [sorted(group) for group in sorted(groups.values()) if len(group) > 1]


def report(particles):
    """Build a human readable summary of the collisions in a scene."""
    pairs = collide(particles)
    lines = ["%d collision(s) among %d particles" % (len(pairs), len(particles))]
    for left, right in pairs:
        tmp = distance(particles[left], particles[right])
        lines.append("  %d <-> %d at distance %.3f" % (left, right, tmp))
    for group in group_chains(pairs, len(particles)):
        lines.append("  cluster: " + ", ".join(str(i) for i in group))
    return "\n".join(lines)


def main():
    cfg = [
        [(0, 0, 1), (0, 0, 1)],
        [(0, 0, 2), (3, 0, 2), (10, 10, 1), (11, 10, 1), (5, 0, 1)],
        [(0, 0, 1), (5, 5, 1)],
    ]
    for num, scene in enumerate(cfg, start=1):
        msg = report(scene)
        print("scene %d: %s" % (num, collide(scene)))
        print(msg)


if __name__ == "__main__":
    main()

