CFG = {"levels": 256, "peak": 255}


def validate(param):
    if not isinstance(param, list) or not param:
        raise ValueError("image must be a non-empty list of rows")
    width = None
    for idx, row in enumerate(param):
        if not isinstance(row, list) or not row:
            raise ValueError("row %d must be a non-empty list" % idx)
        if width is None:
            width = len(row)
        elif len(row) != width:
            raise ValueError("row %d has inconsistent length" % idx)
        for elem in row:
            if isinstance(elem, bool) or not isinstance(elem, int):
                raise TypeError("row %d contains a non-integer pixel" % idx)
            if elem < 0 or elem > 255:
                raise ValueError("pixel %r out of range in row %d" % (elem, idx))


def histogram(image, cfg):
    buf = [0] * cfg["levels"]
    for row in image:
        for pixel in row:
            buf[pixel] += 1
    return buf


def cumulative(counts):
    running = []
    total = 0
    for cnt in counts:
        total += cnt
        running.append(total)
    return running


def build_lut(cdf, num, cfg):
    peak = cfg["peak"]
    lut = []
    for val in cdf:
        tmp = val * peak / float(num)
        lut.append(int(round(tmp)))
    return lut


def analyze(image, cfg):
    counts = histogram(image, cfg)
    cdf = cumulative(counts)
    num = cdf[-1]
    ctx = {"counts": counts, "cdf": cdf, "total": num, "lut": build_lut(cdf, num, cfg)}
    return ctx


def lut_segments(lut):
    segments = []
    pos = 0
    prev = lut[0]
    for idx in range(1, len(lut)):
        curr = lut[idx]
        if curr != prev:
            segments.append((pos, idx - 1, prev))
            pos = idx
            prev = curr
    segments.append((pos, len(lut) - 1, prev))
    return segments


def equalize(image):
    validate(image)
    lut = analyze(image, CFG)["lut"]
    res = []
    for row in image:
        res.append([lut[pixel] for pixel in row])
    return res


def report(image, out):
    ctx = analyze(image, CFG)
    lines = ["pixels: %d" % ctx["total"], "mapping:"]
    for seg in lut_segments(ctx["lut"]):
        lines.append("  %3d-%3d -> %3d" % seg)
    lines.append("result:")
    for row in out:
        lines.append("  " + " ".join("%3d" % pixel for pixel in row))
    msg = "\n".join(lines)
    return msg


def main():
    samples = [
        ("flat", [[10, 10, 10], [10, 10, 10], [10, 10, 10]]),
        ("ramp", [[0, 64, 128], [64, 128, 192], [128, 192, 255]]),
        ("broken", [[10, 300], [0, 5]]),
    ]
    for name, img in samples:
        print("== %s ==" % name)
        try:
            out = equalize(img)
        except (ValueError, TypeError) as err:
            print("rejected: %s" % err)
            continue
        print(report(img, out))


if __name__ == "__main__":
    main()

