DEFAULT_CFG = {"damping": 0.85, "iterations": 100, "tol": 1.0e-12, "digits": 3}


def merge_cfg(param):
    cfg = dict(DEFAULT_CFG)
    if param:
        cfg.update(param)
    if not 0.0 < cfg["damping"] < 1.0:
        raise ValueError("damping must lie strictly between 0 and 1")
    if cfg["iterations"] < 1:
        raise ValueError("iterations must be at least 1")
    return cfg


def normalize_links(links):
    clean = []
    for pos, elem in enumerate(links):
        tmp = tuple(elem)
        if len(tmp) != 2:
            raise ValueError("link #%d must have exactly two endpoints" % pos)
        clean.append(tmp)
    return clean


def build_graph(links):
    ctx = {"nodes": [], "out": {}}
    for src, dst in links:
        for name in (src, dst):
            if name not in ctx["out"]:
                ctx["nodes"].append(name)
                ctx["out"][name] = []
        ctx["out"][src].append(dst)
    return ctx


def pagerank(links, param=None):
    cfg = merge_cfg(param)
    ctx = build_graph(normalize_links(links))
    nodes = ctx["nodes"]
    num = len(nodes)
    if num == 0:
        return []
    damping = cfg["damping"]
    curr = {name: 1.0 for name in nodes}
    idx = 0
    err = float("inf")
    while idx < cfg["iterations"] and err >= cfg["tol"]:
        prev = curr
        buf = {name: 1.0 - damping for name in nodes}
        for name in nodes:
            targets = ctx["out"][name]
            cnt = len(targets)
            if cnt == 0:
                val = damping * prev[name] / num
                for other in nodes:
                    buf[other] += val
            else:
                val = damping * prev[name] / cnt
                for dst in targets:
                    buf[dst] += val
        err = max(abs(buf[name] - prev[name]) for name in nodes)
        curr = buf
        idx += 1
    res = [(name, round(curr[name], cfg["digits"])) for name in sorted(nodes)]
    return res


def format_report(res):
    ranked = sorted(res, key=lambda elem: (-elem[1], elem[0]))
    lines = []
    for pos, elem in enumerate(ranked, 1):
        msg = "{:>2}. {:<8} {:.3f}".format(pos, elem[0], elem[1])
        lines.append(msg)
    return "\n".join(lines)


