def validate(ratings):
    if not ratings:
        raise ValueError("ratings must not be empty")
    for pos in range(len(ratings)):
        elem = ratings[pos]
        if len(elem) != 3:
            raise ValueError("entry %d must be (user, movie, rating)" % pos)
        val = elem[2]
        if not isinstance(val, (int, float)):
            raise ValueError("rating at %d is not numeric" % pos)


def build_ctx(ratings):
    ctx = {"users": [], "by_user": {}}
    for entry in ratings:
        name, movie, val = entry[0], entry[1], entry[2]
        if name not in ctx["by_user"]:
            ctx["users"].append(name)
            ctx["by_user"][name] = {}
        ctx["by_user"][name][movie] = val
    return ctx


def weight(diff, param):
    max_diff, scale = param
    if diff > max_diff:
        return 0.0
    return 1.0 - diff / scale


def similarity(target_map, other_map, cfg):
    tmp = []
    for curr in target_map:
        if curr not in other_map:
            continue
        diff = abs(target_map[curr] - other_map[curr])
        w = weight(diff, cfg["tolerance"])
        if w > 0.0:
            tmp.append(w)
    cnt = len(tmp)
    if cnt < cfg["min_overlap"]:
        return None
    res = sum(tmp) / cnt
    if res < cfg["min_sim"]:
        return None
    return res


def recommend(ratings):
    validate(ratings)
    cfg = {"tolerance": (2.0, 5.0), "min_overlap": 1, "min_sim": 0.5}
    ctx = build_ctx(ratings)
    target = ctx["users"][0]
    target_map = ctx["by_user"][target]
    scores = {}
    first_pos = {}
    num = 0
    for idx, user in enumerate(ctx["users"]):
        if user == target:
            continue
        other_map = ctx["by_user"][user]
        sim = similarity(target_map, other_map, cfg)
        if sim is None:
            continue
        num += 1
        for elem in other_map:
            if elem in target_map:
                continue
            prev = scores.get(elem, 0.0)
            scores[elem] = prev + sim * other_map[elem]
            first_pos.setdefault(elem, idx)
    if num == 0:
        err = "no similar users found for %s" % target
        print(err)
        return []
    return sorted(scores, key=lambda m: (-scores[m], first_pos[m], m))


def format_report(target, res):
    buf = ["recommendations for %s:" % target]
    if not res:
        buf.append("  (none)")
    rank = 1
    for movie in res:
        buf.append("  %d. %s" % (rank, movie))
        rank += 1
    return "\n".join(buf)


def main():
    ratings = [("Alice", "Movie1", 5), ("Bob", "Movie1", 4), ("Bob", "Movie2", 5)]
    res = recommend(ratings)
    msg = format_report(ratings[0][0], res)
    print(msg)


if __name__ == "__main__":
    main()

