from math import atan2, hypot
import sys

SCAN_CTX = {"scanned": 0, "discarded": 0}

DEFAULT_POINTS = [(0, 0), (2, 2), (0, 2), (2, 0), (1, 1)]


def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def parse_points(args):
    tmp = []
    idx = 0
    while idx < len(args):
        param = args[idx].split(",")
        if len(param) != 2:
            msg = "token %r is not of the form 'x,y'" % args[idx]
            raise ValueError(msg)
        tmp.append((float(param[0]), float(param[1])))
        idx += 1
    return tmp


def graham(points):
    seen = set()
    uniq = []
    for elem in points:
        if len(elem) != 2:
            raise ValueError("each point needs exactly two coordinates")
        tmp = (elem[0], elem[1])
        if tmp not in seen:
            seen.add(tmp)
            uniq.append(tmp)
    pivot = min(uniq, key=lambda q: (q[1], q[0]))
    order = sorted(uniq, key=lambda q: (atan2(q[1] - pivot[1], q[0] - pivot[0]),
                                        hypot(q[1] - pivot[1], q[0] - pivot[0])))
    SCAN_CTX["scanned"] = len(order)
    SCAN_CTX["discarded"] = 0
    if len(order) < 3:
        return list(order)
    buf = [order[0], order[1]]
    cnt = 0
    pos = 2
    while pos < len(order):
        curr = order[pos]
        while len(buf) >= 2:
            prev = buf[-1]
            val = cross(buf[-2], prev, curr)
            if val > 0:
                break
            buf.pop()
            cnt += 1
        buf.append(curr)
        pos += 1
    SCAN_CTX["discarded"] = cnt
    res = [tuple(v) for v in buf]
    return res


def describe(hull, cfg):
    num = 0.0
    idx = 0
    while idx < len(hull):
        curr = hull[idx]
        prev = hull[idx - 1]
        num += prev[0] * curr[1] - curr[0] * prev[1]
        idx += 1
    parts = ["(%g, %g)" % (elem[0], elem[1]) for elem in hull]
    msg = "%s: %s" % (cfg["label"], " -> ".join(parts))
    return msg + " | area=%.*f" % (cfg["digits"], abs(num) / 2.0)


def main():
    cfg = {"label": "hull", "digits": 2}
    try:
        data = parse_points(sys.argv[1:]) or DEFAULT_POINTS
    except ValueError as err:
        print("bad input: %s" % err)
        return 1
    res = graham(data)
    print(describe(res, cfg))
    ctx = SCAN_CTX
    print("scanned %d unique points, discarded %d" % (ctx["scanned"], ctx["discarded"]))
    return 0


if __name__ == "__main__":
    sys.exit(main())

