import sys

DEFAULT_MAX_DELTA = 64
DEFAULT_ESCAPE = 255


def make_cfg(max_delta=DEFAULT_MAX_DELTA, escape=DEFAULT_ESCAPE):
    if max_delta < 1:
        err = "max_delta must be a positive integer"
        raise ValueError(err)
    if escape < 0:
        msg = "escape code must be non-negative"
        raise ValueError(msg)
    return {"max_delta": max_delta, "escape": escape}


def override(cfg, changes):
    res = dict(cfg)
    for param in changes:
        res[param] = int(changes[param])
    return res


def delta(data, cfg=None, ctx=None):
    cfg = make_cfg() if cfg is None else cfg
    ctx = {} if ctx is None else ctx
    ctx["escapes"] = []
    buf = []
    cnt = 0
    if not data:
        msg = "delta: empty input sequence, nothing to compress"
        print(msg, file=sys.stderr)
        return (cnt, buf)
    prev = int(data[0])
    buf.append(prev)
    pos = 1
    for elem in data[1:]:
        curr = int(elem)
        tmp = curr - prev
        if abs(tmp) > cfg["max_delta"]:
            buf.append(cfg["escape"])
            buf.append(curr)
            ctx["escapes"].append(pos)
            cnt += 1
            pos += 2
        else:
            buf.append(tmp)
            pos += 1
        prev = curr
