import sys

DEFAULT_MAX_DELTA = 64
DEFAULT_ESCAPE = 255


def make_configuration(max_delta=DEFAULT_MAX_DELTA, escape=DEFAULT_ESCAPE):
    if max_delta < 1:
        error = "max_delta must be a positive integer"
        raise ValueError(error)
    if escape < 0:
        message = "escape code must be non-negative"
        raise ValueError(message)
    return {"max_delta": max_delta, "escape": escape}


def override(configuration, changes):
    result = dict(configuration)
    for parameter in changes:
        result[parameter] = int(changes[parameter])
    return result


def delta(data, configuration=None, context=None):
    configuration = make_configuration() if configuration is None else configuration
    context = {} if context is None else context
    context["escapes"] = []
    buffer = []
    count = 0
    if not data:
        message = "delta: empty input sequence, nothing to compress"
        print(message, file=sys.stderr)
