import sys


def _normalize(param):
    if len(param) != 4:
        msg = "rectangle needs 4 coordinates, got {}".format(len(param))
        raise ValueError(msg)
    x1, y1, x2, y2 = param
    return min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)


def _vertical_edges(rectangles):
    res = []
    for elem in rectangles:
        x1, y1, x2, y2 = _normalize(elem)
        if x1 == x2 or y1 == y2:
            continue
        res.append((x1, 1, y1, y2))
        res.append((x2, -1, y1, y2))
    res.sort(key=lambda edge: (edge[0], -edge[1]))
    return res


def _covered_span(buf):
    val = 0
    curr = None
    for lo, hi in sorted(buf):
        if curr is None or lo > curr[1]:
            if curr is not None:
                val += curr[1] - curr[0]
            curr = [lo, hi]
        elif hi > curr[1]:
            curr[1] = hi
    if curr is not None:
        val += curr[1] - curr[0]
    return val


def overlap(rectangles, ctx=None):
    edges = _vertical_edges(rectangles)
    if ctx is not None:
        ctx["edges"] = 0
    if not edges:
        return 0
    buf = []
    res = 0
    cnt = 0
    idx = 0
    prev = edges[0][0]
    while idx < len(edges):
        elem = edges[idx]
        curr = elem[0]
        if curr != prev:
            tmp = _covered_span(buf)
            res += tmp * (curr - prev)
            prev = curr
        if elem[1] == 1:
            buf.append((elem[2], elem[3]))
        else:
            buf.remove((elem[2], elem[3]))
        cnt += 1
        idx += 1
    if ctx is not None:
        ctx["edges"] = cnt
    return int(res)


