import logging

LOG = logging.getLogger("viterbi")

MODEL_CFG = {
    "start": {"Rainy": 0.8, "Sunny": 0.2},
    "trans": {
        "Rainy": {"Rainy": 0.3, "Sunny": 0.7},
        "Sunny": {"Rainy": 0.7, "Sunny": 0.3},
    },
    "emit": {
        "Rainy": {"walk": 0.4, "shop": 0.1, "clean": 0.5},
        "Sunny": {"walk": 0.2, "shop": 0.7, "clean": 0.1},
    },
}


def parse_observations(param):
    if isinstance(param, str):
        return [elem.strip() for elem in param.split(",") if elem.strip()]
    if isinstance(param, (list, tuple)):
        return [str(elem).strip() for elem in param]
    err = "observations must be a comma separated string, a list or a tuple"
    raise TypeError(err)


def emission_of(cfg, state, elem):
    tmp = cfg["emit"][state]
    if elem not in tmp:
        return None
    return tmp[elem]


def is_known(cfg, elem):
    return any(elem in tmp for tmp in cfg["emit"].values())


def viterbi(observations):
    cfg = MODEL_CFG
    obs = parse_observations(observations)
    if not obs:
        return []
    states = list(cfg["start"])
    ctx = []
    prev = {}
    cnt = 0
    for idx, elem in enumerate(obs):
        cnt += 1
        if not is_known(cfg, elem):
            msg = "unknown observation %r at step %d, using uniform emission"
            LOG.warning(msg, elem, idx)
        curr = {}
        buf = {}
        for state in states:
            val = emission_of(cfg, state, elem)
            if val is None:
                num = len(cfg["emit"][state])
                val = 1.0 / num
            if idx == 0:
                curr[state] = cfg["start"][state] * val
                buf[state] = None
                continue
            best = 0.0
            src = None
            for cand in states:
                tmp = prev[cand] * cfg["trans"][cand][state]
                if tmp > best:
                    best = tmp
                    src = cand
            curr[state] = best * val
            buf[state] = src
        ctx.append(buf)
        prev = curr
    LOG.info("processed %d observations", cnt)
    res = []
    curr_state = max(prev, key=prev.get)
    for pos in range(len(ctx) - 1, -1, -1):
        res.append(curr_state)
        prev_state = ctx[pos][curr_state]
        if prev_state is None:
            break
        curr_state = prev_state
    res.reverse()
    return res


def format_path(obs, res):
    buf = []
    for idx, elem in enumerate(obs):
        buf.append("{}:{}->{}".format(idx, elem, res[idx]))
    return " | ".join(buf)


def main():
    logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
    for param in ("walk,shop,clean", "walk,dance,clean"):
        res = viterbi(param)
        print(res)
        print(format_path(parse_observations(param), res))


if __name__ == "__main__":
    main()

