MAX_CODES = 4096


def _validate(text, cfg):
    if not isinstance(text, str):
        raise TypeError("lzw() expects a string")
    if cfg < 256:
        raise ValueError("dictionary size must leave room for the 256 base codes")
    for pos, ch in enumerate(text):
        num = ord(ch)
        if num > 255:
            raise ValueError(f"character {ch!r} at position {pos} is outside latin-1")


def lzw(text, cfg=MAX_CODES):
    """Compress text into a list of integer codes."""
    _validate(text, cfg)
    ctx = {chr(i): i for i in range(256)}
    cnt = 256
    buf = []
    prev = ""
    for idx in range(len(text)):
        curr = text[idx]
        elem = prev + curr
        if elem in ctx:
            prev = elem
        else:
            buf.append(ctx[prev])
            if cnt < cfg:
                ctx[elem] = cnt
                cnt += 1
            prev = curr
    if prev:
        buf.append(ctx[prev])
    return buf


def unlzw(codes, cfg=MAX_CODES):
    """Rebuild the original string from a list of LZW codes."""
    if not codes:
        return ""
    ctx = {i: chr(i) for i in range(256)}
    cnt = 256
    prev = ctx[codes[0]]
    buf = [prev]
    for idx in range(1, len(codes)):
        param = codes[idx]
        if param in ctx:
            curr = ctx[param]
        elif param == cnt:
            curr = prev + prev[0]
        else:
            raise ValueError(f"code {param} at position {idx} is undefined")
        buf.append(curr)
        if cnt < cfg:
            ctx[cnt] = prev + curr[0]
            cnt += 1
        prev = curr
    return "".join(buf)


def format_report(text, res):
    tmp = len(text) * 8
    val = len(res) * 16
    ratio = val / tmp if tmp else 1.0
    return f"{len(text)} chars -> {len(res)} codes ({tmp} bits -> {val} bits, {ratio:.2f}x)"


def main():
    cfg = 512
    samples = ["ABABABA", "TOBEORNOTTOBEORTOBEORNOT", "aaaaaaaaaa", "sn\u2713w"]
    for idx, sample in enumerate(samples, 1):
        try:
            res = lzw(sample, cfg)
        except ValueError as err:
