import logging

LOG = logging.getLogger("huffman")

CODE_CFG = {"left": "0", "right": "1"}


def _leaf(sym, num):
    return {"sym": sym, "freq": num, "kids": None}


def _build_leaves(frequencies):
    if not frequencies:
        raise ValueError("huffman() needs at least one (symbol, frequency) pair")
    tmp = []
    for idx in range(len(frequencies)):
        elem = frequencies[idx]
        sym = elem[0]
        num = elem[1]
        if num <= 0:
            err = "frequency for %r at index %d must be positive, got %r" % (sym, idx, num)
            raise ValueError(err)
        tmp.append(_leaf(sym, num))
    return sorted(tmp, key=lambda node: -node["freq"])


def _insert_sorted(nodes, node):
    val = node["freq"]
    pos = 0
    while pos < len(nodes) and nodes[pos]["freq"] >= val:
        pos += 1
    nodes.insert(pos, node)


def _walk(node, buf, res, cfg):
    if node["kids"] is None:
        res[node["sym"]] = buf or cfg["left"]
        return
    left, right = node["kids"]
    _walk(left, buf + cfg["left"], res, cfg)
    _walk(right, buf + cfg["right"], res, cfg)


def huffman(frequencies):
    nodes = _build_leaves(frequencies)
    cnt = 0
    while len(nodes) > 1:
        curr = nodes.pop()
        prev = nodes.pop()
        val = prev["freq"] + curr["freq"]
        _insert_sorted(nodes, {"sym": None, "freq": val, "kids": (prev, curr)})
        cnt += 1
    ctx = nodes[0]
    res = {}
    _walk(ctx, "", res, CODE_CFG)
    msg = "built prefix code for %d symbols in %d merges" % (len(res), cnt)
    LOG.info(msg)
    return res


def encode(text, codes):
    buf = []
    for ch in text:
        if ch not in codes:
            err = "symbol %r has no code in the given table" % ch
            raise KeyError(err)
        buf.append(codes[ch])
    return "".join(buf)


def main():
    logging.basicConfig(level=logging.INFO, format="%(message)s")
    param = [("A", 5), ("B", 2), ("C", 2)]
    res = huffman(param)
    for sym in sorted(res):
        print("%s -> %s" % (sym, res[sym]))
    text = "AABBCA"
    bits = encode(text, res)
    print("%s encoded as %s (%d bits vs %d raw)" % (text, bits, len(bits), 8 * len(text)))


if __name__ == "__main__":
    main()

