import math
import sys

DEFAULT_CFG = {"steps": 20, "digits": 4}


def validate_control(control):
    if not control:
        raise ValueError("control needs at least one point")
    num = len(control[0])
    for idx, elem in enumerate(control):
        if len(elem) != num:
            msg = f"point {idx} has dimension {len(elem)}, expected {num}"
            raise ValueError(msg)


def de_casteljau(control, param):
    num = len(control[0])
    curr = list(control)
    while len(curr) > 1:
        prev = curr
        curr = []
        for pos in range(len(prev) - 1):
            tmp = prev[pos]
            nxt = prev[pos + 1]
            elem = []
            for idx in range(num):
                val = tmp[idx] + (nxt[idx] - tmp[idx]) * param
                elem.append(val)
            curr.append(tuple(elem))
    return curr[0]


def bezier(control, params=None, cfg=None):
    cfg = dict(DEFAULT_CFG, **(cfg or {}))
    validate_control(control)
    if params is None:
        num = cfg["steps"]
        params = [pos / num for pos in range(num + 1)]
    ctx = []
    for param in params:
        if not 0.0 <= param <= 1.0:
            msg = f"parameter out of range: {param}"
            raise ValueError(msg)
        ctx.append(tuple(round(val, 10) for val in de_casteljau(control, param)))
    return ctx


def summarize(control, params=None, cfg=None):
    points = bezier(control, params=params, cfg=cfg)
    prev = points[0]
    total = 0.0
    cnt = 0
    for curr in points[1:]:
        tmp = sum((curr[idx] - prev[idx]) ** 2 for idx in range(len(curr)))
        total += math.sqrt(tmp)
        cnt += 1
        prev = curr
    return f"{cnt} segments, polyline length {total:.4f}"


def format_points(points, cfg=None):
    cfg = dict(DEFAULT_CFG, **(cfg or {}))
    buf = []
    for pos, elem in enumerate(points):
        coords = ", ".join(f"{val:.{cfg['digits']}f}" for val in elem)
        buf.append(f"[{pos:3d}] ({coords})")
    return "\n".join(buf)


def main():
    cfg = {"steps": 8}
    control = [(0, 0), (0, 1), (1, 1)]
    print(bezier(control, params=[0.5]))
    if len(sys.argv) > 1:
        try:
            param = float(sys.argv[1])
        except ValueError as err:
            print(f"bad parameter: {err}")
            return 1
        print(bezier(control, params=[param]))
    print(format_points(bezier(control, cfg=cfg), cfg=cfg))
    print(summarize(control, cfg=cfg))
    return 0


if __name__ == "__main__":
    sys.exit(main())

