import logging

LOG = logging.getLogger(__name__)

MODEL_CFG = {
    "states": ["coin_a", "coin_b"],
    "initial": {"coin_a": 0.5, "coin_b": 0.5},
    "transitions": {
        "coin_a": {"coin_a": 0.5, "coin_b": 0.5},
        "coin_b": {"coin_a": 0.5, "coin_b": 0.5},
    },
    "emissions": {
        "coin_a": {"heads": 0.5, "tails": 0.5},
        "coin_b": {"heads": 0.5, "tails": 0.5},
    },
}


def build_ctx(cfg):
    states = sorted(cfg["states"])
    num = len(states)
    if num == 0:
        raise ValueError("model needs at least one state")
    for state in states:
        row = cfg["transitions"].get(state)
        if row is None:
            err = "missing transition row for state " + state
            raise ValueError(err)
        tmp = sum(row.values())
        if abs(tmp - 1.0) > 1e-9:
            raise ValueError("transition rates for %s do not sum to 1" % state)
    return {
        "states": states,
        "initial": cfg["initial"],
        "transitions": cfg["transitions"],
        "emissions": cfg["emissions"],
    }


def check_symbols(ctx, sequence):
    for pos, elem in enumerate(sequence):
        for state in ctx["states"]:
            if elem not in ctx["emissions"][state]:
                msg = "unknown event %r" % (elem,)
                err = "%s at position %d" % (msg, pos)
                raise ValueError(err)


def step_sum(ctx, prev, state):
    tmp = 0.0
    for src, prob in prev.items():
        param = ctx["transitions"][src][state]
        tmp += prob * param
    return tmp


def forward(sequence):
    ctx = build_ctx(MODEL_CFG)
    check_symbols(ctx, sequence)
    curr = dict(ctx["initial"])
    for idx, elem in enumerate(sequence):
        prev = curr
        curr = {}
        for state in ctx["states"]:
            if idx == 0:
                tmp = prev[state]
            else:
                tmp = step_sum(ctx, prev, state)
            val = ctx["emissions"][state][elem]
            prob = tmp * val
            if prob == 0.0:
                LOG.debug("zero probability in %s at step %d", state, idx)
            curr[state] = prob
    total = sum(curr.values())
    return float(total)


def report(sequence, res):
    buf = []
    for pos, elem in enumerate(sequence):
        buf.append("  [%d] %s" % (pos, elem))
    msg = "\n".join(buf)
    return "%d events:\n%s\nprobability = %.6f" % (len(sequence), msg, res)


def main():
    logging.basicConfig(level=logging.DEBUG)
    samples = [["heads", "tails", "heads"], ["heads", "heads"], ["tails"]]
    cnt = 0
    for seq in samples:
        res = forward(seq)
        print(report(seq, res))
        cnt += 1
    print("scored %d sequences" % cnt)


if __name__ == "__main__":
    main()

