    "localhost": "127.0.0.1",
    "mirror.net": "10.0.0.7",
}

ALIAS_PARAM = {
    "www.example.com": "example.com",
    "web.example.com": "www.example.com",
    "docs.example.com": "iana.org",
    "loop-a.test": "loop-b.test",
    "loop-b.test": "loop-c.test",
    "loop-c.test": "loop-a.test",
    "old.mirror.net": "mirror.net",
}

CFG = {"max_hops": 3, "fallback": "0.0.0.0"}


def normalize(elem):
    tmp = str(elem).strip().lower().rstrip(".")
    if not tmp:
        raise ValueError("empty domain name")
    return tmp


def follow(domain, param, cfg):
    curr = domain
    cnt = 0
    while curr in param:
        curr = param[curr]
        cnt += 1
        if cnt > cfg["max_hops"]:
            return None, cnt
    return curr, cnt


def lookup(domain, ctx, cfg):
    return ctx.get(domain, cfg["fallback"])


def timeout_message(pos, domain, cnt):
    return "timeout: query #%d '%s' unresolved after %d alias steps" % (pos, domain, cnt)


def resolve(queries):
    buf = []
    timeouts = []
    for idx, elem in enumerate(queries):
        try:
            curr = normalize(elem)
