            timeouts.append("query #%d rejected: %s" % (idx, err))
            continue
        canonical, cnt = follow(curr, ALIAS_PARAM, CFG)
        if canonical is None:
            msg = timeout_message(idx, curr, cnt)
            timeouts.append(msg)
            break
        val = lookup(canonical, ADDR_CTX, CFG)
        buf.append((curr, canonical, val))
    res = (buf, timeouts)
    return res


