        if canonical == name:
            lines.append("  %s -> %s" % (name, addr))
        else:
            lines.append("  %s -> %s -> %s" % (name, canonical, addr))
    for text in timeouts:
        lines.append("  ! " + text)
    return "\n".join(lines)


