def fmt_clock(num):
    if num < 0:
        raise ValueError("duration cannot be negative: %d" % num)
    tmp = divmod(num, 60)
    return "%d:%02d" % tmp


def check_cfg(cfg):
    for param in sorted(cfg):
        val = cfg[param]
        if not isinstance(val, int) or val <= 0:
            raise ValueError("bad duration for %r: %r" % (param, val))


def parse_interval(raw):
    if not isinstance(raw, str):
        raise TypeError("interval must be a string, got %r" % (raw,))
