    return val


def time(intervals):
    check_cfg(CFG)
    buf = []
    ctx = {"run": 0, "walk": 0}
    curr = 0
    for idx in range(len(intervals)):
        elem = parse_interval(intervals[idx])
        param = CFG[elem]
