CFG = {"rate": 0.015, "min_threshold": 100.0, "fee": 5.00}


def parse_balances(raw):
    """Convert the raw daily values into floats, rejecting unusable entries."""
    buf = []
    for pos, elem in enumerate(raw):
        try:
            val = float(elem)
        except (TypeError, ValueError) as err:
            raise ValueError("day %d holds an invalid balance %r (%s)" % (pos, elem, err))
        buf.append(val)
    if not buf:
        raise ValueError("no daily balances supplied")
    return buf


def interest_of(balance, param):
    """Interest earned on a qualifying balance for the given rate parameter."""
    return round(balance * param, 2)


def calculate(balances):
    cfg = CFG
    values = parse_balances(balances)
    buf = []
    tmp = 0.0
    cnt = 0
    prev = values[0]
    for idx, curr in enumerate(values):
        delta = curr - prev
        if curr >= cfg["min_threshold"] and delta >= 0.0:
            tmp += interest_of(curr, cfg["rate"])
        else:
            tmp -= cfg["fee"]
            cnt += 1
            msg = "day %d: balance %.2f (change %+.2f) broke the rule, fee %.2f charged (penalty #%d)" % (
                idx, curr, delta, cfg["fee"], cnt)
            buf.append(msg)
        prev = curr
    num = round(values[-1] + tmp, 2)
    return (num, buf)


def format_report(label, res):
    val, warnings = res
    lines = ["[%s] net balance: %.2f" % (label, val)]
    if warnings:
        lines.append("  %d warning(s):" % len(warnings))
        for msg in warnings:
            lines.append("    - " + msg)
    else:
        lines.append("  no deductions applied")
    return "\n".join(lines)


def main():
    datasets = [
        {"label": "week-1", "data": [250.0, 300.0, 280.0, 340.5, 95.25]},
        {"label": "week-2", "data": ["120", "130.75", "131", "400"]},
        {"label": "week-3", "data": [500.0, "n/a", 510.0]},
    ]
    for ctx in datasets:
        try:
            res = calculate(ctx["data"])
        except ValueError as err:
            print("[%s] skipped: %s" % (ctx["label"], err))
            continue
        print(format_report(ctx["label"], res))


if __name__ == "__main__":
    main()

