    num = (idx + 1) * CFG["block_minutes"]
    return "{:02d}:{:02d}".format((num // 60) % 24, num % 60)


def parse_intervals(raw):
    """Turn a comma separated pedometer dump into a list of step counts."""
    res = []
    for elem in raw.split(","):
        tmp = elem.strip()
        try:
            val = int(tmp)
        except ValueError as err:
            raise ValueError("not a step number: {!r}".format(tmp)) from err
        if val < 0:
            raise ValueError("negative step number: {}".format(val))
        res.append(val)
    return res


def count(intervals):
    param = CFG["daily_goal"]
    total = 0
    val = 0
    pos = 0
    prev = 0
    idle_count = 0
    tmp = 0
    buf = []
    for idx in range(len(intervals)):
        curr = intervals[idx]
        total += curr
        window = prev + curr
        if window > val:
            val = window
            pos = idx
        if curr == 0:
            idle_count += 1
            if tmp:
                buf.append(tmp)
                tmp = 0
        else:
            idle_count = 0
            tmp += curr
        prev = curr
    if tmp:
        buf.append(tmp)
    print("Busiest 20 minutes end at {} with {} steps".format(block_label(pos), val))
    if idle_count >= CFG["idle_alert"]:
        print("You have been idle for the last {} intervals.".format(idle_count))
    if total >= param:
        msg = "Congratulations, you walked {} steps and beat your goal of {}!".format(total, param)
        print(msg)
    return (total, buf)


def format_report(res):
