SUPPORTED_COLORS = {'r': 'red', 'g': 'green', 'b': 'blue', 'y': 'yellow'}
DEFAULT_CFG = {'tension': 1, 'border': '|'}


def validate_pattern(pattern):
    """Return the over/under rules as a list of positive integers."""
    tmp = []
    for elem in pattern:
        if not isinstance(elem, int) or isinstance(elem, bool) or elem <= 0:
            raise ValueError("pattern rules must be positive integers, got %r" % (elem,))
        tmp.append(elem)
    if not tmp:
        raise ValueError("pattern must contain at least one rule")
    return tmp


def build_segments(rules):
    """Turn the over/under rules into the visual segments of a single row."""
    buf = []
    for idx, num in enumerate(rules):
        buf.append(('O' if idx % 2 == 0 else 'U') * num)
    return buf


def weave(threads, pattern, cfg=None, ctx=None):
    """Weave `threads` according to `pattern` and return the woven layout."""
    cfg = dict(DEFAULT_CFG, **(cfg or {}))
    rules = validate_pattern(pattern)
    tension = cfg['tension']
    if not isinstance(tension, int) or tension < 1:
        raise ValueError("tension must be an integer of at least 1")
    if ctx is None:
        ctx = {}
    ctx.setdefault('warnings', [])
    ctx['rows'] = 0

    res = []
    prev = None
    for idx, curr in enumerate(threads):
        pos = idx + 1
        if tension > 1 and pos % tension == 0:
            continue
        if curr not in SUPPORTED_COLORS:
            msg = "warning: unsupported color %r at position %d" % (curr, pos)
            ctx['warnings'].append(msg)
            continue
        tmp = build_segments(rules)
        if curr == prev:
            tmp.insert(0, cfg['border'])
            tmp.append(cfg['border'])
        res.append("%-6s %s" % (SUPPORTED_COLORS[curr], ''.join(tmp)))
        ctx['rows'] += 1
        prev = curr
    return res


def render(res, ctx):
    """Format the woven layout together with the run statistics."""
    buf = ["fabric:"]
    for elem in res:
        buf.append("  " + elem)
    buf.append("successful rows: %d" % ctx['rows'])
    for msg in ctx['warnings']:
        buf.append("  " + msg)
    return "\n".join(buf)


def main():
    ctx = {}
    res = weave("rrr", [2, 1], {'tension': 2}, ctx)
    print(render(res, ctx))

    ctx = {}
    res = weave("rgxbb", [3, 2, 1], {'border': '#'}, ctx)
    print(render(res, ctx))

    try:
        weave("rg", [2, 0])
    except ValueError as err:
        print("rejected pattern: %s" % err)


if __name__ == '__main__':
    main()

