    "minerals": {
        "sand": 0.10,
        "clay": 0.35,
        "gravel": 0.08,
        "silt": 0.22,
        "loam": 0.28,
    },
}


def parse_layer(elem, cfg):
    """Split a soil description into (type name, mineral concentration)."""
    tmp = str(elem).strip().lower()
    parts = tmp.split(":")
    name = parts[0].strip()
    if len(parts) > 1:
        try:
            conc = float(parts[1])
        except ValueError as err:
            msg = "invalid mineral reading in layer %r" % (elem,)
            raise ValueError(msg) from err
    else:
        conc = cfg["minerals"].get(name, cfg["default_mineral"])
    return name, conc


def analyze(samples, depths, cfg=None):
    """Return the significant geological transitions of a drilling core."""
    ctx = dict(DEFAULT_CFG)
    if cfg:
        ctx.update(cfg)
    num = len(samples)
    if num != len(depths):
        msg = "samples (%d) and depths (%d) must have equal length" % (num, len(depths))
        raise ValueError(msg)
    res = []
    prev = None
    prev_conc = 0.0
    prev_pos = 0.0
    for idx, elem in enumerate(samples):
        pos = float(depths[idx])
        curr, conc = parse_layer(elem, ctx)
        if curr in ctx["void_markers"]:
            msg = "unexpected hollow zone at %.1f m (layer %d)" % (pos, idx)
            res.append({"kind": "hollow", "depth": pos, "layer": idx, "message": msg})
            prev = None
            continue
        if prev is not None and curr != prev:
            diff = abs(conc - prev_conc)
            if diff > ctx["min_delta"]:
                span = max(pos - prev_pos, ctx["min_span"])
                tmp = diff / span
                res.append({
                    "kind": "transition",
                    "depth": pos,
                    "layer": idx,
                    "from": prev,
                    "to": curr,
                    "delta": round(diff, 3),
                    "gradient": round(tmp, 4),
                })
        prev = curr
        prev_conc = conc
        prev_pos = pos
    return res


