    buf = []
    for rec in res:
        if rec["kind"] == "hollow":
            buf.append("WARN   %s" % rec["message"])
        else:
            line = "%6.1f m  %-7s -> %-7s  delta=%.3f  grad=%.4f/m" % (
                rec["depth"], rec["from"], rec["to"], rec["delta"], rec["gradient"])
            buf.append(line)
    if not buf:
        buf.append("no significant transitions found")
    return "\n".join(buf)


