import math

CFG = {
    "unit_volume": 250.0,
    "capacity": 450.0,
    "iterations": 500,
    "step": 0.05,
    "tol": 1e-6,
}

ANCHORS = [(0.0, 0.0), (60.0, 120.0), (120.0, 180.0), (180.0, 240.0),
           (240.0, 270.0), (300.0, 300.0), (360.0, 360.0)]


def hue_of(color):
    r, g, b = [ch / 255.0 for ch in color]
    high = max(r, g, b)
    span = high - min(r, g, b)
    if span == 0.0:
        return 0.0
    if high == r:
        tmp = ((g - b) / span) % 6.0
    elif high == g:
        tmp = (b - r) / span + 2.0
    else:
        tmp = (r - g) / span + 4.0
    return (tmp * 60.0) % 360.0


def ryb_angle(color):
    dist = (60.0 - hue_of(color)) % 360.0
    for idx in range(1, len(ANCHORS)):
        prev = ANCHORS[idx - 1]
        curr = ANCHORS[idx]
        if dist <= curr[0]:
            pos = (dist - prev[0]) / (curr[0] - prev[0])
            return prev[1] + pos * (curr[1] - prev[1])
    return ANCHORS[-1][1]


def wheel_vector(color):
    ang = math.radians(ryb_angle(color))
    return (math.cos(ang), math.sin(ang))


def solve_weights(vecs, goal, cfg):
    num = len(vecs)
    val = 1.0 / num
    weights = [val] * num
    cnt = 0
    while cnt < cfg["iterations"]:
        cnt += 1
        res = [sum(w * v[k] for w, v in zip(weights, vecs)) for k in (0, 1)]
        err = [res[0] - goal[0], res[1] - goal[1]]
        if math.hypot(err[0], err[1]) < cfg["tol"]:
            break
        for idx, elem in enumerate(vecs):
            grad = 2.0 * (err[0] * elem[0] + err[1] * elem[1])
            weights[idx] = max(0.0, weights[idx] - cfg["step"] * grad)
    return weights, cnt


def mix(colors, target):
    if not colors:
        raise ValueError("no base pigments supplied")
    cfg = CFG
    buf = [wheel_vector(elem) for elem in colors]
    weights, cnt = solve_weights(buf, wheel_vector(target), cfg)
    vols = []
    total = 0.0
    for param in weights:
        vol = param * cfg["unit_volume"]
        total += vol
        vols.append(vol)
    if total <= 0.0:
        raise ValueError("target hue unreachable from the given pigments")
    if total > cfg["capacity"]:
        ctx = f"{len(colors)} pigments toward rgb{target}"
        msg = f"OVERFLOW: {total:.1f} ml for {ctx} exceeds the {cfg['capacity']:.1f} ml can"
        print(msg)
        factor = cfg["capacity"] / total
        vols = [v * factor for v in vols]
    print(f"weights aligned after {cnt} adjustment passes")
    return [round(v, 2) for v in vols]


def format_report(colors, target, vols):
    lines = [f"Target rgb{target}"]
    for idx, elem in enumerate(colors):
        lines.append(f"  pigment {idx}: rgb{elem} -> {vols[idx]:.2f} ml")
    lines.append(f"  dispensed total: {sum(vols):.2f} ml")
    return "\n".join(lines)


def main():
    jobs = [
        ([(0, 0, 255), (255, 255, 0)], (0, 255, 0)),
        ([(255, 0, 0), (255, 255, 0), (0, 0, 255)], (255, 128, 0)),
    ]
    for colors, target in jobs:
        res = mix(colors, target)
        print(format_report(colors, target, res))


if __name__ == "__main__":
    main()

