PIGMENT_SCALE = {
    "vibrant green": 4,
    "green": 3,
    "pale green": 2,
    "bleached": 1,
    "pale white": 0,
}


def normalize_pigment(param):
    tmp = str(param).strip().lower()
    if tmp not in PIGMENT_SCALE:
        raise ValueError("unknown pigmentation %r" % param)
    return PIGMENT_SCALE[tmp]


def parse_record(elem, idx):
    pos = elem.get("site")
    if not pos:
        raise ValueError("record %d has no site" % idx)
    val = normalize_pigment(elem.get("pigment"))
    return pos, val


def classify(num, cfg):
    if num >= cfg["critical"]:
        return "critical"
    if num >= cfg["warning"]:
        return "warning"
    return "stable"


def survey(transects, thresholds):
    buf = []
    failures = []
    history = {}
    for idx, elem in enumerate(transects):
        try:
            pos, curr = parse_record(elem, idx)
        except ValueError as err:
            failures.append(str(err))
            continue
        prev = history.get(pos)
        history[pos] = curr
        if prev is None:
            continue
        num = prev - curr
        grade = classify(num, thresholds)
        if grade == "stable":
            continue
        buf.append({"site": pos, "drop": num, "level": grade, "record": idx})
    sites = set(entry["site"] for entry in buf)
    cnt = len(sites)
    return {"events": buf, "affected_regions": cnt, "skipped": failures}


def format_report(res):
    events = res["events"]
    ctx = {}
    for elem in events:
        ctx[elem["level"]] = ctx.get(elem["level"], 0) + 1
    lines = ["affected regions: %d" % res["affected_regions"]]
    for level in sorted(ctx):
        lines.append("  %s events: %d" % (level, ctx[level]))
    for elem in events:
        lines.append(
            "  %s (record %d): drop of %d -> %s"
            % (elem["site"], elem["record"], elem["drop"], elem["level"])
        )
    for msg in res["skipped"]:
        lines.append("  skipped: %s" % msg)
    return "\n".join(lines)


