DEFAULT_CFG = {"cells_per_line": 32, "lines_per_page": 4}

ALPHA_CELLS = "⠁⠃⠉⠙⠑⠋⠛⠓⠊⠚⠅⠇⠍⠝⠕⠏⠟⠗⠎⠞⠥⠧⠺⠭⠽⠵"


def merge_cfg(param):
    cfg = dict(DEFAULT_CFG)
    if param is None:
        param = {}
    for key in param:
        if key not in cfg:
            err = "unknown page option: {}".format(key)
            raise KeyError(err)
        num = param[key]
        if not isinstance(num, int) or num < 1:
            err = "{} must be a positive integer".format(key)
            raise ValueError(err)
        cfg[key] = num
    return cfg


def build_rules():
    import string
    rules = dict(zip(string.ascii_lowercase, ALPHA_CELLS))
    rules[" "] = "⠀"
    rules[","] = "⠂"
    rules["."] = "⠲"
    return rules


class Composer:
    def __init__(self, cfg):
        self.width = cfg["cells_per_line"]
        self.per_page = cfg["lines_per_page"]
        self.pages = [[]]
        self.buf = []
        self.cnt = 0
        self.pos = None

    def add(self, val):
        if len(self.buf) >= self.width:
            self.wrap()
        self.buf.append(val)

    def mark_break(self):
        self.pos = len(self.buf) - 1

    def wrap(self):
        if self.pos is None:
            self.flush()
            return
        tail = self.buf[self.pos + 1:]
        del self.buf[self.pos:]
        self.flush()
        self.buf.extend(tail)

    def flush(self):
        if not self.buf:
            self.pos = None
            return
        curr = self.pages[-1]
        if len(curr) >= self.per_page:
            curr = []
            self.pages.append(curr)
        curr.append("".join(self.buf))
        self.cnt += 1
        self.buf = []
        self.pos = None


def translate(text, rules, cfg=None):
    ctx = Composer(merge_cfg(cfg))
    errors = []
    prev = ""
    for idx, ch in enumerate(text):
        tmp = prev
        prev = ch
        if ch == "\n":
            ctx.flush()
            continue
        if ch == " " and tmp == " ":
            continue
        val = rules.get(ch)
        if val is None:
            msg = "index {}: no tactile cell for {!r}".format(idx, ch)
            errors.append(msg)
            continue
        ctx.add(val)
        if ch == " ":
            ctx.mark_break()
    ctx.flush()
    res = {"pages": ctx.pages, "line_count": ctx.cnt, "errors": errors}
    return res


def format_report(res):
    out = []
    for num, page in enumerate(res["pages"], 1):
        out.append("--- page {} ---".format(num))
        for elem in page:
            out.append(elem)
    for msg in res["errors"]:
        out.append("! " + msg)
    out.append("total lines: {}".format(res["line_count"]))
    return "\n".join(out)


def main():
    rules = build_rules()
    print(format_report(translate("hello", rules)))
    cfg = {"cells_per_line": 16, "lines_per_page": 2}
    print(format_report(translate("the quick brown fox jumps over the lazy dog!", rules, cfg)))


if __name__ == "__main__":
    main()

