        self.pages = [[]]
        self.buffer = []
        self.count = 0
        self.position = None

    def add(self, value):
        if len(self.buffer) >= self.width:
            self.wrap()
        self.buffer.append(value)

    def mark_break(self):
        self.position = len(self.buffer) - 1

    def wrap(self):
        if self.position is None:
            self.flush()
            return
        tail = self.buffer[self.position + 1:]
        del self.buffer[self.position:]
        self.flush()
        self.buffer.extend(tail)

    def flush(self):
        if not self.buffer:
            self.position = None
            return
        current = self.pages[-1]
        if len(current) >= self.per_page:
            current = []
            self.pages.append(current)
        current.append("".join(self.buffer))
        self.count += 1
        self.buffer = []
        self.position = None


def translate(text, rules, configuration=None):
    context = Composer(merge_configuration(configuration))
    errors = []
    previous = ""
    for index, ch in enumerate(text):
        temporary = previous
        previous = ch
        if ch == "\n":
            context.flush()
            continue
        if ch == " " and temporary == " ":
            continue
        value = rules.get(ch)
        if value is None:
            message = "index {}: no tactile cell for {!r}".format(index, ch)
            errors.append(message)
            continue
        context.add(value)
        if ch == " ":
            context.mark_break()
    context.flush()
    result = {"pages": context.pages, "line_count": context.count, "errors": errors}
    return result


def format_report(result):
    out = []
    for number, page in enumerate(result["pages"], 1):
        out.append("--- page {} ---".format(number))
        for element in page:
            out.append(element)
    for message in result["errors"]:
        out.append("! " + message)
    out.append("total lines: {}".format(result["line_count"]))
    return "\n".join(out)


def main():
    rules = build_rules()
    print(format_report(translate("hello", rules)))
    configuration = {"cells_per_line": 16, "lines_per_page": 2}
    print(format_report(translate("the quick brown fox jumps over the lazy dog!", rules, configuration)))


if __name__ == "__main__":
    main()

