    if "sensitivity" not in cfg:
        raise KeyError("baseline is missing the 'sensitivity' limit")
    val = float(cfg["sensitivity"])
    if val <= 0:
        raise ValueError("sensitivity limit must be greater than zero")
    cfg["sensitivity"] = val
    cfg["start_time"] = int(cfg.get("start_time", 0))
    cfg["interval"] = int(cfg.get("interval", 1))
    if cfg["interval"] <= 0:
        raise ValueError("sampling interval must be greater than zero")
    return cfg


def detect(waves, baseline):
    """Scan a chronological amplitude series and compile the alert history."""
    cfg = load_cfg(baseline)
    param = cfg["sensitivity"]
    res = []
    cnt = 0
    for idx in range(1, len(waves)):
        prev = float(waves[idx - 1])
        curr = float(waves[idx])
        tmp = curr - prev
        if abs(tmp) >= param:
            cnt += 1
            pos = cfg["start_time"] + idx * cfg["interval"]
            res.append({
                "event": cnt,
                "time": pos,
                "magnitude": round(abs(tmp), 3),
                "amplitude": curr,
                "rising": tmp > 0,
            })
    return res


