def parse_tracks(tracks):
    cfg = {}
    for name, param in tracks.items():
        val = param.get("capacity") if isinstance(param, dict) else param
        num = int(val)
        if num <= 0:
            err = "siding %s has a non-positive capacity" % name
            raise ValueError(err)
        cfg[name] = num
    if not cfg:
        raise ValueError("no sidings available in the yard")
    return cfg


def normalize_car(car, idx):
    dest = car.get("dest") or car.get("destination")
    if not dest:
        err = "incoming car at position %d carries no destination" % idx
        raise ValueError(err)
    return {"id": car.get("id", "CAR-%02d" % idx), "dest": dest}


def choose_siding(layout, cfg, dest):
    best = None
    for name, elem in layout.items():
        if elem and elem[0]["dest"] == dest and len(elem) < cfg[name]:
            if best is None or len(elem) > len(layout[best]):
                best = name
    if best is not None:
        return best
    free = [name for name in cfg if not layout[name]]
    if free:
        return max(free, key=lambda name: cfg[name])
    return None


def report(ctx, res):
    cnt = ctx["sorted"]
    print("sorted %d car(s) onto %d siding(s)" % (cnt, len(res)))
    for msg in ctx["warnings"]:
        print("WARNING: " + msg)


def shunt(cars, tracks):
    cfg = parse_tracks(tracks)
    layout = {name: [] for name in cfg}
    buf = []
    ctx = {"sorted": 0, "warnings": []}
    for idx, car in enumerate(cars):
        curr = normalize_car(car, idx)
        pos = choose_siding(layout, cfg, curr["dest"])
        if pos is None:
            tmp = [n for n, e in layout.items() if e and e[0]["dest"] == curr["dest"]]
            if tmp:
                ctx["warnings"].append("siding %s is at capacity, %s held back"
                                       % (tmp[0], curr["id"]))
            buf.append(curr)
            continue
        layout[pos].append(curr)
        ctx["sorted"] += 1
    while buf:
        prev = len(buf)
        held = []
        for elem in buf:
            pos = choose_siding(layout, cfg, elem["dest"])
            if pos is None:
                held.append(elem)
            else:
                layout[pos].append(elem)
                ctx["sorted"] += 1
        buf = held
        if len(buf) == prev:
            for elem in buf:
                msg = "derailment risk: %s bound for %s cannot be placed" % (
                    elem["id"], elem["dest"])
                ctx["warnings"].append(msg)
            break
    res = {name: [c["id"] for c in elem] for name, elem in layout.items() if elem}
    report(ctx, res)
    return res


