DEFAULT_CFG = {
    "volume": 12.0,
    "absorption": 0.85,
    "flood_limit": 18.0,
}


def parse_location(elem):
    if isinstance(elem, dict):
        center = (float(elem["x"]), float(elem["y"]))
        num = float(elem["radius"])
    else:
        center = (float(elem[0]), float(elem[1]))
        num = float(elem[2])
    if num <= 0:
        raise ValueError("spray radius must be positive, got %r" % num)
    return center, num


def wetted_cells(center, radius, field):
    width, height = field
    cx, cy = center
    res = []
    for y in range(max(0, int(cy - radius)), min(height, int(cy + radius) + 1)):
        for x in range(max(0, int(cx - radius)), min(width, int(cx + radius) + 1)):
            tmp = ((x - cx) ** 2 + (y - cy) ** 2) ** 0.5
            if tmp <= radius:
                res.append(((x, y), tmp))
    return res


def format_map(grid, alerts):
    lines = []
    for idx, row in enumerate(grid):
        lines.append("row %2d | %s" % (idx, " ".join("%5.1f" % v for v in row)))
    for msg in alerts:
        lines.append(msg)
    return "\n".join(lines)


def irrigate(sprinklers, field):
    cfg = dict(DEFAULT_CFG)
    width, height = field
    if width <= 0 or height <= 0:
        raise ValueError("field dimensions must be positive")
    buf = [[0.0] * width for _ in range(height)]
    prev = set()
    overlaps = set()
    for elem in sprinklers:
        param = parse_location(elem)
        curr = wetted_cells(param[0], param[1], field)
        for pos, dist in curr:
            val = cfg["volume"] * (1.0 - dist / (param[1] + 1.0))
            buf[pos[1]][pos[0]] += val
        cells = set(pos for pos, _ in curr)
        overlaps |= cells & prev
        prev |= cells
    alerts = []
    for y in range(height):
        for x in range(width):
            buf[y][x] = round(buf[y][x] * cfg["absorption"], 2)
            if buf[y][x] > cfg["flood_limit"]:
                alerts.append("FLOOD ALERT at (%d, %d): %.2f mm" % (x, y, buf[y][x]))
    res = {
        "grid": buf,
        "alerts": alerts,
        "overlap_cells": sorted(overlaps),
        "wetted_cells": len(prev),
    }
    return res


def main():
    field = (12, 8)
    plan = [(3, 4, 4.0), {"x": 8, "y": 4, "radius": 4.0}]
    try:
        ctx = irrigate(plan, field)
    except ValueError as err:
        print("irrigation aborted:", err)
        return
    print(format_map(ctx["grid"], ctx["alerts"]))
    cnt = len(ctx["overlap_cells"])
    print("wetted cells: %d, overlapping cells: %d" % (ctx["wetted_cells"], cnt))


if __name__ == "__main__":
    main()

