import math

DEFAULT_CFG = {"max_step_km": 4.0, "max_climb_m": 120.0, "base_elevation": 0.0}


def _read_cfg(terrain):
    cfg = dict(DEFAULT_CFG)
    cfg.update(terrain)
    for param in ("max_step_km", "max_climb_m"):
        num = float(cfg[param])
        if num <= 0:
            raise ValueError("threshold '%s' must be positive" % param)
        cfg[param] = num
    return cfg


def _norm(waypoints):
    out = []
    for idx, elem in enumerate(waypoints):
        for param in ("name", "lat", "lon"):
            if param not in elem:
                raise ValueError("waypoint %d is missing key '%s'" % (idx, param))
        pt = {"name": str(elem["name"])}
        for param in ("lat", "lon"):
            num = float(elem[param])
            pt[param] = num
        out.append(pt)
    return out


def _distance_km(prev, curr):
    lat1 = math.radians(prev["lat"])
    lat2 = math.radians(curr["lat"])
    dlon = math.radians(curr["lon"] - prev["lon"])
    tmp = math.sin((lat2 - lat1) / 2) ** 2
    tmp += math.cos(lat1) * math.cos(lat2) * math.sin(dlon / 2) ** 2
    return 2 * 6371.0088 * math.asin(math.sqrt(tmp))


def _elevation(elem, ctx):
    val = ctx.get("elevations", {}).get(elem["name"], ctx["base_elevation"])
    return float(val)


def validate(waypoints, terrain):
    cfg = _read_cfg(terrain)
    route = _norm(waypoints)
    warns = terrain.setdefault("warnings", [])
    res = []
    if not route:
        return res
    buf = [route[0]]
    for idx in range(1, len(route)):
        prev = route[idx - 1]
        curr = route[idx]
        gap = _distance_km(prev, curr)
        climb = abs(_elevation(curr, cfg) - _elevation(prev, cfg))
        if gap <= cfg["max_step_km"] and climb <= cfg["max_climb_m"]:
            buf.append(curr)
            continue
        msg = "step %d (%s -> %s) impassable: %.2f km, %.0f m climb" % (
            idx, prev["name"], curr["name"], gap, climb)
        warns.append(msg)
        if len(buf) > 1:
            res.append(buf)
        buf = [curr]
    if len(buf) > 1:
        res.append(buf)
    return res


def report(res, warns):
    lines = []
    for pos, seg in enumerate(res, 1):
        cnt = len(seg)
        names = " -> ".join(elem["name"] for elem in seg)
        lines.append("verified path %d (%d waypoints): %s" % (pos, cnt, names))
    for msg in warns:
        lines.append("warning: " + msg)
    return "\n".join(lines) if lines else "no verified paths"


def main():
    route = [
        {"name": "trailhead", "lat": 47.6100, "lon": -122.3300},
        {"name": "old oak", "lat": 47.6150, "lon": -122.3300},
        {"name": "creek bend", "lat": 47.6200, "lon": -122.3300},
        {"name": "far ridge", "lat": 47.9000, "lon": -122.3000},
    ]
    terrain = {"max_step_km": 2.0, "elevations": {"far ridge": 900.0}}
    try:
        res = validate(route, terrain)
    except ValueError as err:
        print("invalid input: %s" % err)
        return
    print(report(res, terrain["warnings"]))


if __name__ == "__main__":
    main()

