import math

DEFAULTS = {'gap': 0.0, 'radius': 0.0, 'n': 1.0}


def normalize_lenses(lenses):
    """Validate the glass description and return clean float configs."""
    res = []
    for idx, elem in enumerate(lenses):
        for param in DEFAULTS:
            if not isinstance(elem.get(param, DEFAULTS[param]), (int, float)):
                raise TypeError(f"lens {idx}: '{param}' must be numeric")
        cfg = {key: float(elem.get(key, DEFAULTS[key])) for key in DEFAULTS}
        if cfg['n'] <= 0.0:
            err = f"lens {idx}: optical density must be positive, got {cfg['n']}"
            raise ValueError(err)
        res.append(cfg)
    return res


def refract(pos, angle, cfg, ctx):
    """Snell's law at one surface; returns (new_angle, event_note)."""
    radius = cfg['radius']
    if radius == 0.0:
        tilt = 0.0
    else:
        val = pos / radius
        if abs(val) > 1.0:
            return None, f"beam misses curved surface (y={pos:.3f}, R={radius:.3f})"
        tilt = math.asin(val)
    num = ctx['n'] / cfg['n']
    tmp = num * math.sin(angle - tilt)
    if abs(tmp) > 1.0:
        return None, f"total internal reflection (sin theta = {tmp:.3f})"
    return math.asin(tmp) + tilt, None


def trace(rays, lenses):
    cfg_list = normalize_lenses(lenses)
    paths, notes, cnt = [], [], 0
    for idx, ray in enumerate(rays):
        pos = float(ray.get('y', 0.0))
        curr = float(ray.get('angle', 0.0))
        ctx = {'n': 1.0, 'z': 0.0}
        buf = [{'z': 0.0, 'y': pos, 'angle': curr}]
        blocked = None
        for elem in cfg_list:
            prev = pos
            pos = prev + elem['gap'] * math.tan(curr)
            ctx['z'] += elem['gap']
            tmp, msg = refract(pos, curr, elem, ctx)
            buf.append({'z': ctx['z'], 'y': pos, 'angle': curr if msg else tmp})
            if msg is not None:
                blocked = f"beam {idx}: {msg}"
                break
            curr = tmp
            ctx['n'] = elem['n']
        if blocked is None:
            cnt += 1
            paths.append(buf)
        else:
            notes.append(blocked)
    return {'transmitted': cnt, 'paths': paths, 'events': notes}


