from collections import Counter

FAMILIES = ("top", "heart", "base")

FAMILY_TABLE = {
    "bergamot": "top",
    "lemon": "top",
    "mint": "top",
    "rose": "heart",
    "jasmine": "heart",
    "lavender": "heart",
    "vanilla": "base",
    "sandalwood": "base",
    "musk": "base",
}

VOL_TABLE = {"top": 0.9, "heart": 0.5, "base": 0.2}

DEFAULT_CFG = {"top": 0.3, "heart": 0.4, "base": 0.3, "threshold": 9.0, "max_gap": 0.55}


def resolve_cfg(profile):
    cfg = dict(DEFAULT_CFG)
    cfg.update(profile or {})
    tmp = sum(float(cfg[family]) for family in FAMILIES)
    if tmp <= 0.0:
        raise ValueError("scent profile must request a positive share of some family")
    for family in FAMILIES:
        cfg[family] = float(cfg[family]) / tmp
    return cfg


def as_note(elem):
    if isinstance(elem, str):
        return {"name": elem}
    return dict(elem)


def classify(elem):
    name = str(elem.get("name", "")).strip().lower()
    return FAMILY_TABLE.get(name, elem.get("family", "heart"))


def evaporation(elem, family):
    val = float(elem.get("volatility", VOL_TABLE[family]))
    return max(0.0, min(1.0, val))


def is_smooth(prev, curr, max_gap):
    return prev is None or abs(prev - curr) <= max_gap


def blend(notes, profile):
    cfg = resolve_cfg(profile)
    buf = []
    mixture = []
    prev = None
    intensity = 0.0
    for idx, item in enumerate(notes):
        elem = as_note(item)
        if not elem.get("name"):
            buf.append("ingredient at position %d has no name" % idx)
            continue
        family = classify(elem)
        if family not in FAMILIES:
            buf.append("%s declares unknown family %r" % (elem["name"], family))
            continue
        curr = evaporation(elem, family)
        if not is_smooth(prev, curr, cfg["max_gap"]):
            msg = "dropping %s: evaporation jump %.2f -> %.2f" % (elem["name"], prev, curr)
            buf.append(msg)
            continue
        prev = curr
        mixture.append(family)
        intensity += float(elem.get("intensity", 1.0))
    if intensity > cfg["threshold"]:
        err = "masking risk: combined intensity %.2f exceeds %.2f" % (intensity, cfg["threshold"])
        buf.append(err)
    cnt = Counter(mixture)
    res = [round(cfg[family] / cnt[family], 4) for family in mixture]
    for msg in buf:
        print("[blend] " + msg)
    return res


def main():
    notes = [{"name": "rose", "intensity": 4.0}, {"name": "vanilla", "intensity": 3.0}]
    profile = {"top": 0.0, "heart": 0.6, "base": 0.4, "threshold": 8.0}
    res = blend(notes, profile)
    for pos, val in enumerate(res, start=1):
        print("%d. %-10s %6.2f%%" % (pos, notes[pos - 1]["name"], val * 100.0))


if __name__ == "__main__":
    main()

