    ("padlock", "locked"): "Lock the padlock '{name}' ({room})",
    ("padlock", "unlocked"): "Unlock the padlock '{name}' ({room})",
    ("lamp", "on"): "Switch on the lamp '{name}' ({room})",
    ("lamp", "off"): "Switch off the lamp '{name}' ({room})",
    ("drawer", "closed"): "Close the drawer '{name}' ({room})",
    ("drawer", "open"): "Open the drawer '{name}' ({room})",
    ("safe", "locked"): "Close and lock the safe '{name}' ({room})",
}


def instruction(elem, param, ctx):
    tmp = TEMPLATES.get((norm(elem.get("kind")), param))
    if tmp is None:
        tmp = "Set the " + norm(elem.get("kind")) + " '{name}' ({room}) to " + param
    return tmp.format(name=elem.get("name"), room=ctx["room"])


def audit(elem, param, ctx):
    buf = []
    pos = norm(elem.get("zone"))
    if pos != norm(param.get("zone")):
        buf.append("Move '{}' from {} back to {}".format(
            elem.get("name"), elem.get("zone", "nowhere"), param.get("zone")))
    curr = norm(elem.get("state"))
    if curr != norm(param.get("state")):
        buf.append(instruction(elem, norm(param.get("state")), ctx))
    return buf


def reset(props, room):
    cfg = room.get("props", {})
    ctx = {"room": room.get("name", "unnamed room")}
    res = []
    cnt = 0
    prev = None
    for elem in sorted(props, key=lambda p: (norm(p.get("zone")), norm(p.get("name")))):
        param = cfg.get(elem.get("name"))
        if param is None:
            err = "Unregistered prop '{}' in {} - remove it from play".format(
                elem.get("name", "?"), elem.get("zone", "?"))
            buf = [err]
