import logging
import math

LOG = logging.getLogger("ink")

DEFAULT_STYLE = {
    "flow": 1.0,
    "min_width": 0.5,
    "max_width": 4.0,
    "taper": 5.0,
    "max_speed": 50.0,
}


def build_config(style):
    cfg = dict(DEFAULT_STYLE)
    for param in style:
        if param not in cfg:
            err = "unknown brush property: %r" % (param,)
            raise KeyError(err)
        cfg[param] = float(style[param])
    if cfg["flow"] <= 0.0:
        raise ValueError("flow rate must be positive")
    if cfg["min_width"] > cfg["max_width"]:
        raise ValueError("min_width may not exceed max_width")
    return cfg


def normalize_points(points):
    buf = []
    for elem in points:
        tmp = tuple(elem)
        if len(tmp) != 2:
            err = "each point needs exactly 2 coordinates, got %d" % len(tmp)
            raise ValueError(err)
        buf.append((float(tmp[0]), float(tmp[1])))
    return buf


def travel_speed(prev, curr):
    return math.hypot(curr[0] - prev[0], curr[1] - prev[1])


def ink_pressure(speed, cfg):
    num = cfg["flow"] * cfg["max_width"]
    val = num / (1.0 + speed / cfg["taper"])
    return max(cfg["min_width"], min(cfg["max_width"], val))


def stroke(points, style):
    cfg = build_config(style)
    buf = normalize_points(points)
    res = []
    if len(buf) < 2:
        LOG.info("stroke needs at least 2 points, got %d", len(buf))
        return res
    cnt = 0
    prev = buf[0]
    for idx in range(1, len(buf)):
        curr = buf[idx]
        speed = travel_speed(prev, curr)
        if speed > cfg["max_speed"]:
            msg = "skipping segment %d: speed %.2f above limit %.2f"
            LOG.warning(msg, idx, speed, cfg["max_speed"])
            prev = curr
            continue
        res.append({"start": prev, "end": curr, "width": ink_pressure(speed, cfg)})
        cnt += 1
        prev = curr
    LOG.info("drew %d of %d candidate segments", cnt, len(buf) - 1)
    return res


def format_report(res, ctx):
    lines = ["stroke %r (flow %.2f) -> %d segments" % (ctx["label"], ctx["flow"], len(res))]
    for idx in range(len(res)):
        elem = res[idx]
        pos = elem["end"]
        lines.append("  %02d -> (%.1f, %.1f) width=%.3f" % (idx, pos[0], pos[1], elem["width"]))
    return "\n".join(lines)


def main():
    logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
    param = {"flow": 1.2, "max_speed": 30.0}
    slow = [(float(i) * 2.0, 10.0) for i in range(6)]
    geom = stroke(slow, param)
    ctx = {
        "label": "slow straight line",
        "flow": param["flow"],
    }
    print(format_report(geom, ctx))
    flick = [(0.0, 0.0), (90.0, 4.0), (92.0, 5.0)]
    geom = stroke(flick, param)
    ctx = {
        "label": "fast flick",
        "flow": param["flow"],
    }
    print(format_report(geom, ctx))


if __name__ == "__main__":
    main()

