        buffer.append((float(temporary[0]), float(temporary[1])))
    return buffer


def travel_speed(previous, current):
    return math.hypot(current[0] - previous[0], current[1] - previous[1])


def ink_pressure(speed, configuration):
    number = configuration["flow"] * configuration["max_width"]
    value = number / (1.0 + speed / configuration["taper"])
    return max(configuration["min_width"], min(configuration["max_width"], value))


def stroke(points, style):
    configuration = build_config(style)
    buffer = normalize_points(points)
    result = []
    if len(buffer) < 2:
        LOG.info("stroke needs at least 2 points, got %d", len(buffer))
        return result
    count = 0
    previous = buffer[0]
    for index in range(1, len(buffer)):
        current = buffer[index]
        speed = travel_speed(previous, current)
        if speed > configuration["max_speed"]:
            message = "skipping segment %d: speed %.2f above limit %.2f"
            LOG.warning(message, index, speed, configuration["max_speed"])
            previous = current
            continue
        result.append({"start": previous, "end": current, "width": ink_pressure(speed, configuration)})
        count += 1
        previous = current
    LOG.info("drew %d of %d candidate segments", count, len(buffer) - 1)
    return result


def format_report(result, context):
    lines = ["stroke %r (flow %.2f) -> %d segments" % (context["label"], context["flow"], len(result))]
    for index in range(len(result)):
        element = result[index]
        position = element["end"]
        lines.append("  %02d -> (%.1f, %.1f) width=%.3f" % (index, position[0], position[1], element["width"]))
    return "\n".join(lines)


def main():
    logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
    parameter = {"flow": 1.2, "max_speed": 30.0}
    slow = [(float(i) * 2.0, 10.0) for i in range(6)]
    geom = stroke(slow, parameter)
    context = {
        "label": "slow straight line",
        "flow": parameter["flow"],
    }
    print(format_report(geom, context))
    flick = [(0.0, 0.0), (90.0, 4.0), (92.0, 5.0)]
    geom = stroke(flick, parameter)
    context = {
        "label": "fast flick",
        "flow": parameter["flow"],
    }
    print(format_report(geom, context))


if __name__ == "__main__":
    main()

