import math

DEFAULT_CFG = {"min_angle": 120.0, "precision": 3, "buffer_size": 3}


def validate(coordinates):
    """Return the coordinates as a list of float pairs, rejecting bad input."""
    res = []
    for idx, elem in enumerate(coordinates):
        if len(elem) != 2:
            err = "coordinate {} must hold exactly two values".format(idx)
            raise ValueError(err)
        x, y = elem
        res.append((float(x), float(y)))
    return res


def _vector(prev, curr):
    return (curr[0] - prev[0], curr[1] - prev[1])


def interior_angle(v_prev, v_curr):
    """Angle in degrees swept at the joint between two movement vectors."""
    num = -(v_prev[0] * v_curr[0] + v_prev[1] * v_curr[1])
    den = math.hypot(*v_prev) * math.hypot(*v_curr)
    if den == 0.0:
        return 180.0
    val = max(-1.0, min(1.0, num / den))
    return math.degrees(math.acos(val))


def midpoint(prev, curr, precision):
    x = round((prev[0] + curr[0]) / 2.0, precision)
    y = round((prev[1] + curr[1]) / 2.0, precision)
    return (x, y)


def fmt_point(elem):
    return "({:g}, {:g})".format(elem[0], elem[1])


def optimize(coordinates, ctx=None):
    """Smooth a cutting path, inserting intermediate points at sharp joints."""
    cfg = dict(DEFAULT_CFG)
    if ctx:
        cfg.update(ctx)
    pts = validate(coordinates)
    log = cfg.get("log")
    if log is None:
        log = []
    res = pts[:1]
    buf = []
    cnt = 0
    for pos in range(1, len(pts)):
        prev = pts[pos - 1]
        curr = pts[pos]
        buf.append(_vector(prev, curr))
        if len(buf) > cfg["buffer_size"]:
            buf.pop(0)
        if len(buf) >= 2:
            angle = interior_angle(buf[-2], buf[-1])
            if angle < cfg["min_angle"]:
                tmp = midpoint(prev, curr, cfg["precision"])
                res.append(tmp)
                cnt += 1
                msg = "reroute #{}: {:.1f} deg joint at {} routed via {}".format(
                    cnt, angle, fmt_point(prev), fmt_point(tmp))
                log.append(msg)
        res.append(curr)
    return res, cnt


def main():
    ctx = {"min_angle": 120.0, "log": []}
    path, cnt = optimize([(0, 0), (10, 0), (10, 10)], ctx)
    print("path:", " -> ".join(fmt_point(elem) for elem in path))
    print("inserted:", cnt)
    for msg in ctx["log"]:
        print(msg)
    try:
        optimize([(0, 0), (5, 5, 5)], ctx)
    except ValueError as err:
        print("rejected:", err)


if __name__ == "__main__":
    main()

