DEFAULT_CFG = {
    "max_jump": 30.0,
    "min_angle": -180.0,
    "max_angle": 180.0,
    "helix_span": 20.0,
    "sheet_span": 90.0,
}


def clamp(val, low, high):
    if val < low:
        return low
    if val > high:
        return high
    return val


def classify(span, helix_span, sheet_span):
    if span <= helix_span:
        return "helix"
    if span >= sheet_span:
        return "sheet"
    return "coil"


def validate(angles, ctx=None):
    cfg = dict(DEFAULT_CFG)
    if ctx is not None:
        for key in DEFAULT_CFG:
            if key in ctx:
                cfg[key] = float(ctx[key])
    else:
        ctx = {}
    param = cfg["max_jump"]
    low = cfg["min_angle"]
    high = cfg["max_angle"]
    err = ctx.setdefault("errors", [])
    motifs = ctx.setdefault("motifs", [])
    res = []
    buf = []
    cnt = 0
    prev = None
    for idx, elem in enumerate(angles):
        curr = clamp(float(elem), low, high)
        if prev is not None:
            diff = curr - prev
            if abs(diff) > param:
                cnt += 1
                msg = "angle[%d]=%g jumps %+g from %g" % (idx, curr, diff, prev)
                err.append(msg)
                step = param if diff > 0 else -param
                tmp = clamp(prev + step, low, high)
                curr = tmp
        res.append(curr)
        buf.append(curr)
        if len(buf) == 3:
            span = max(buf) - min(buf)
            label = classify(span, cfg["helix_span"], cfg["sheet_span"])
            motifs.append((idx - 2, label))
            buf.pop(0)
        prev = curr
    return res, cnt


def format_report(outcome, ctx):
    res = outcome[0]
    cnt = outcome[1]
    num = len(res)
    lines = ["residues: %d" % num]
    lines.append("corrected: " + ", ".join("%g" % val for val in res))
    lines.append("violations: %d" % cnt)
    for msg in ctx.get("errors", []):
        lines.append("  ! " + msg)
    for pos, label in ctx.get("motifs", []):
        lines.append("  window %d-%d: %s" % (pos, pos + 2, label))
    return lines


def main():
    ctx = {"max_jump": 30}
    outcome = validate([45, 50, 180, 55], ctx)
    for line in format_report(outcome, ctx):
        print(line)


if __name__ == "__main__":
    main()

