from collections import deque

DEFAULT_CFG = {
    "coords": {num: (num, 0) for num in range(1, 10)},
    "max_distance": 1,
    "buffer_size": 3,
}


def room_distance(cfg, src, dst):
    coords = cfg["coords"]
    x0, y0 = coords[src]
    x1, y1 = coords[dst]
    return abs(x0 - x1) + abs(y0 - y1)


def parse_events(text):
    res = []
    for pos, token in enumerate(text.split()):
        try:
            num = int(token)
        except ValueError:
            raise ValueError("token %d is not a room number: %r" % (pos, token))
        res.append(num)
    return res


def track(events, cfg=None, log=None):
    cfg = dict(DEFAULT_CFG, **(cfg or {}))
    param = cfg["max_distance"]
    buf = deque(maxlen=cfg["buffer_size"])
    path = []
    cnt = 0
    prev = None
    for idx, elem in enumerate(events):
        curr = elem
        if curr not in cfg["coords"]:
            raise ValueError("trigger %d names unknown room %r" % (idx, curr))
        tmp = curr
        if prev is not None and room_distance(cfg, prev, curr) > param:
            cnt += 1
            tmp = buf[-1]
            msg = "trigger %d: jump %s -> %s impossible, keeping %s" % (
                idx, prev, curr, tmp)
            if log is not None:
                log.append(msg)
        buf.append(tmp)
        path.append(tmp)
        prev = tmp
    return path, cnt


def format_report(path, cnt, messages):
    ctx = {"steps": len(path), "anomalies": cnt}
    lines = ["path: " + " ".join(str(room) for room in path)]
    for key in sorted(ctx):
        val = ctx[key]
        lines.append("%s = %d" % (key, val))
    lines.extend(messages)
    return "\n".join(lines)


def main():
    cfg = {"max_distance": 1}
    log = []
    try:
        events = parse_events("1 2 9 2")
        path, cnt = track(events, cfg, log)
    except ValueError as err:
        print("input error: %s" % err)
        return 1
    res = format_report(path, cnt, log)
    print(res)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

