import sys
from statistics import mean

DEFAULT_CFG = {"sensitivity": 200.0, "window": 10, "logger": None}


def build_cfg(ctx):
    """Merge a caller-supplied context mapping over the built-in defaults."""
    cfg = dict(DEFAULT_CFG)
    for param, setting in (ctx or {}).items():
        if param not in DEFAULT_CFG:
            raise KeyError("unknown context parameter: %s" % param)
        cfg[param] = setting
    if cfg["window"] < 1:
        raise ValueError("window must cover at least one measurement")
    if cfg["sensitivity"] <= 0:
        raise ValueError("sensitivity must be positive")
    return cfg


def to_num(elem, depth):
    """Coerce one raw measurement into a float, naming its depth on failure."""
    try:
        return float(elem)
    except (TypeError, ValueError) as err:
        raise ValueError("bad measurement at depth %d (%r): %s" % (depth, elem, err))


def analyze(bubbles, ctx=None):
    """Scan an ice core top-to-bottom and isolate concentration excursions."""
    cfg = build_cfg(ctx)
    log = cfg["logger"] or (lambda text: print(text, file=sys.stderr))
    buf = []
    res = []
    tmp = []
    cnt = 0
    prev = None
    for idx, elem in enumerate(bubbles):
        curr = to_num(elem, idx)
        if buf:
            base = mean(buf)
            if abs(curr - base) > cfg["sensitivity"]:
                cnt += 1
                res.append(curr)
                tmp.append(idx)
                msg = "event #%d at depth %d: %.1f ppm vs baseline %.1f, previous %.1f" % (
                    cnt, idx, curr, base, prev)
                log(msg)
        buf.append(curr)
        if len(buf) > cfg["window"]:
            buf.pop(0)
        prev = curr
    if tmp:
        log("flagged depths: %s" % ", ".join(str(pos) for pos in tmp))
    return res, cnt


def format_report(res, total):
    """Render the event values and their count as a human-readable report."""
    if not total:
        return "no historical climate events detected"
    lines = ["detected %d historical climate event(s):" % total]
    for num in res:
        lines.append("  %.1f ppm" % num)
    return "\n".join(lines)


def main(argv):
    ctx = {}
    if len(argv) > 1:
        ctx["sensitivity"] = float(argv[1])
    if len(argv) > 2:
        ctx["window"] = int(argv[2])
    readings = sys.stdin.read().replace(",", " ").split()
    events, total = analyze(readings, ctx)
    print(format_report(events, total))
    return 0 if total else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))

