DEFAULTS = {"base": 1, "chars_per_unit": 6, "pause": 2, "max_units": 4, "lookahead": 3}
BREAK_MARKS = (".", "!", "?", ";", ":")


def build_cfg(param):
    """Merge presenter preferences over the built-in pacing defaults."""
    cfg = dict(DEFAULTS)
    if param is None:
        return cfg
    for key, val in param.items():
        if key not in DEFAULTS:
            err = "unknown presenter preference: %r" % (key,)
            raise KeyError(err)
        if not isinstance(val, int) or val < 0:
            raise ValueError("preference %r must be a non-negative int" % (key,))
        cfg[key] = val
    return cfg


def is_break(word):
    """True when the word closes a sentence."""
    return word.rstrip().endswith(BREAK_MARKS)


def pace_message(pos, elem, num, limit):
    return "word %d (%r) needs %d units, screen scrolls after %d" % (pos, elem, num, limit)


def adjust(script, ctx=None):
    cfg = build_cfg(ctx)
    words = [str(w) for w in script]
    res = []
    cnt = 0
    prev = 0
    for idx, elem in enumerate(words):
        curr = len(elem.strip())
        buf = words[idx + 1:idx + 1 + cfg["lookahead"]]
        num = cfg["base"] + curr // cfg["chars_per_unit"]
        if prev and curr > 2 * prev:
            num += 1
        if is_break(elem):
            param = cfg["pause"]
            num += param
        pending = sum(len(w) for w in buf)
        if pending and pending < cfg["chars_per_unit"]:
            num += 1
        if num > cfg["max_units"]:
            cnt += 1
            msg = pace_message(idx + 1, elem, num, cfg["max_units"])
            print("pacing warning:", msg)
            num = cfg["max_units"]
        tmp = num
        res.append(tmp)
        prev = curr
    return res, cnt


def main():
    script = ["Welcome", "back", "everyone.", "Today"]
    ctx = {"pause": 2, "max_units": 4}
    res, cnt = adjust(script, ctx)
    for elem, val in zip(script, res):
        print("%-12s %d unit(s)" % (elem, val))
    print("total units:", sum(res), "| stutters:", cnt)

