DEFAULTS = {"base": 1, "chars_per_unit": 6, "pause": 2, "max_units": 4, "lookahead": 3}
BREAK_MARKS = (".", "!", "?", ";", ":")


def build_configuration(parameter):
    """Merge presenter preferences over the built-in pacing defaults."""
    configuration = dict(DEFAULTS)
    if parameter is None:
        return configuration
    for key, value in parameter.items():
        if key not in DEFAULTS:
            error = "unknown presenter preference: %r" % (key,)
            raise KeyError(error)
        if not isinstance(value, int) or value < 0:
            raise ValueError("preference %r must be a non-negative int" % (key,))
        configuration[key] = value
    return configuration


def is_break(word):
    """True when the word closes a sentence."""
    return word.rstrip().endswith(BREAK_MARKS)


def pace_message(position, element, number, limit):
    return "word %d (%r) needs %d units, screen scrolls after %d" % (position, element, number, limit)


def adjust(script, context=None):
    configuration = build_configuration(context)
    words = [str(w) for w in script]
    result = []
    count = 0
    previous = 0
    for index, element in enumerate(words):
        current = len(element.strip())
        buffer = words[index + 1:index + 1 + configuration["lookahead"]]
        number = configuration["base"] + current // configuration["chars_per_unit"]
        if previous and current > 2 * previous:
            number += 1
        if is_break(element):
            parameter = configuration["pause"]
            number += parameter
        pending = sum(len(w) for w in buffer)
        if pending and pending < configuration["chars_per_unit"]:
            number += 1
        if number > configuration["max_units"]:
            count += 1
            message = pace_message(index + 1, element, number, configuration["max_units"])
            print("pacing warning:", message)
            number = configuration["max_units"]
        temporary = number
        result.append(temporary)
        previous = current
    return result, count


def main():
    script = ["Welcome", "back", "everyone.", "Today"]
    context = {"pause": 2, "max_units": 4}
    result, count = adjust(script, context)
    for element, value in zip(script, result):
        print("%-12s %d unit(s)" % (element, value))
    print("total units:", sum(result), "| stutters:", count)

    long_script = ["Consider", "this", "extraordinarily", "verbose", "digression!", "Ok"]
    result, count = adjust(long_script, {"chars_per_unit": 4, "pause": 3})
    print("durations:", result, "| stutters:", count)


if __name__ == "__main__":
    main()

