DEFAULTS = {
    "critical_delta": 2000.0,
    "buffer_size": 4,
    "bands": {
        "L-band": (1000.0, 2000.0),
        "S-band": (2000.0, 4000.0),
        "C-band": (4000.0, 8000.0),
    },
}


def validate(ctx):
    num = ctx["critical_delta"]
    if num <= 0:
        return "critical_delta must be positive"
    size = ctx["buffer_size"]
    if size < 1:
        return "buffer_size must be at least 1"
    for name, bounds in ctx["bands"].items():
        lo, hi = bounds
        if lo > hi:
            return "band %s has inverted bounds" % name
    return ""


def prepare(cfg):
    ctx = dict(DEFAULTS)
    if cfg:
        ctx.update(cfg)
    err = validate(ctx)
    if err:
        raise ValueError(err)
    return ctx


def background(buf):
    return sum(buf) / float(len(buf))


def band_of(val, bands):
    for name, bounds in bands.items():
        if bounds[0] <= val <= bounds[1]:
            return name
    return "unclassified"


def filter(signals, cfg=None):
    ctx = prepare(cfg)
    param = ctx["critical_delta"]
    buf = []
    res = []
    cnt = 0
    prev = None
    for idx, elem in enumerate(signals):
        curr = float(elem)
        base = background(buf) if buf else curr
        if buf and curr - base > param:
            cnt += 1
            tmp = buf[-1]
            band = band_of(curr, ctx["bands"])
            head = "pos %d: amplitude %.1f" % (idx, curr)
            detail = "rose %.1f above background %.1f" % (curr - prev, base)
            msg = "%s %s in band %s; substituted %.1f" % (head, detail, band, tmp)
