            res.append(tmp)
        else:
            res.append(curr)
            buf.append(curr)
            if len(buf) > ctx["buffer_size"]:
                buf.pop(0)
        prev = curr
    return res, cnt


def format_report(res, cnt):
    body = ", ".join("%.1f" % amp for amp in res)
    return "filtered: [%s]\ninterference count: %d" % (body, cnt)


def main():
    cfg = {"critical_delta": 2000.0, "buffer_size": 3}
    observations = [1420, 1421, 5000, 1420]
    res, cnt = filter(observations, cfg)
    print(format_report(res, cnt))


