from collections import deque

VECTORS = {'north': (0, 1), 'east': (1, 0), 'south': (0, -1), 'west': (-1, 0)}
ORDER = ['north', 'east', 'south', 'west']
MOVES = {'forward': 1, 'backward': -1}
TURNS = {'left': -1, 'right': 1}


def advance(pos, heading, sign):
    dx, dy = VECTORS[heading]
    return (pos[0] + dx * sign, pos[1] + dy * sign)


def blocked(cfg, pos):
    if not (0 <= pos[0] < cfg['width'] and 0 <= pos[1] < cfg['height']):
        return 'boundary'
    if pos in cfg['beds']:
        return 'flowerbed'
    return None


def build_cfg(ctx):
    src = dict(ctx or {})
    cfg = {}
    for key, default in (('width', 5), ('height', 5), ('trail', 4)):
        val = src.get(key, default)
        if not isinstance(val, int) or val < 1:
            raise ValueError("%s must be a positive integer, got %r" % (key, val))
        cfg[key] = val
    cfg['beds'] = {tuple(elem) for elem in src.get('flowerbeds', ())}
    cfg['start'] = tuple(src.get('start', (0, 0)))
    cfg['heading'] = src.get('heading', 'north')
    if cfg['heading'] not in VECTORS:
        raise ValueError("unknown heading: %r" % (cfg['heading'],))
    if blocked(cfg, cfg['start']):
        raise ValueError("start cell %r is not mowable" % (cfg['start'],))
    return cfg


def evasion_msg(idx, param, tmp, buf):
    trail = ' -> '.join('(%d,%d)' % cell for cell in buf)
    return "step %d: %s at (%d,%d), backtracking over %s" % (idx, param, tmp[0], tmp[1], trail)


def report(cut, cnt):
    num = len(cut)
    return "mowed %d cell(s), avoided %d obstacle(s)" % (num, cnt)


def mow(commands, ctx=None):
    cfg = build_cfg(ctx)
    buf = deque([cfg['start']], maxlen=cfg['trail'])
    cut = {cfg['start']}
    heading = cfg['heading']
    res = []
    cnt = 0
    for idx, elem in enumerate(commands):
        if elem in TURNS:
            heading = ORDER[(ORDER.index(heading) + TURNS[elem]) % len(ORDER)]
            res.append(elem)
            continue
        if elem not in MOVES:
            raise ValueError("unknown movement: %r" % (elem,))
        prev = buf[-1]
        tmp = advance(prev, heading, MOVES[elem])
        param = blocked(cfg, tmp)
        if param:
            cnt += 1
            print(evasion_msg(idx, param, tmp, buf))
            curr = prev
            res.append('backward' if elem == 'forward' else 'forward')
        else:
            curr = tmp
            res.append(elem)
        buf.append(curr)
        cut.add(curr)
    print(report(cut, cnt))
    return res, cnt


def main():
    ctx = {'width': 4, 'height': 5, 'flowerbeds': [(0, 3)], 'start': (0, 0), 'trail': 3}
    commands = ['forward', 'forward', 'forward', 'left']
    try:
        res, cnt = mow(commands, ctx)
    except ValueError as err:
        print("bad garden context: %s" % err)
        return
    print("safe route: %s (obstacles: %d)" % (', '.join(res), cnt))


if __name__ == '__main__':
    main()

