DEFAULT_CFG = {
    "needles": {"W": 0, "R": 4, "B": 9, "G": 14, "Y": 19, "K": 24},
    "tension": 1.0,
    "row_width": 6,
}


def needle_pos(cfg, color):
    table = cfg["needles"]
    if color not in table:
        raise KeyError("no needle configuration for color %r" % color)
    return table[color]


def empty_needles(cfg, prev, curr):
    if prev is None:
        return 0
    param = cfg["tension"]
    if param <= 0:
        raise ValueError("tension must be positive")
    span = abs(needle_pos(cfg, curr) - needle_pos(cfg, prev)) - 1
    if span < 0:
        return 0
    return int(span / param)


def locking_stitches(cfg, prev, curr):
    tmp = []
    for elem in (prev, curr):
        tmp.append("lock %s at needle %d" % (elem, needle_pos(cfg, elem)))
    return tmp


def flush_row(buf, res, idx):
    if buf:
        res.append("row %d: %s" % (idx, " ".join(buf)))
        del buf[:]
        return idx + 1
    return idx


def knit(colors, ctx=None):
    cfg = dict(DEFAULT_CFG)
    if ctx:
        cfg.update(ctx)
    res = []
    buf = []
    cnt = 0
    prev = None
    row_idx = 1
    for pos, curr in enumerate(colors):
        num = empty_needles(cfg, prev, curr)
        if num > 3:
            cnt += 1
            row_idx = flush_row(buf, res, row_idx)
            msg = "manual tie required at stitch %d (%d empty needles)" % (pos, num)
            print(msg)
            res.append(msg)
            res.extend(locking_stitches(cfg, prev, curr))
        buf.append("knit %s" % curr)
        if len(buf) >= cfg["row_width"]:
            row_idx = flush_row(buf, res, row_idx)
        prev = curr
    flush_row(buf, res, row_idx)
    return res, cnt


def main():
    pattern = ["W", "R", "R", "K", "K", "B", "G", "G", "Y", "W"]
    try:
        res, cnt = knit(pattern, {"tension": 1.5})
    except (KeyError, ValueError) as err:
        print("knitting aborted: %s" % err)
        return
    for idx, val in enumerate(res, 1):
        print("%2d. %s" % (idx, val))
    print("dropped stitches: %d" % cnt)


if __name__ == "__main__":
    main()

