from datetime import datetime

PLAZA_CFG = {"A1": 0.0, "B2": 60.0, "C3": 62.5, "D4": 118.0}
MAX_SPEED_MPH = 80.0
TIME_FMT = "%Y-%m-%d %H:%M"


def parse_read(elem):
    try:
        pos = elem["plaza"]
        stamp = datetime.strptime(elem["time"], TIME_FMT)
        plate = elem["vehicle"]
    except (KeyError, TypeError, ValueError) as err:
        raise ValueError("unusable transponder read: %s" % err)
    return {"vehicle": plate, "plaza": pos, "time": stamp,
            "toll": float(elem.get("toll", 0.0)), "review": False, "reason": ""}


def required_minutes(prev, curr, cfg, param):
    try:
        miles = abs(cfg[curr] - cfg[prev])
    except KeyError as err:
        raise ValueError("plaza missing from configuration: %s" % err)
    return miles / param * 60.0


def ghost_message(num, idx, prev, curr, gap, need):
    return ("ghost vehicle %s at read %d: %s -> %s in %.1f min, %.1f min needed"
            % (num, idx, prev["plaza"], curr["plaza"], gap, need))


def audit(records, cfg=PLAZA_CFG, param=MAX_SPEED_MPH):
    res = []
    cnt = 0
    buf = {}
    for idx, elem in enumerate(records, 1):
        curr = parse_read(elem)
        num = curr["vehicle"]
        prev = buf.get(num)
        if prev is not None:
            gap = (curr["time"] - prev["time"]).total_seconds() / 60.0
            need = required_minutes(prev["plaza"], curr["plaza"], cfg, param)
            if gap < need:
                cnt += 1
                msg = ghost_message(num, idx, prev, curr, gap, need)
                tmp = dict(curr)
                tmp["review"] = True
                tmp["reason"] = msg
                tmp["toll"] = 0.0
                res.append(tmp)
                buf[num] = curr
                continue
        res.append(curr)
        buf[num] = curr
    return res, cnt


def format_report(res, cnt, ctx):
    lines = ["plazas=%d max_speed=%.0fmph anomalies=%d"
             % (ctx["plazas"], ctx["max_speed"], cnt)]
    for idx, elem in enumerate(res, 1):
        if elem["review"]:
            lines.append("%2d HOLD  %s" % (idx, elem["reason"]))
        else:
            lines.append("%2d BILL  %s %s $%.2f"
                         % (idx, elem["vehicle"], elem["plaza"], elem["toll"]))
    return "\n".join(lines)


def main():
    reads = [
        {"vehicle": "XYZ-100", "plaza": "A1", "time": "2026-09-18 08:00", "toll": 2.5},
        {"vehicle": "XYZ-100", "plaza": "B2", "time": "2026-09-18 08:05", "toll": 3.0},
        {"vehicle": "QRS-771", "plaza": "A1", "time": "2026-09-18 08:10", "toll": 2.5},
        {"vehicle": "QRS-771", "plaza": "D4", "time": "2026-09-18 10:15", "toll": 4.0},
