from datetime import datetime

PLAZA_CONFIGURATION = {"A1": 0.0, "B2": 60.0, "C3": 62.5, "D4": 118.0}
MAX_SPEED_MPH = 80.0
TIME_FMT = "%Y-%m-%d %H:%M"


def parse_read(element):
    try:
        position = element["plaza"]
        stamp = datetime.strptime(element["time"], TIME_FMT)
        plate = element["vehicle"]
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError("unusable transponder read: %s" % error)
    return {"vehicle": plate, "plaza": position, "time": stamp,
            "toll": float(element.get("toll", 0.0)), "review": False, "reason": ""}


def required_minutes(previous, current, configuration, parameter):
    try:
        miles = abs(configuration[current] - configuration[previous])
    except KeyError as error:
        raise ValueError("plaza missing from configuration: %s" % error)
    return miles / parameter * 60.0


def ghost_message(number, index, previous, current, gap, need):
    return ("ghost vehicle %s at read %d: %s -> %s in %.1f min, %.1f min needed"
            % (number, index, previous["plaza"], current["plaza"], gap, need))


def audit(records, configuration=PLAZA_CONFIGURATION, parameter=MAX_SPEED_MPH):
    result = []
    count = 0
    buffer = {}
    for index, element in enumerate(records, 1):
        current = parse_read(element)
        number = current["vehicle"]
        previous = buffer.get(number)
        if previous is not None:
            gap = (current["time"] - previous["time"]).total_seconds() / 60.0
            need = required_minutes(previous["plaza"], current["plaza"], configuration, parameter)
            if gap < need:
                count += 1
                message = ghost_message(number, index, previous, current, gap, need)
                temporary = dict(current)
                temporary["review"] = True
                temporary["reason"] = message
                temporary["toll"] = 0.0
                result.append(temporary)
                buffer[number] = current
                continue
        result.append(current)
        buffer[number] = current
    return result, count


def format_report(result, count, context):
    lines = ["plazas=%d max_speed=%.0fmph anomalies=%d"
             % (context["plazas"], context["max_speed"], count)]
    for index, element in enumerate(result, 1):
        if element["review"]:
            lines.append("%2d HOLD  %s" % (index, element["reason"]))
        else:
            lines.append("%2d BILL  %s %s $%.2f"
                         % (index, element["vehicle"], element["plaza"], element["toll"]))
    return "\n".join(lines)


def main():
    reads = [
        {"vehicle": "XYZ-100", "plaza": "A1", "time": "2026-09-18 08:00", "toll": 2.5},
        {"vehicle": "XYZ-100", "plaza": "B2", "time": "2026-09-18 08:05", "toll": 3.0},
        {"vehicle": "QRS-771", "plaza": "A1", "time": "2026-09-18 08:10", "toll": 2.5},
        {"vehicle": "QRS-771", "plaza": "D4", "time": "2026-09-18 10:15", "toll": 4.0},
        {"vehicle": "XYZ-100", "plaza": "C3", "time": "2026-09-18 10:30", "toll": 3.5},
    ]
    value, count = audit(reads)
    context = {"plazas": len(PLAZA_CONFIGURATION), "max_speed": MAX_SPEED_MPH}
