DEFAULT_CFG = {"max_jump": 50.0, "min_level": 0.0, "max_level": 100.0}


def fmt(level):
    if float(level).is_integer():
        return str(int(level))
    return "%.1f" % level


def parse_levels(raw, cfg=None):
    """Turn a comma separated cue list into validated intensity levels."""
    cfg = cfg or DEFAULT_CFG
    res = []
    for pos, chunk in enumerate(raw.split(","), start=1):
        text = chunk.strip()
        if not text:
            raise ValueError("empty intensity at position %d" % pos)
        try:
            val = float(text)
        except ValueError as err:
            raise ValueError("bad intensity %r at position %d (%s)" % (text, pos, err))
        if not cfg["min_level"] <= val <= cfg["max_level"]:
            raise ValueError("intensity %s at position %d is out of range" % (text, pos))
        res.append(val)
    return res


def crossfade(scenes, cfg=None, ctx=None):
    """Smooth a cue list, inserting fade steps where the jump is too fast."""
    cfg = cfg or DEFAULT_CFG
    param = cfg["max_jump"]
    if param <= 0:
        raise ValueError("max_jump must be positive, got %s" % fmt(param))
    if ctx is None:
        ctx = {}
    smooth = []
    buf = []
    cnt = 0
    prev = None
    for idx, elem in enumerate(scenes):
        curr = float(elem)
        if prev is None:
            smooth.append(curr)
            prev = curr
            continue
        delta = curr - prev
        if abs(delta) > param:
            cnt += 1
            buf.append(prev + delta / 2.0)
            tmp = buf[-1]
            smooth.append(tmp)
            msg = "choppy fade before cue %d: %s -> %s exceeds %s" % (
                idx + 1, fmt(prev), fmt(curr), fmt(param))
            ctx.setdefault("messages", []).append(msg)
        smooth.append(curr)
        prev = curr
    ctx["buffer"] = buf
    return smooth, cnt


def report(levels, cnt, ctx):
    lines = ["smoothed: " + ", ".join(fmt(num) for num in levels)]
    lines.append("snaps: %d" % cnt)
    inserted = ctx.get("buffer") or []
    if inserted:
        lines.append("inserted steps: " + ", ".join(fmt(step) for step in inserted))
    for pos, note in enumerate(ctx.get("messages", []), start=1):
        lines.append("  %d) %s" % (pos, note))
    return lines


def main():
    raw = "10, 100, 95, 20, 22"
    ctx = {}
    levels = parse_levels(raw)
    smooth, snaps = crossfade(levels, ctx=ctx)
    print("cue list: " + ", ".join(fmt(level) for level in levels))
    for line in report(smooth, snaps, ctx):
        print(line)


if __name__ == "__main__":
    main()

