def _lookup_threshold(baseline, altitude):
    """Return the threshold whose altitude range contains altitude, else None."""
    for rng, val in baseline.items():
        lo, hi = rng
        if lo <= altitude < hi:
            return float(val)
    return None


def _rolling_avg(buf):
    """Mean of the last five valid measurements held in the active window."""
    tmp = buf[-5:]
    return sum(tmp) / len(tmp)


def _parse_reading(elem):
    """Accept either a mapping or an (altitude, value) pair."""
    if isinstance(elem, dict):
        return float(elem["altitude"]), float(elem["value"])
    altitude, num = elem
    return float(altitude), float(num)


def calibrate(readings, baseline):
    res = []
    err = []
    buf = []
    prev = None
    for idx in range(len(readings)):
        elem = readings[idx]
        altitude, curr = _parse_reading(elem)
        param = _lookup_threshold(baseline, altitude)
        if param is None:
            err.append("reading %d: altitude %.0f m not covered by baseline" % (idx, altitude))
            continue
        if prev is None:
            diff = 0.0
        else:
            diff = abs(curr - prev)
        if diff > param:
            msg = "reading %d: change of %.2f exceeds threshold %.2f at %.0f m" % (
                idx, diff, param, altitude)
            err.append(msg)
            continue
        buf.append(curr)
        res.append(_rolling_avg(buf))
        prev = curr
    return res, err


def format_report(smoothed, failures):
    lines = []
    cnt = len(failures)
    lines.append("accepted %d reading(s), discarded %d" % (len(smoothed), cnt))
    for pos in range(len(smoothed)):
        val = smoothed[pos]
        lines.append("  [%02d] %7.3f" % (pos, val))
    for msg in failures:
        lines.append("  ! " + msg)
    return "\n".join(lines)


def main():
    cfg = {(0, 1000): 2.5, (1000, 3000): 4.0, (3000, 9000): 6.0}
    samples = [
        (120, 1013.2),
        (450, 1014.0),
        (800, 1019.5),
        (1200, 1017.8),
        (2400, 1014.1),
        (2900, 1013.6),
        (3500, 1012.9),
        {"altitude": 4200, "value": 1011.4},
        {"altitude": 12000, "value": 900.0},
    ]
    smoothed, failures = calibrate(samples, cfg)
    print(format_report(smoothed, failures))


if __name__ == "__main__":
    main()

