def validate(frames, offset):
    if not isinstance(offset, (int, float)):
        raise TypeError("offset must be numeric")
    for idx, elem in enumerate(frames):
        if len(elem) != 3:
            raise ValueError("frame %d must have 3 fields" % idx)
        if not isinstance(elem[2], list):
            raise TypeError("settings of frame %d must be a list" % idx)


def synchronize(frames, offset):
    validate(frames, offset)
    buf = []
    warnings = []
    cnt = 0
    prev = None
    for pos, (stamp, scene, settings) in enumerate(frames):
        val = stamp + offset
        if val < 0:
            msg = "frame %d: timestamp %s clamped to 0" % (pos, val)
            warnings.append(msg)
            val = 0
        if prev is not None and scene != prev:
            cnt += 1
        prev = scene
        buf.append((val, scene, list(settings)))
    return buf, cnt, warnings


def merge_settings(events):
    ctx = {}
    for _, scene, settings in events:
        tmp = ctx.setdefault(scene, [])
        for param in settings:
            if param not in tmp:
                tmp.append(param)
    return ctx


