    lines = ["realigned %d events, %d scene change(s)" % (len(events), cnt)]
    for curr in events:
        lines.append("  t=%-6s scene=%-8s settings=%s"
                     % (curr[0], curr[1], ",".join(curr[2]) or "-"))
    ctx = merge_settings(events)
    for scene in sorted(ctx):
        lines.append("  scene %s uses %d distinct setting(s)" % (scene, len(ctx[scene])))
    for err in warnings:
        lines.append("  WARNING: " + err)
    return "\n".join(lines)


