START_NODE = "gateway"


def normalize_layout(cfg):
    """Build a symmetric adjacency table from a raw layout mapping."""
    ctx = {}
    for node, neighbors in cfg.items():
        ctx.setdefault(node, [])
        for elem in neighbors:
            if elem not in ctx[node]:
                ctx[node].append(elem)
            ctx.setdefault(elem, [])
            if node not in ctx[elem]:
                ctx[elem].append(node)
    return ctx


def rebuild_path(prev, dest):
    path = []
    curr = dest
    while curr is not None:
        path.append(curr)
        curr = prev[curr]
    path.reverse()
    return path


def find_path(ctx, dest, limit):
    """Breadth-first search from the gateway, refusing to exceed limit hops."""
    if START_NODE not in ctx or dest not in ctx:
        return None
    prev = {START_NODE: None}
    depth = {START_NODE: 0}
    buf = [START_NODE]
    pos = 0
    while pos < len(buf):
        curr = buf[pos]
        pos += 1
        if curr == dest:
            return rebuild_path(prev, dest)
        if depth[curr] >= limit:
            continue
        for elem in ctx[curr]:
            if elem in prev:
                continue
            prev[elem] = curr
            depth[elem] = depth[curr] + 1
            buf.append(elem)
    return None


def parse_packet(param):
    if len(param) != 3:
        raise ValueError("expected 3 fields, got %d" % len(param))
    dest, num, payload = param
    if not isinstance(num, int) or num < 0:
        raise ValueError("invalid hop limit %r" % (num,))
    tmp = str(payload).strip()
    if not tmp:
        raise ValueError("empty payload")
    return dest, num, tmp


def route(packets, layout):
    ctx = normalize_layout(layout)
    res = []
    for idx, param in enumerate(packets):
        try:
            dest, num, payload = parse_packet(param)
        except (TypeError, ValueError) as err:
            res.append("packet %d rejected: %s" % (idx, err))
            continue
        path = find_path(ctx, dest, num)
        if path is None:
            res.append("%s: unreachable within %d hops" % (dest, num))
            continue
        val = len(payload)
        msg = "%s: delivered %d bytes via %s in %d hops" % (
            dest, val, " -> ".join(path), len(path) - 1)
        res.append(msg)
    return res


def main():
    cfg = {
        "gateway": ["switch-a", "switch-b"],
        "switch-a": ["host-1", "host-2"],
        "switch-b": ["host-3"],
        "host-3": ["host-4"],
        "island": [],
    }
    packets = [
        ("host-2", 3, "telemetry frame"),
        ("host-4", 2, "firmware chunk"),
        ("island", 5, "ping"),
        ("host-1", 4, "   "),
        ("host-3", 9),
    ]
    cnt = 0
    for idx, msg in enumerate(route(packets, cfg), 1):
        print("%2d. %s" % (idx, msg))
        if "delivered" in msg:
            cnt += 1
    print("delivered %d of %d packets" % (cnt, len(packets)))


if __name__ == "__main__":
