    if isinstance(param, dict):
        tmp = (param["target"], param.get("tolerance", param.get("variance")))
    else:
        tmp = tuple(param)
    if tmp[1] is None:
        raise ValueError("no variance given")
    return {"target": float(tmp[0]), "tol": abs(float(tmp[1]))}


def load_stages(stages):
    """Validate and convert the stage definitions supplied by the caller."""
    if not stages:
        raise ValueError("stages must define at least one heating phase")
    res = []
    idx = 0
    for elem in stages:
        idx += 1
        try:
            res.append(parse_stage(elem))
        except (TypeError, ValueError, KeyError, IndexError) as err:
            raise ValueError("stage %d is malformed: %s" % (idx, err))
    return res


def profile(temperatures, stages):
    """Check readings against the heating phases; return (completed, alerts)."""
    phases = load_stages(stages)
    alerts = []
    curr = 0
    cnt = 0
    num = 0
    done = 0
    pos = 0
    for reading in temperatures:
        pos += 1
        if curr >= len(phases):
            break
        cfg = phases[curr]
        val = float(reading)
        if abs(val - cfg["target"]) <= cfg["tol"]:
            cnt += 1
            if cnt == 5:
                done += 1
                curr += 1
                cnt = 0
                num = 0
        else:
            cnt = 0
            num += 1
            if num == 4:
                msg = "ALERT: phase %d off target %d times at reading %d (%.1f)" % (
                    curr + 1, num, pos, val)
                alerts.append(msg)
    return done, alerts


