    """Turn the profile() result into a human readable summary."""
    done, alerts = res
    buf = ["completed phases: %d of %d" % (done, total)]
    if alerts:
        buf.append("alerts raised: %d" % len(alerts))
        for msg in alerts:
            buf.append("  " + msg)
    else:
        buf.append("alerts raised: none")
    return "\n".join(buf)


