DIR_CFG = {
    "N": (0, 1),
    "E": (1, 0),
    "S": (0, -1),
    "W": (-1, 0),
}
ORDER = ("N", "E", "S", "W")
VALID = ("F", "L", "R")


def normalize_commands(commands):
    buf = []
    for elem in commands:
        val = str(elem).strip().upper()
        if val not in VALID:
            err = "unsupported command: {!r}".format(elem)
            raise ValueError(err)
        buf.append(val)
    return buf


def normalize_obstacles(obstacles):
    res = set()
    for elem in obstacles:
        tmp = tuple(elem)
        if len(tmp) != 2:
            raise ValueError("obstacle must have two coordinates: {!r}".format(elem))
        for num in tmp:
            if not isinstance(num, int):
                raise ValueError("obstacle coordinates must be integers: {!r}".format(elem))
        res.add(tmp)
    return res


def advance(pos, heading):
    param = DIR_CFG[heading]
    return (pos[0] + param[0], pos[1] + param[1])


def navigate(commands, obstacles):
    buf = normalize_commands(commands)
    blocked = normalize_obstacles(obstacles)
    pos = (0, 0)
    idx = 0
    res = []
    for curr in buf:
        if curr == "F":
            tmp = advance(pos, ORDER[idx])
            if tmp in blocked:
                msg = "Collision at ({}, {}) while facing {}".format(tmp[0], tmp[1], ORDER[idx])
                res.append(msg)
                break
            pos = tmp
        elif curr == "L":
            idx = (idx - 1) % len(ORDER)
        else:
            idx = (idx + 1) % len(ORDER)
    return pos, res


def format_report(pos, collisions):
    cnt = len(collisions)
    lines = ["final position: ({}, {})".format(pos[0], pos[1]), "collisions: {}".format(cnt)]
    for msg in collisions:
        lines.append("  - " + msg)
    return "\n".join(lines)


def main():
    scenarios = [
        {"label": "clear run", "commands": "FFRFFLF", "obstacles": [(4, 4), (-1, 0)]},
        {"label": "blocked ahead", "commands": "FFFRFF", "obstacles": [(0, 2), (2, 2)]},
        {"label": "loop in place", "commands": "LLRRF", "obstacles": [(1, 1)]},
    ]
    for ctx in scenarios:
        pos, collisions = navigate(ctx["commands"], ctx["obstacles"])
        print(ctx["label"] + " -> " + ctx["commands"])
        print(format_report(pos, collisions))
        print()


if __name__ == "__main__":
    main()

