OPS = {
    "add": lambda prev, num: prev + num,
    "sub": lambda prev, num: prev - num,
    "mul": lambda prev, num: prev * num,
    "div": lambda prev, num: prev / num,
    "mod": lambda prev, num: prev % num,
}


def load(registers, param):
    """Return the numeric content named by a source identifier."""
    if isinstance(param, (int, float)):
        return param
    if param not in registers:
        raise KeyError("unknown source register %r" % param)
    return registers[param]


def parse_line(text):
    """Turn one line of assembly text into an instruction tuple, or None."""
    pos = text.find("#")
    if pos >= 0:
        text = text[:pos]
    tmp = text.split()
    if not tmp:
        return None
    if len(tmp) != 3:
        raise ValueError("malformed instruction: %r" % text.strip())
    op, dst, src = tmp
    if src.lstrip("-").isdigit():
        src = int(src)
    return (op.lower(), dst, src)


def execute(instructions, registers):
    res = dict(registers)
    faults = []
    for idx, elem in enumerate(instructions):
        op, dst, src = elem
        if op not in OPS:
            raise ValueError("unsupported operation %r" % op)
        num = load(res, src)
        prev = res.get(dst, 0)
        try:
            curr = OPS[op](prev, num)
        except ZeroDivisionError as err:
            msg = "instruction %d (%s %s %s): %s" % (idx, op, dst, src, err)
            faults.append(msg)
            continue
        res[dst] = curr
    return res, faults


def report(ctx, faults):
    buf = []
    width = max((len(name) for name in ctx), default=1)
    for name in sorted(ctx):
        buf.append("%-*s = %s" % (width, name, ctx[name]))
    cnt = len(faults)
    buf.append("faults: %d" % cnt)
    for msg in faults:
        buf.append("  " + msg)
    return "\n".join(buf)


def main():
    program = """
    add a b      # a = a + b
    mul a 3
    div a c      # c holds zero, so this faults
    sub b 1
    mod a b
    div a b
    """
    cfg = {"a": 10, "b": 3, "c": 0}
    instructions = []
    for text in program.splitlines():
        elem = parse_line(text)
        if elem is not None:
            instructions.append(elem)
    final, faults = execute(instructions, cfg)
    print(report(final, faults))


if __name__ == "__main__":
    main()

