import sys


def reverse_string(s):
    if not isinstance(s, str):
        raise TypeError("expected str, got %s" % type(s).__name__)
    buf = list(s)
    idx = 0
    pos = len(buf) - 1
    while idx < pos:
        tmp = buf[idx]
        buf[idx] = buf[pos]
        buf[pos] = tmp
        idx += 1
        pos -= 1
    return "".join(buf)


def repeat_reverse(s, num):
    curr = s
    while num > 0:
        prev = curr
        curr = reverse_string(curr)
        num -= 1
        if curr == prev:
            break
    return curr


def reverse_words(text):
    return " ".join(reverse_string(word) for word in text.split())


def is_palindrome(s):
    cleaned = "".join(ch.lower() for ch in s if ch.isalnum())
    return cleaned == reverse_string(cleaned)


def parse_args(argv):
    cfg = {"words": False, "repeat": 1}
    items = []
    for elem in argv:
        if elem.startswith("--"):
            tmp = elem[2:].split("=", 1)
            param = tmp[0]
            val = tmp[1] if len(tmp) > 1 else ""
            if param == "words":
                cfg["words"] = True
            elif param == "repeat":
                if not val.isdigit() or int(val) < 1:
                    raise ValueError("--repeat needs a positive integer")
                cfg["repeat"] = int(val)
            else:
                raise ValueError("unknown option: " + param)
        else:
            items.append(elem)
    return cfg, items


def analyze(param, cfg):
    res = {
        "reversed": repeat_reverse(param, cfg["repeat"]),
        "palindrome": is_palindrome(param),
    }
    if cfg["words"]:
        res["words"] = reverse_words(param)
    return res


def format_report(items, cfg):
    ctx = {"width": max((len(elem) for elem in items), default=0)}
    lines = []
    cnt = 0
    for idx, elem in enumerate(items, 1):
        res = analyze(elem, cfg)
        msg = "%2d. %-*s -> %s" % (idx, ctx["width"], elem, res["reversed"])
        if cfg["words"]:
            msg += " | words: " + res["words"]
        if res["palindrome"]:
            cnt += 1
            msg += " | palindrome"
        lines.append(msg)
    lines.append("%d of %d input(s) are palindromes" % (cnt, len(items)))
    return lines


def main(argv):
    try:
        cfg, items = parse_args(argv[1:])
    except ValueError as err:
        sys.stderr.write("error: %s\n" % err)
        return 2
    if not items:
        items = [line.rstrip("\n") for line in sys.stdin if line.strip()]
    for msg in format_report(items, cfg):
        print(msg)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

