import sys


def normalize(text):
    """Return only the alphanumeric characters of *text*, lowercased."""
    buf = []
    for elem in text:
        if elem.isalnum():
            buf.append(elem.lower())
    return "".join(buf)


def is_palindrome(text):
    """True if *text* reads the same both ways, ignoring case and punctuation."""
    if not isinstance(text, str):
        msg = "text must be a string, got %s" % type(text).__name__
        raise TypeError(msg)
    val = normalize(text)
    pos = 0
    idx = len(val) - 1
    while pos < idx:
        if val[pos] != val[idx]:
            return False
        pos += 1
        idx -= 1
    return True


def is_strict_palindrome(text):
    """True if *text* is a palindrome character for character, as written."""
    return text == text[::-1]


def describe(text, cfg):
    """Classify *text* and build the one-line report for it."""
    if cfg["strict"]:
        res = is_strict_palindrome(text)
    else:
        res = is_palindrome(text)
    tmp = normalize(text)
    num = len(tmp)
    msg = "%-32s %-5s (%d significant chars)" % (repr(text), res, num)
    return res, msg


def summarize(ctx):
    num = ctx["total"]
    cnt = ctx["palindromes"]
    if num == 0:
        return "no input lines"
    val = 100.0 * cnt / num
    return "%d/%d palindromes (%.1f%%)" % (cnt, num, val)


def parse_args(argv):
    cfg = {"quiet": False, "strict": False}
    for param in argv:
        if param in ("-q", "--quiet"):
            cfg["quiet"] = True
        elif param in ("-s", "--strict"):
            cfg["strict"] = True
        else:
            raise ValueError("unknown option: %r" % param)
    return cfg


def main(argv):
    try:
        cfg = parse_args(argv)
    except ValueError as err:
        print("error: %s" % err, file=sys.stderr)
        return 2
    ctx = {"total": 0, "palindromes": 0}
    for line in sys.stdin:
        curr = line.rstrip("\n")
        if not curr.strip():
            continue
        res, msg = describe(curr, cfg)
        ctx["total"] += 1
        if res:
            ctx["palindromes"] += 1
        if not cfg["quiet"]:
            print(msg)
    print(summarize(ctx))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

