def calculate_average(numbers):
    """Return the arithmetic mean of numbers, or 0 for an empty list."""
    cnt = len(numbers)
    if cnt == 0:
        return 0
    tmp = 0.0
    for elem in numbers:
        tmp += elem
    return tmp / cnt


def parse_row(text):
    """Split a comma/space separated row into floats, reporting bad fields."""
    buf = []
    err = None
    pos = 0
    for param in text.replace(",", " ").split():
        pos += 1
        try:
            buf.append(float(param))
        except ValueError:
            err = "field %d is not a number: %r" % (pos, param)
            break
    return buf, err


def running_averages(numbers):
    """Average of every prefix of numbers, computed incrementally."""
    res = []
    total = 0.0
    for idx, val in enumerate(numbers, start=1):
        total += val
        res.append(total / idx)
    return res


def describe_trend(averages):
    """Summarise how the running average moves from one prefix to the next."""
    if len(averages) < 2:
        return "flat"
    prev = averages[0]
    ups = 0
    downs = 0
    for curr in averages[1:]:
        if curr > prev:
            ups += 1
        elif curr < prev:
            downs += 1
        prev = curr
    if ups and not downs:
        return "rising"
    if downs and not ups:
        return "falling"
    if ups or downs:
        return "mixed"
    return "flat"


def format_report(label, numbers):
    """Build a one-block report for a labelled row of numbers."""
    average = calculate_average(numbers)
    lines = ["%s: n=%d average=%s" % (label, len(numbers), average)]
    if numbers:
        marks = running_averages(numbers)
        lines.append("  prefix averages: " + ", ".join("%.3f" % m for m in marks))
        lines.append("  trend: " + describe_trend(marks))
    return "\n".join(lines)


def main():
    cfg = {
        "empty": "",
        "simple": "10, 20, 30",
        "decimals": "1.5 2.5 4.0 8.0",
        "broken": "3, 4, x, 5",
    }
    for label in sorted(cfg):
        values, err = parse_row(cfg[label])
        if err is not None:
            msg = "%s: skipped (%s)" % (label, err)
            print(msg)
            continue
        print(format_report(label, values))


if __name__ == "__main__":
    main()

