def remove_duplicates(items):
    """Return a new list without duplicates, keeping first-occurrence order."""
    seen = set()
    buf = []
    for elem in items:
        if elem in seen:
            continue
        seen.add(elem)
        buf.append(elem)
    return buf


def removed_indices(items):
    """Pairs (index of the dropped item, index of the kept first occurrence)."""
    first = {}
    res = []
    for idx, elem in enumerate(items):
        pos = first.get(elem, _MISSING)
        if pos is _MISSING:
            first[elem] = idx
        else:
            res.append((idx, pos))
    return res


def count_adjacent_repeats(items):
    cnt = 0
    prev = _MISSING
    for curr in items:
        if prev is not _MISSING and curr == prev:
            cnt += 1
        prev = curr
    return cnt


def parse_tokens(line, cfg):
    res = []
    for tmp in line.split(cfg["separator"]):
        tmp = tmp.strip()
        if not tmp:
            raise ValueError("empty field in %r" % line)
        try:
            val = int(tmp)
        except ValueError:
            val = tmp
        res.append(val)
    return res


def format_report(cfg, ctx, label, items):
    res = remove_duplicates(items)
    num = len(res)
    cnt = len(items) - num
    parts = [label.ljust(cfg["width"]), "unique=%d" % num, "removed=%d" % cnt,
             "adjacent=%d" % count_adjacent_repeats(items)]
    if cfg["show_removed"] and cnt:
        buf = ["%d->%d" % (idx, pos) for idx, pos in removed_indices(items)]
        parts.append("dups[" + ",".join(buf) + "]")
    ctx["total_removed"] += cnt
    return cfg["field_separator"].join(parts), res


