OPS = {
    '+': lambda a, b: a + b,
    '-': lambda a, b: a - b,
    '*': lambda a, b: a * b,
    '/': lambda a, b: a / b,
}


def simple_calculator(num1, operator, num2):
    """Apply operator to num1 and num2, returning 'Error' for division by zero."""
    operation = OPS.get(operator)
    if operation is None:
        return 'Error'
    if operator == '/' and num2 == 0:
        return 'Error'
    return operation(num1, num2)


def parse_number(token):
    """Turn a numeric token into an int when possible, otherwise a float."""
    val = float(token)
    if val.is_integer() and '.' not in token and 'e' not in token.lower():
        return int(val)
    return val


def tokenize(buf):
    """Split an expression like '10 / 0' or '10/0' into three tokens."""
    res = []
    curr = ''
    prev = ''
    for pos, elem in enumerate(buf):
        if elem.isspace():
            if curr:
                res.append(curr)
                curr = ''
        elif elem in OPS:
            signed = elem == '-' and (pos == 0 or prev in OPS)
            if signed:
                curr += elem
            else:
                if curr:
                    res.append(curr)
                    curr = ''
                res.append(elem)
        else:
            curr += elem
        prev = elem
    if curr:
        res.append(curr)
    return res


def evaluate(expr):
    """Evaluate a two-operand expression string; return the value or 'Error'."""
    tokens = tokenize(expr)
    if len(tokens) != 3:
        return 'Error'
    try:
        num = parse_number(tokens[0])
        val = parse_number(tokens[2])
    except ValueError:
        return 'Error'
    return simple_calculator(num, tokens[1], val)


def format_result(expr, val):
    if val == 'Error':
        return '{0} = Error'.format(expr)
    if isinstance(val, float):
        return '{0} = {1:.4g}'.format(expr, val)
    return '{0} = {1}'.format(expr, val)


def main():
    expressions = ['10 + 5', '10 / 0', '7*6', '-3 - 4', '9 / 4', '2 ^ 8', '5 +']
    err = 0
    for idx, expr in enumerate(expressions, start=1):
        res = evaluate(expr)
        if res == 'Error':
            err += 1
        msg = format_result(expr, res)
        print('{0:>2}. {1}'.format(idx, msg))
    cnt = len(expressions) - err
    print('{0} of {1} expressions evaluated, {2} failed'.format(cnt, len(expressions), err))


if __name__ == '__main__':
    main()

