PUNCT_WORD_CHARS = "-'"


def scan_words(sentence):
    """Return a list of (word, start offset) pairs found in the sentence."""
    res = []
    buf = []
    pos = 0
    prev = ""
    for idx, curr in enumerate(sentence):
        if curr.isalnum() or (curr in PUNCT_WORD_CHARS and prev.isalnum()):
            if not buf:
                pos = idx
            buf.append(curr)
        elif buf:
            res.append(("".join(buf), pos))
            buf = []
        prev = curr
    if buf:
        res.append(("".join(buf), pos))
    return res


def longest_entry(sentence):
    """Return the (word, offset) pair of the first longest word, or None."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string, got %r" % type(sentence).__name__)
    curr = None
    num = 0
    for elem in scan_words(sentence):
        val = len(elem[0])
        if val > num:
            curr = elem
            num = val
    return curr


def find_longest_word(sentence):
    res = longest_entry(sentence)
    if res is None:
        return ""
    return res[0]


def format_report(sentence, ctx):
    entry = longest_entry(sentence)
    tmp = " ".join(sentence.split())
    width = ctx["width"]
    if len(tmp) > width:
        tmp = tmp[:width - 3] + "..."
    if entry is None:
        return "%-*s -> (no words found)" % (width, tmp)
    word, pos = entry
    cnt = sum(1 for elem in scan_words(sentence) if len(elem[0]) == len(word)) - 1
