import os
import sys


def count_lines_in_file(filepath):
    cnt = 0
    prev = b""
    with open(filepath, "rb") as fh:
        while True:
            buf = fh.read(1 << 16)
            if not buf:
                break
            cnt += buf.count(b"\n")
            prev = buf[-1:]
    if prev and prev != b"\n":
        cnt += 1
    return cnt


def count_nonempty_lines(filepath):
    num = 0
    with open(filepath, "r", errors="replace") as fh:
        for line in fh:
            if line.strip():
                num += 1
    return num


def longest_line(filepath):
    pos = 0
    idx = 0
    res = 0
    with open(filepath, "r", errors="replace") as fh:
        for line in fh:
            pos += 1
            val = len(line.rstrip("\n"))
            if val > res:
                res = val
                idx = pos
    return idx, res


def build_report(filepath, cfg):
    ctx = {
        "path": filepath,
        "lines": count_lines_in_file(filepath),
        "bytes": os.path.getsize(filepath),
    }
    if cfg.get("nonempty"):
        ctx["nonempty"] = count_nonempty_lines(filepath)
    if cfg.get("longest"):
        ctx["longest_at"], ctx["longest_len"] = longest_line(filepath)
    return ctx


def format_report(ctx):
    parts = ["%s: %d lines, %d bytes" % (ctx["path"], ctx["lines"], ctx["bytes"])]
    if "nonempty" in ctx:
        parts.append("%d non-empty" % ctx["nonempty"])
    if "longest_len" in ctx:
        parts.append("longest line %d (%d chars)" % (ctx["longest_at"], ctx["longest_len"]))
    return ", ".join(parts)


def main(argv):
    cfg = {"nonempty": "-n" in argv, "longest": "-l" in argv}
    targets = [param for param in argv[1:] if not param.startswith("-")]
    if not targets:
        sys.stderr.write("usage: %s [-n] [-l] FILE...\n" % argv[0])
        return 2
    err = 0
    total = 0
    for path in targets:
        try:
            ctx = build_report(path, cfg)
        except OSError as exc:
            msg = "cannot read %s: %s" % (path, exc.strerror)
            sys.stderr.write(msg + "\n")
            err = 1
            continue
        total += ctx["lines"]
        print(format_report(ctx))
    if len(targets) > 1:
        print("total: %d lines" % total)
    return err


if __name__ == "__main__":
    sys.exit(main(sys.argv))

