MIN_YEAR = 1000


def calculate_age(birth_year, current_year):
    """Return the age in whole years given a birth year and the current year."""
    for param in (birth_year, current_year):
        if isinstance(param, bool) or not isinstance(param, int):
            raise TypeError("years must be integers, got %r" % (param,))
        if param < MIN_YEAR:
            raise ValueError("year %d is before %d" % (param, MIN_YEAR))
    if birth_year > current_year:
        raise ValueError("birth year %d is after current year %d" % (birth_year, current_year))
    return current_year - birth_year


def parse_record(line):
    """Split a "name,birth_year" record into a (name, year) pair."""
    buf = line.strip()
    pos = buf.find(",")
    if pos < 0:
        raise ValueError("missing comma in record %r" % (buf,))
    name = buf[:pos].strip()
    num = buf[pos + 1:].strip()
    if not name:
        raise ValueError("empty name in record %r" % (buf,))
    return name, int(num)


def build_report(records, cfg):
    """Turn raw records into formatted lines, collecting errors as messages."""
    year = cfg["current_year"]
    res = []
    cnt = 0
    for idx, line in enumerate(records, start=1):
        try:
            name, birth = parse_record(line)
            val = calculate_age(birth, year)
        except (TypeError, ValueError) as err:
            res.append("line %d: skipped (%s)" % (idx, err))
            continue
        cnt += 1
        res.append("%-8s %4d %3d" % (name, birth, val))
    res.append("%d of %d records accepted" % (cnt, len(records)))
    return res


def oldest(records, cfg):
    """Return the (name, age) of the oldest valid person, or None."""
    year = cfg["current_year"]
    best = None
    for line in records:
        try:
            name, birth = parse_record(line)
            age = calculate_age(birth, year)
        except (TypeError, ValueError):
            continue
        elem = (name, age)
        if best is None or elem[1] > best[1]:
            best = elem
    return best


def main():
    ctx = {"current_year": 2023}
    data = [
        "Ada,1990",
        "Bob,2000",
        "Cleo,2025",
        "Dan",
        "Eve,1958",
    ]
    for msg in build_report(data, ctx):
        print(msg)
    tmp = oldest(data, ctx)
    if tmp is not None:
        print("oldest: %s (%d)" % tmp)


if __name__ == "__main__":
    main()

