    if not isinstance(email, str):
        return False

    idx_at = email.find('@')
    idx_dot = email.rfind('.')

    if idx_at == -1 or idx_dot == -1:
        return False

    if idx_at > idx_dot:
        return False

    if idx_at == 0 or idx_dot == len(email) - 1:
        return False

