def update_inventory(inventory, item_name, quantity):
    """Add quantity to item_name in inventory, creating the entry if needed."""
    if not isinstance(item_name, str) or not item_name.strip():
        raise ValueError("item name must be a non-empty string")
    if not isinstance(quantity, int):
        raise TypeError("quantity must be an integer")
    curr = inventory.get(item_name, 0)
    inventory[item_name] = curr + quantity
    return inventory


def parse_transaction(line):
    """Turn 'name,quantity' into a (name, quantity) pair."""
    parts = line.split(",")
    if len(parts) != 2:
        raise ValueError("expected 'name,quantity', got %r" % line)
    param = parts[0].strip()
    val = parts[1].strip()
    try:
        num = int(val)
    except ValueError:
        raise ValueError("bad quantity %r for %r" % (val, param))
    return param, num


def apply_transactions(inventory, lines):
    """Apply every transaction line, collecting errors instead of raising."""
    ctx = {"applied": 0, "errors": []}
    for idx, line in enumerate(lines, start=1):
        tmp = line.strip()
        if not tmp or tmp.startswith("#"):
            continue
        try:
            name, num = parse_transaction(tmp)
            update_inventory(inventory, name, num)
        except (ValueError, TypeError) as err:
            msg = "line %d: %s" % (idx, err)
            ctx["errors"].append(msg)
        else:
            ctx["applied"] += 1
    return ctx


def format_report(inventory, width=20):
    """Render the inventory as an aligned text table with a total."""
    buf = []
    cnt = 0
    for name in sorted(inventory):
        val = inventory[name]
        buf.append(name.ljust(width) + str(val).rjust(6))
        cnt += val
    buf.append("-" * (width + 6))
    buf.append("TOTAL".ljust(width) + str(cnt).rjust(6))
    return "\n".join(buf)


def main():
    cfg = {
        "start": {"apple": 10},
        "feed": [
            "apple,5",
            "banana,3",
            "# restock",
            "banana,12",
            "cherry,seven",
            "apple,-4",
            "date",
