    for pos, err in enumerate(res["errors"], start=1):
        print("  error %d: %s" % (pos, err))
    print(format_report(inventory))
    prev = inventory.get("apple")
    update_inventory(inventory, "apple", 100)
    print("apple: %d -> %d" % (prev, inventory["apple"]))


if __name__ == "__main__":
