def capitalize_sentences(text):
    """Capitalize the first letter of every sentence in `text`."""
    if not isinstance(text, str):
        raise TypeError("text must be a string, got %s" % type(text).__name__)
    buf = []
    pending = True
    for curr in text:
        if pending and curr.isalpha():
            buf.append(curr.upper())
            pending = False
        else:
