BEATS = {"rock": "scissors", "paper": "rock", "scissors": "paper"}

ALIASES = {"r": "rock", "p": "paper", "s": "scissors"}


def normalize(choice):
    """Turn a raw choice into one of 'rock', 'paper', 'scissors'."""
    val = choice.strip().lower()
    val = ALIASES.get(val, val)
    if val not in BEATS:
        raise ValueError("unknown choice: %r" % (choice,))
    return val


def rock_paper_scissors(player1_choice, player2_choice):
    """Play one round and report the outcome as a message."""
    first = normalize(player1_choice)
    second = normalize(player2_choice)
    if first == second:
        return "It's a tie!"
    if BEATS[first] == second:
        return "Player 1 wins!"
    return "Player 2 wins!"


def parse_round(line):
    """Split a line like 'rock vs scissors' into the two raw choices."""
    parts = line.split("vs")
    if len(parts) != 2:
        raise ValueError("cannot read round from %r" % (line,))
    return parts[0].strip(), parts[1].strip()


def play_match(lines):
    """Score lines of the form 'rock vs paper', returning a summary dict."""
    res = {"Player 1 wins!": 0, "Player 2 wins!": 0, "It's a tie!": 0}
    rows = []
    errors = []
    for idx, elem in enumerate(lines, start=1):
        try:
            left, right = parse_round(elem)
            msg = rock_paper_scissors(left, right)
        except ValueError as err:
            errors.append((idx, str(err)))
            continue
        res[msg] += 1
        rows.append((idx, left, right, msg))
    return {"tally": res, "rows": rows, "errors": errors, "played": sum(res.values())}


def format_report(summary):
    """Render a match summary (as built by play_match) as text."""
    buf = []
    for num, left, right, msg in summary["rows"]:
        buf.append("Round %d: %s vs %s -> %s" % (num, left, right, msg))
    tally = summary["tally"]
    buf.append("Rounds played: %d" % summary["played"])
    for msg, cnt in tally.items():
        buf.append("  %-16s %d" % (msg, cnt))
    p1, p2 = tally["Player 1 wins!"], tally["Player 2 wins!"]
    if p1 > p2:
        buf.append("Match winner: Player 1")
    elif p2 > p1:
        buf.append("Match winner: Player 2")
    else:
        buf.append("Match drawn")
    for pos, err in summary["errors"]:
        buf.append("Round %d skipped: %s" % (pos, err))
    return "\n".join(buf)


def main():
    rounds = [
        "rock vs scissors",
        "paper vs rock",
        "Scissors vs scissors",
        "r vs paper",
        "lizard vs rock",
        "rock",
    ]
    print(format_report(play_match(rounds)))


if __name__ == "__main__":
    main()

