def run_length_encode(s: str) -> str:
    if not s:
        return ""

    res_buf = []
    curr_char = s[0]
    cnt_char = 1

    for idx in range(1, len(s)):
        elem = s[idx]
        if elem == curr_char:
            cnt_char += 1
        else:
            res_buf.append(curr_char)
            res_buf.append(str(cnt_char))
            curr_char = elem
            cnt_char = 1

    res_buf.append(curr_char)
    res_buf.append(str(cnt_char))

    return "".join(res_buf)

