import sys


def char_frequency(text):
    if not isinstance(text, str):
        msg = "text must be a str, got {}".format(type(text).__name__)
        raise TypeError(msg)
    frequency_map = {}
    for curr in text:
        elem = curr.lower()
        cnt = frequency_map.get(elem, 0)
        frequency_map[elem] = cnt + 1
    return frequency_map


def order_items(frequency_map, cfg):
    res = list(frequency_map.items())
    param = cfg.get("sort_by", "char")
    if param == "count":
        res.sort(key=lambda pair: (-pair[1], pair[0]))
    elif param == "char":
        res.sort(key=lambda pair: pair[0])
    else:
        raise ValueError("unknown sort_by: " + param)
    num = cfg.get("limit")
    if num is not None:
        res = res[:num]
    return res


def longest_run(text):
    res = (None, 0, -1)
    prev = None
    cnt = 0
    pos = 0
    for idx, curr in enumerate(text.lower()):
        if curr == prev:
            cnt += 1
        else:
            cnt = 1
            pos = idx
        if cnt > res[1]:
            res = (curr, cnt, pos)
        prev = curr
    return res


def format_report(text, cfg):
    frequency_map = char_frequency(text)
    if not frequency_map:
        return "text: '' (no characters to count)"
    num = sum(frequency_map.values())
    buf = ["text: {!r} ({} characters)".format(text, num)]
    for idx, pair in enumerate(order_items(frequency_map, cfg), 1):
        curr, val = pair
        buf.append("{:>3}. {!r} -> {:>3} ({:5.1f}%)".format(idx, curr, val, 100.0 * val / num))
    curr, cnt, pos = longest_run(text)
    if cnt > 1:
        buf.append("longest run: {!r} x{} at index {}".format(curr, cnt, pos))
    return "\n".join(buf)


def parse_cfg(args):
    cfg = {"sort_by": "char", "limit": None}
    for param in args:
        if "=" not in param:
            raise ValueError("expected key=value, got " + param)
        key, val = param.split("=", 1)
        if key == "sort_by":
            cfg["sort_by"] = val
        elif key == "limit":
            cfg["limit"] = int(val)
        else:
            raise ValueError("unknown option: " + key)
    return cfg


