    result = dict1.copy()
    for current_key, current_value in dict2.items():
        result[current_key] = current_value
    return result

def example_usage():
    configuration = {'a': 1, 'b': 2}
    temporary_dict = {'b': 3, 'c': 4}
    merged_configuration = update_dict(configuration, temporary_dict)
    print(f"Example 1: {merged_configuration}")

    context = {'x': 10}
    new_data = {'y': 20}
    final_context = update_dict(context, new_data)
    print(f"Example 2: {final_context}")

    # Additional test
    previous_state = {'status': 'active', 'user_id': 101}
    current_update = {'user_id': 102, 'timestamp': '2023-10-27'}
    updated_state = update_dict(previous_state, current_update)
    print(f"Additional Test: {updated_state}")

if __name__ == "__main__":
    example_usage()

