import sys

DEFAULT_CFG = {"width": 6, "show_delta": True, "max_limit": 10000}


def parse_limit(param):
    """Turn a command-line argument into a non-negative int limit."""
    tmp = str(param).strip()
    if not tmp:
        raise ValueError("empty limit")
    try:
        val = int(tmp, 10)
    except ValueError as err:
        raise ValueError("limit is not an integer: %s" % tmp) from err
    if val < 0:
        raise ValueError("limit must be non-negative, got %d" % val)
    return val


def cubes_up_to(limit):
    """Return the cubes of 0..limit inclusive as a list of ints."""
    if not isinstance(limit, int) or isinstance(limit, bool):
        raise TypeError("limit must be an int")
    if limit < 0:
        raise ValueError("limit must be non-negative")
    cubes_list = [num ** 3 for num in range(limit + 1)]
    return cubes_list


def format_row(idx, curr, prev, cfg):
    """Render one table line: index, cube and optionally the step size."""
    width = cfg["width"]
    msg = "%*d -> %*d" % (width, idx, width, curr)
    if cfg["show_delta"] and prev is not None:
        msg += "  (+%d)" % (curr - prev)
    return msg


def build_report(cubes_list, cfg):
    """Build the printable report lines for an already computed cube list."""
    buf = []
    prev = None
    for idx, curr in enumerate(cubes_list):
        buf.append(format_row(idx, curr, prev, cfg))
        prev = curr
    cnt = len(cubes_list)
    buf.append("%d cube(s), last = %d" % (cnt, cubes_list[-1]))
    return buf


def main(argv):
    cfg = dict(DEFAULT_CFG)
    args = [a for a in argv[1:] if a != "--no-delta"]
    if len(args) != len(argv[1:]):
        cfg["show_delta"] = False
    if not args:
        args = ["3"]
    ctx = {"failures": 0}
    for pos, param in enumerate(args):
        try:
            limit = parse_limit(param)
            if limit > cfg["max_limit"]:
                raise ValueError("limit %d exceeds %d" % (limit, cfg["max_limit"]))
            res = cubes_up_to(limit)
        except ValueError as err:
            print("argument %d: %s" % (pos + 1, err), file=sys.stderr)
            ctx["failures"] += 1
            continue
        for elem in build_report(res, cfg):
            print(elem)
    return 1 if ctx["failures"] else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

