def count_char(txt, chr_to_cnt):
    """Counts occurrences of a character in a string."""
    if not isinstance(txt, str) or not isinstance(chr_to_cnt, str):
        raise TypeError("Both arguments must be strings.")
    if len(chr_to_cnt) != 1:
        raise ValueError("Second argument must be a single character.")

    cnt = 0
    for elem in txt:
        if elem == chr_to_cnt:
            cnt += 1
    return cnt

def process_data(data_list, target_char):
    """Processes a list of strings to count target_char in each."""
    res_list = []
    for idx, curr_str in enumerate(data_list):
        num_occur = count_char(curr_str, target_char)
        msg = f"String at index {idx} has {num_occur} occurrences of '{target_char}'."
        res_list.append(msg)
    return res_list

def analyze_text_buffer(buf_str, char_val):
    """Analyzes a text buffer for character counts."""
    curr_cnt = count_char(buf_str, char_val)
    tmp_msg = f"Total count of '{char_val}' in buffer: {curr_cnt}"
    return tmp_msg

def main():
    cfg_data = ['apple', 'banana', 'cherry', 'date']
    param_char = 'a'
    results = process_data(cfg_data, param_char)
    for res in results:
        print(res)

    test_buf = "hello world how are you"
    char_to_find = 'o'
    analysis_res = analyze_text_buffer(test_buf, char_to_find)
    print(analysis_res)

if __name__ == "__main__":
    main()

