import sys

DIGIT_VALUES = {ch: val for val, ch in enumerate("0123456789abcdef")}


def digit_value(curr, pos):
    """Return the numeric value of a single hex digit."""
    val = DIGIT_VALUES.get(curr.lower())
    if val is None:
        raise ValueError("invalid hex digit %r at position %d" % (curr, pos))
    return val


def split_sign(hex_string):
    """Split a hex literal into a sign (+1/-1) and its bare digit string."""
    tmp = hex_string.strip().replace("_", "")
    sign = 1
    if tmp[:1] in "+-":
        sign = -1 if tmp[0] == "-" else 1
        tmp = tmp[1:]
    if tmp[:2].lower() == "0x":
        tmp = tmp[2:]
    return sign, tmp


def hex_to_decimal(hex_string):
    sign, buf = split_sign(hex_string)
    if not buf:
        raise ValueError("no hexadecimal digits found")
    num = 0
    for pos, curr in enumerate(buf):
        num = num * 16 + digit_value(curr, pos)
    return sign * num


def describe_steps(buf):
    """Return one explanatory line per hex digit of the given digit string."""
    res = []
    prev = 0
    for pos, curr in enumerate(buf):
        val = digit_value(curr, pos)
        curr_total = prev * 16 + val
        res.append("  step %d: %s -> %d*16+%d = %d" % (pos, curr, prev, val, curr_total))
        prev = curr_total
    return res


def group_digits(buf, size=4):
    """Regroup hex digits into blocks of the given width, counted from the right."""
    out = []
    pos = len(buf)
    while pos > 0:
        out.append(buf[max(0, pos - size):pos])
        pos -= size
    return "_".join(reversed(out))


def main(argv):
    verbose = False
    inputs = []
    for elem in argv[1:]:
        if elem in ("-v", "--verbose"):
            verbose = True
        else:
            inputs.append(elem)
    if not inputs:
        inputs = [line.strip() for line in sys.stdin if line.strip()]

    cnt = 0
    for param in inputs:
        try:
            num = hex_to_decimal(param)
        except ValueError as err:
            print("%s: error: %s" % (param, err))
            cnt += 1
            continue
        sign, buf = split_sign(param)
        print("%s%s = %d" % ("-" if sign < 0 else "", group_digits(buf), num))
        if verbose:
            for msg in describe_steps(buf):
                print(msg)
    return 1 if cnt else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

