def calculate_discount_price(original_price, discount_percentage):
    """Return the price left after removing discount_percentage percent."""
    for param, val in (("original_price", original_price),
                       ("discount_percentage", discount_percentage)):
        if not isinstance(val, (int, float)) or isinstance(val, bool):
            raise TypeError("%s must be numeric" % param)
    if original_price < 0:
        raise ValueError("original_price must not be negative")
    if not 0 <= discount_percentage <= 100:
        raise ValueError("discount_percentage must be between 0 and 100")
    res = original_price * (1.0 - discount_percentage / 100.0)
    return round(float(res), 2)


def parse_item(line):
    """Turn 'name;price;percent' into (name, price, percent)."""
    buf = [elem.strip() for elem in line.split(";")]
    if len(buf) != 3:
        raise ValueError("expected 3 fields, got %d" % len(buf))
    name = buf[0]
    if not name:
        raise ValueError("item name is empty")
    num = float(buf[1])
    val = float(buf[2])
    return name, num, val


def build_report(lines, cfg):
    """Price every line, returning (rows, errors) with rows sorted by saving."""
    rows = []
    errors = []
    for idx, line in enumerate(lines, start=1):
        tmp = line.strip()
        if not tmp or tmp.startswith(cfg["comment"]):
            continue
        try:
            name, num, val = parse_item(tmp)
            curr = calculate_discount_price(num, val)
        except (TypeError, ValueError) as err:
            errors.append("line %d: %s" % (idx, err))
            continue
        rows.append((name, num, val, curr, round(num - curr, 2)))
    rows.sort(key=lambda row: row[4], reverse=True)
    return rows[:cfg["max_rows"]], errors


def format_report(rows):
    out = ["%-12s %9s %6s %9s %9s" % ("ITEM", "PRICE", "OFF%", "FINAL", "SAVED")]
    total = 0.0
    for name, num, val, curr, saved in rows:
        total += saved
        out.append("%-12s %9.2f %6.1f %9.2f %9.2f"
                   % (name[:12], num, val, curr, saved))
    out.append("items: %d, total saved: %.2f" % (len(rows), total))
    return "\n".join(out)


def main():
    cfg = {"comment": "#", "max_rows": 10}
    data = [
        "# name;price;discount",
        "Notebook;100;10",
        "Mouse;50;20",
        "Keyboard;79.99;15",
        "Monitor;abc;5",
        "Cable;12.5;0",
        "Dock;200;120",
    ]
    rows, errors = build_report(data, cfg)
    print(format_report(rows))
    for msg in errors:
        print("skipped -> " + msg)


if __name__ == "__main__":
    main()

