import math
import sys


def calculate_sphere_volume(radius):
    val = float(radius)
    if val < 0.0:
        raise ValueError("radius must be non-negative")
    return 4.0 / 3.0 * math.pi * val ** 3


def parse_radius(token):
    text = token.strip()
    if not text:
        raise ValueError("empty radius")
    try:
        return float(text)
    except ValueError:
        raise ValueError("not a number: %r" % text)


def collect_radii(tokens):
    res = []
    err = []
    for idx, token in enumerate(tokens):
        try:
            res.append(parse_radius(token))
        except ValueError as exc:
            err.append("argument %d: %s" % (idx + 1, exc))
    return res, err


def format_row(cfg, radius, volume):
    return "%*.*f  %*.*f" % (
        cfg["radius_width"], cfg["digits"], radius,
        cfg["volume_width"], cfg["digits"], volume,
    )


def build_report(cfg, radii):
    buf = []
    prev = None
    for radius in radii:
        curr = calculate_sphere_volume(radius)
        buf.append(format_row(cfg, radius, curr))
        if prev is not None:
            buf.append("growth: %.*f" % (cfg["digits"], curr - prev))
        prev = curr
    buf.append("spheres: %d" % len(radii))
    return "\n".join(buf)


def median_radius(radii):
    ordered = sorted(radii)
    cnt = len(ordered)
    pos = cnt // 2
    if cnt % 2:
        return ordered[pos]
    return 0.5 * (ordered[pos - 1] + ordered[pos])


def main(argv):
    cfg = {"digits": 6, "radius_width": 10, "volume_width": 16}
    tokens = argv[1:]
    if not tokens:
        tokens = ["1.0", "3.0", "0.5"]
    radii, err = collect_radii(tokens)
    for msg in err:
        print(msg, file=sys.stderr)
    if not radii:
        return 1
    print(build_report(cfg, radii))
    print("median radius: %.*f" % (cfg["digits"], median_radius(radii)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

