    if len(parts) != 3:
        raise ValueError("expected YYYY-MM-DD, got %r" % param)
    num = []
    for idx, elem in enumerate(parts):
        tmp = elem.strip()
        if not tmp.isdigit():
            raise ValueError("%s must be numeric, got %r" % (FIELDS[idx], elem))
        num.append(int(tmp))
    return num[0], num[1], num[2]


def days_since(year, month, day):
    """Number of full days between the given past date and today."""
    try:
        target = datetime.date(year, month, day)
    except ValueError as err:
        raise ValueError("invalid date %04d-%02d-%02d: %s" % (year, month, day, err))
    today = datetime.date.today()
    if target > today:
        raise ValueError("%s is in the future" % target.isoformat())
    res = (today - target).days
    return res


def format_row(ctx, label, val):
