SAMPLE = """The quick brown fox jumps over the lazy dog.
The dog barks, and the the fox runs away; the dog sleeps.
Quick quick brown foxes are not not lazy dogs."""


def word_frequency(words):
    res = {}
    for elem in words:
        if not isinstance(elem, str):
            raise TypeError("expected strings, got %r" % (elem,))
        val = elem.strip().lower()
        if not val:
            continue
        res[val] = res.get(val, 0) + 1
    return res


def tokenize(text):
    buf = []
    curr = []
    for ch in text:
        if ch.isalnum() or ch == "'":
            curr.append(ch)
        elif curr:
            buf.append("".join(curr))
            curr = []
    if curr:
        buf.append("".join(curr))
    return buf


def top_words(freq, num):
    tmp = sorted(freq.items(), key=lambda item: (-item[1], item[0]))
    return tmp[:num]


def find_stutters(words):
    res = []
    prev = None
    for pos, elem in enumerate(words):
        curr = elem.lower()
        if curr == prev:
            ctx = " ".join(words[max(0, pos - 2):pos + 1])
            res.append((pos, curr, ctx))
        prev = curr
    return res


def format_report(freq, cfg):
    total = sum(freq.values())
    width = cfg["width"]
    lines = ["distinct=%d total=%d" % (len(freq), total)]
    for idx, (word, cnt) in enumerate(top_words(freq, cfg["limit"]), 1):
        pct = 100.0 * cnt / total
        lines.append("%2d. %-*s %4d %5.1f%%" % (idx, width, word, cnt, pct))
    return "\n".join(lines)


def parse_cfg(argv):
    cfg = {"limit": 10, "width": 12}
    for param in argv:
        key, sep, val = param.partition("=")
        if not sep or key not in cfg:
            raise ValueError("unknown option: " + param)
        try:
            num = int(val)
        except ValueError as err:
            raise ValueError("bad value in %s (%s)" % (param, err))
        if num < 1:
            raise ValueError("%s must be positive" % key)
        cfg[key] = num
    return cfg


def main(argv):
