        cfg = parse_cfg(argv)
    except ValueError as err:
        print("error: %s" % err, file=sys.stderr)
        return 1
    buf = tokenize(SAMPLE)
    freq = word_frequency(buf)
    msg = format_report(freq, cfg)
    print(msg)
    for pos, word, ctx in find_stutters(buf):
        print("stutter at %d: %r in ...%s" % (pos, word, ctx))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

