CFG = {"strong_len": 8, "medium_len": 6, "medium_classes": 2}


def scan_password(param):
    """Collect character-class counts and the longest repeated run."""
    ctx = {
        "length": len(param),
        "upper": 0,
        "lower": 0,
        "digit": 0,
        "other": 0,
        "longest_run": 1 if param else 0,
        "run_start": 0,
    }
    prev = ""
    curr = 0
    for idx, elem in enumerate(param):
        if elem.isupper():
            ctx["upper"] += 1
        elif elem.islower():
            ctx["lower"] += 1
        elif elem.isdigit():
            ctx["digit"] += 1
        else:
            ctx["other"] += 1
        curr = curr + 1 if elem == prev else 1
        if curr > ctx["longest_run"]:
            ctx["longest_run"] = curr
            ctx["run_start"] = idx - curr + 1
        prev = elem
    return ctx


def criteria(ctx, cfg):
    """Return the ordered (name, satisfied) pairs used for the verdict."""
    return [
        ("length >= %d" % cfg["strong_len"], ctx["length"] >= cfg["strong_len"]),
        ("uppercase letter", ctx["upper"] > 0),
        ("lowercase letter", ctx["lower"] > 0),
        ("digit", ctx["digit"] > 0),
    ]


def check_password_strength(password):
    if not isinstance(password, str):
        raise TypeError("password must be a string, got %r" % type(password).__name__)
    ctx = scan_password(password)
    res = criteria(ctx, CFG)
    cnt = sum(1 for name, val in res if val)
    if cnt == len(res):
        return "Strong"
    if ctx["length"] >= CFG["medium_len"] and cnt >= CFG["medium_classes"]:
        return "Medium"
    return "Weak"


def format_report(password):
    ctx = scan_password(password)
    tmp = password[:1] + "*" * max(len(password) - 1, 0)
    buf = ["%s -> %s" % (tmp or "(empty)", check_password_strength(password))]
    num = ctx["length"]
    buf.append("  length: %d, symbols: %d" % (num, ctx["other"]))
    for idx, (name, val) in enumerate(criteria(ctx, CFG), start=1):
        buf.append("  %d. %-18s %s" % (idx, name, "yes" if val else "no"))
    if ctx["longest_run"] > 1:
        pos = ctx["run_start"]
        msg = "  warning: %d repeated characters at position %d" % (ctx["longest_run"], pos)
        buf.append(msg)
    return "\n".join(buf)


def main():
    samples = ["P@ssw0rd", "password", "abc", "Str0ng!!", "aaaaaa1A"]
    for elem in samples:
        print(format_report(elem))


if __name__ == "__main__":
    main()

