import sys


def parse_line(line):
    """Turn a whitespace/comma separated line into a list of integers."""
    buf = line.replace(",", " ").split()
    values = []
    for pos, elem in enumerate(buf):
        try:
            values.append(int(elem))
        except ValueError:
            raise ValueError("token %d (%r) is not an integer" % (pos, elem))
    return values


def validate_sequence(values):
    """Check that the values are distinct and drawn from 1..len(values)+1."""
    num = len(values) + 1
    seen = set()
    for idx, val in enumerate(values):
        if val < 1 or val > num:
            raise ValueError("value %d at index %d is outside 1..%d" % (val, idx, num))
        if val in seen:
            raise ValueError("duplicate value %d at index %d" % (val, idx))
        seen.add(val)


def find_missing_element(values):
    """Return the single number of 1..len(values)+1 absent from the list."""
    validate_sequence(values)
    cnt = len(values)
    res = (cnt + 1) * (cnt + 2) // 2
    for val in values:
        res -= val
    return res


def format_case(idx, line, cfg):
    """Solve one input line and render the answer as a report line."""
    try:
        values = parse_line(line)
        val = find_missing_element(values)
    except ValueError as err:
        return "case %d: invalid input (%s)" % (idx, err)
    msg = "case %d: %d" % (idx, val)
    if cfg["verbose"]:
        msg += " (given %s)" % " ".join(str(elem) for elem in sorted(values))
    return msg


def main(argv):
    """Read one sequence per line from stdin and print the missing numbers."""
    cfg = {"verbose": "-v" in argv or "--verbose" in argv}
    cnt = 0
    for line in sys.stdin:
        if line.strip():
            cnt += 1
            print(format_case(cnt, line, cfg))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

