def is_leap_year(year):
    if not isinstance(year, int) or isinstance(year, bool):
        raise TypeError("year must be an integer")
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def parse_years(text):
    res = []
    for pos, token in enumerate(text.replace(",", " ").split()):
        try:
            val = int(token)
        except ValueError as err:
            msg = "token %d (%r) is not a year: %s" % (pos, token, err)
            raise ValueError(msg)
        res.append(val)
    return res


def leap_years_in(start, end):
    res = []
    for curr in range(start, end + 1):
        if is_leap_year(curr):
            res.append(curr)
    return res


def gap_summary(years):
    """Return (min_gap, max_gap) between consecutive leap years, or None."""
    if len(years) < 2:
        return None
    res = []
    prev = years[0]
    for curr in years[1:]:
        res.append(curr - prev)
        prev = curr
    return min(res), max(res)


def format_report(start, end, per_line):
    years = leap_years_in(start, end)
    cnt = len(years)
    buf = ["range %d-%d: %d leap years" % (start, end, cnt)]
    for idx in range(0, cnt, per_line):
        chunk = years[idx:idx + per_line]
        buf.append("  " + " ".join(str(elem) for elem in chunk))
    gaps = gap_summary(years)
    if gaps is not None:
        buf.append("  gaps: min=%d max=%d" % gaps)
    return "\n".join(buf)


