def parse_date(date_str):
    """Return (year, month, day) for a 'YYYY-MM-DD' string, or raise ValueError."""
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("date must look like YYYY-MM-DD: %r" % date_str)
    num = []
    for idx, elem in enumerate(parts):
        width = 4 if idx == 0 else 2
        if len(elem) != width or not elem.isdigit():
            raise ValueError("bad date component %r in %r" % (elem, date_str))
        num.append(int(elem))
    year, month, day = num
    if not 1 <= month <= 12:
        raise ValueError("month out of range in %r" % date_str)
    leap = year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)
    lengths = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if not 1 <= day <= lengths[month - 1]:
        raise ValueError("day out of range in %r" % date_str)
    return year, month, day


def add_calendar_event(calendar, date_str, event_description):
    """Append event_description to calendar[date_str], creating the list if needed."""
    parse_date(date_str)
    val = event_description.strip()
    if not val:
        raise ValueError("event description must not be empty")
    if date_str not in calendar:
        calendar[date_str] = []
    calendar[date_str].append(val)


def load_events(calendar, lines):
    """Add 'date|description' lines to the calendar; return (added, problems)."""
    cnt = 0
    problems = []
    for num, line in enumerate(lines, start=1):
        tmp = line.strip()
        if not tmp or tmp.startswith('#'):
            continue
        pos = tmp.find('|')
        if pos < 0:
            problems.append("line %d: missing '|' separator" % num)
            continue
        try:
            add_calendar_event(calendar, tmp[:pos].strip(), tmp[pos + 1:])
        except ValueError as err:
            problems.append("line %d: %s" % (num, err))
        else:
            cnt += 1
    return cnt, problems


def format_calendar(calendar):
    """Render the calendar as text, grouped by month and sorted by date."""
    out = []
    prev = None
    for date_str in sorted(calendar):
        curr = parse_date(date_str)[:2]
        if curr != prev:
            out.append("== %04d-%02d ==" % curr)
            prev = curr
        for val in calendar[date_str]:
            out.append("  %s  %s" % (date_str, val))
    return "\n".join(out)


