def is_isomorphic(s, t):
    """Return True if s and t are isomorphic strings."""
    if len(s) != len(t):
        return False
    forward = {}
    backward = {}
    for idx, elem in enumerate(s):
        curr = t[idx]
        prev = forward.get(elem)
        if prev is None:
            if curr in backward:
                return False
            forward[elem] = curr
            backward[curr] = elem
        elif prev != curr:
            return False
    return True


def build_mapping(s, t):
    """Return the character mapping from s to t, or None if not isomorphic."""
    if not is_isomorphic(s, t):
        return None
    res = {}
    for pos, elem in enumerate(s):
        res[elem] = t[pos]
    return res


def format_mapping(mapping):
    """Render a mapping dict as 'a->b, c->d' in sorted key order."""
    buf = []
    for elem in sorted(mapping):
        buf.append("{}->{}".format(elem, mapping[elem]))
    return ", ".join(buf) if buf else "(empty)"


def parse_pair(line):
    """Split a 'word word' line into two strings; raise ValueError on bad input."""
    parts = line.split()
    if len(parts) != 2:
        raise ValueError("expected two words, got {}".format(len(parts)))
    return parts[0], parts[1]


def report(lines):
    """Check each line's word pair and return (report_lines, isomorphic_count)."""
    out = []
    cnt = 0
    for num, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            s, t = parse_pair(line)
        except ValueError as err:
            out.append("line {}: error: {}".format(num, err))
            continue
        val = is_isomorphic(s, t)
        if val:
            cnt += 1
            tmp = build_mapping(s, t)
            msg = "True  [{}]".format(format_mapping(tmp))
        else:
            msg = "False"
        out.append("line {}: {!r} vs {!r} -> {}".format(num, s, t, msg))
    return out, cnt


def main():
    pairs = [
        "egg add",
        "foo bar",
        "paper title",
        "ab aa",
        "badge",
        "  ",
    ]
    out, cnt = report(pairs)
    for msg in out:
        print(msg)
    print("isomorphic pairs: {}".format(cnt))


if __name__ == "__main__":
    main()

