import sys
from typing import NamedTuple


class Layout(NamedTuple):
    idx_width: int
    label_width: int
    precision: int


def power_recursive(base: float, exponent: int) -> float:
    """Compute base ** exponent for a non-negative integer exponent."""
    if exponent < 0:
        raise ValueError("exponent must be non-negative")
    if exponent == 0:
        return 1.0
    half = power_recursive(base, exponent // 2)
    res = half * half
    if exponent % 2:
        res *= base
    return float(res)


def parse_param(param: str) -> tuple:
    """Turn a 'base,exponent' argument into a (float, int) pair."""
    tmp = param.split(",")
    if len(tmp) != 2:
        msg = "expected two comma-separated fields: base,exponent"
        raise ValueError(msg)
    try:
        val = float(tmp[0].strip())
        num = int(tmp[1].strip())
    except ValueError as err:
        raise ValueError(f"malformed number ({err})")
    if num < 0:
        raise ValueError(f"exponent {num} is negative")
    return val, num


def describe_chain(exponent: int) -> list:
    """Describe the squaring chain the recursion walks through."""
    if exponent == 0:
        return ["step 0: exponent 0 (empty product, result 1)"]
    chain = []
    curr = exponent
    while curr > 0:
        chain.append(curr)
        curr //= 2
    buf = []
    prev = 0
    for pos, elem in enumerate(reversed(chain)):
        if prev == 0:
            op = "base"
        elif elem == 2 * prev:
            op = "square"
        else:
            op = "square and multiply by base"
        buf.append(f"step {pos}: exponent {elem} ({op})")
        prev = elem
    return buf


def format_row(cfg: Layout, idx: int, base: float, exponent: int, res: float) -> str:
    label = f"{base:g}^{exponent}"
    return (f"{idx:>{cfg.idx_width}}  {label:<{cfg.label_width}}"
            f" = {res:.{cfg.precision}f}")


def main(argv: list) -> int:
    cfg = Layout(idx_width=3, label_width=14, precision=4)
    args = argv[1:]
    cnt = len(args)
    if cnt == 0:
        print(f"usage: {argv[0]} base,exponent [base,exponent ...]", file=sys.stderr)
        return 2
    ctx = {"ok": 0, "bad": 0}
    for idx, param in enumerate(args, 1):
        try:
            base, num = parse_param(param)
        except ValueError as err:
            print(f"{param!r}: {err}", file=sys.stderr)
            ctx["bad"] += 1
            continue
        res = power_recursive(base, num)
        print(format_row(cfg, idx, base, num, res))
        for elem in describe_chain(num):
            print("      " + elem)
        ctx["ok"] += 1
    print(f"processed {cnt} argument(s): {ctx['ok']} computed, {ctx['bad']} rejected")
    return 1 if ctx["bad"] else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

