import random
from collections import Counter


def roll_die() -> int:
    """Return a random integer between 1 and 6 inclusive."""
    return random.randint(1, 6)


def roll_many(num: int) -> list:
    """Roll the die the requested number of times and return the results."""
    if num < 0:
        raise ValueError("cannot roll a negative number of times")
    return [roll_die() for _ in range(num)]


def tally(rolls: list) -> dict:
    """Count how often each face appeared."""
    cnt = Counter(rolls)
    return {face: cnt.get(face, 0) for face in range(1, 7)}


def longest_streak(rolls: list) -> tuple:
    """Return (face, length) of the longest run of identical rolls."""
    if not rolls:
        return (None, 0)
    best = (rolls[0], 1)
    prev = rolls[0]
    curr = 1
    for pos in range(1, len(rolls)):
        elem = rolls[pos]
        if elem == prev:
            curr += 1
        else:
            prev = elem
            curr = 1
        if curr > best[1]:
            best = (elem, curr)
    return best


def format_report(rolls: list, width: int = 40) -> str:
    """Build a text histogram plus summary lines for the given rolls."""
    counts = tally(rolls)
    total = len(rolls)
    peak = max(counts.values()) if total else 0
    buf = []
    for face, val in counts.items():
        bar_width = 0 if peak == 0 else round(val * width / peak)
        percent = 0.0 if total == 0 else 100.0 * val / total
        buf.append("%d | %-*s %4d (%5.1f%%)" % (face, width, "#" * bar_width, val, percent))
    if total:
        average = sum(rolls) / total
        face, length = longest_streak(rolls)
        buf.append("mean = %.3f (expected 3.500)" % average)
        buf.append("longest streak: %d x %d" % (length, face))
    return "\n".join(buf)


def main(argv: list) -> int:
    cfg = {"trials": 600, "seed": None}
    for idx, param in enumerate(argv):
        if param in ("-n", "--trials"):
            cfg["trials"] = int(argv[idx + 1])
        elif param in ("-s", "--seed"):
            cfg["seed"] = int(argv[idx + 1])
    if cfg["seed"] is not None:
        random.seed(cfg["seed"])
    try:
        res = roll_many(cfg["trials"])
    except ValueError as err:
        msg = "error: %s" % err
        print(msg)
        return 1
    print("single roll: %d" % roll_die())
    print(format_report(res))
    return 0


if __name__ == "__main__":
    import sys

    raise SystemExit(main(sys.argv[1:]))

